class V42ExpProtectedRecoverySleeveV1Strategy(V42ExpBtcTcOffBaseExitStrategy):
    """Small no-leverage test: protect part of existing low recovery buys from ordinary main sells."""

    PROTECTED_RECOVERY_SETUPS = {"recovery-probe-buy", "value-recovery"}
    PROTECTED_RECOVERY_FRACTION = 0.50
    PROTECTED_RECOVERY_CAP = {"BTC/USDT": 0.10, "ETH/USDT": 0.10, "BNB/USDT": 0.06}
    PROTECTED_RECOVERY_PORTFOLIO_CAP = 0.22
    PROTECTED_RECOVERY_HARD_STOP = 0.70

    @property
    def name(self) -> str:
        return "v4_2_exp_protected_recovery_sleeve_v1"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._protected_recovery_by_symbol: dict[str, dict] = {}
        self._protected_recovery_events: list[dict] = []

    def strategy_protected_recovery_events(self) -> list[dict]:
        return list(self._protected_recovery_events)

    def _main_quantity(self, context: V42Context) -> float:
        main_qty = super()._main_quantity(context)
        if self._protected_recovery_exit_allowed(context):
            return main_qty
        return max(0.0, main_qty - self._protected_recovery_quantity(context))

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        exit_allowed = self._protected_recovery_exit_allowed(context)
        unprotected_before = max(0.0, super()._main_quantity(context) - self._protected_recovery_quantity(context))
        super()._record_event(context, regime, episode, decision, sizing, action)
        if action is None:
            return
        if action.side == "buy" and self._should_protect_recovery_buy(context, regime, episode, decision, sizing, action):
            self._record_protected_recovery_buy(context, regime, episode, sizing, action)
            return
        if action.side == "sell" and exit_allowed:
            protected_sell_qty = max(0.0, float(action.quantity) - unprotected_before)
            if protected_sell_qty > 1e-12:
                self._consume_protected_recovery(context, sizing, action, protected_sell_qty, "hard_stop")

    def _should_protect_recovery_buy(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action,
    ) -> bool:
        if sizing.setup not in self.PROTECTED_RECOVERY_SETUPS:
            return False
        if self._is_bear_base_buy(decision, sizing):
            return False
        if context.price <= 0.0 or context.total_value <= 0.0:
            return False
        if not self._protected_recovery_low_location(context, regime):
            return False
        if regime.btc_regime == "BEAR" and context.trend_risk >= 2:
            return False
        if self._protected_recovery_pct(context) >= self._protected_recovery_asset_cap(context.symbol) - self.RECOVERY_MIN_STEP:
            return False
        if self._protected_recovery_portfolio_pct(context) >= self.PROTECTED_RECOVERY_PORTFOLIO_CAP - self.RECOVERY_MIN_STEP:
            return False
        return bool(action.quantity > 1e-12)

    def _record_protected_recovery_buy(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        sizing: V42Sizing,
        action: Action,
    ) -> None:
        room_asset = max(0.0, self._protected_recovery_asset_cap(context.symbol) - self._protected_recovery_pct(context))
        room_portfolio = max(0.0, self.PROTECTED_RECOVERY_PORTFOLIO_CAP - self._protected_recovery_portfolio_pct(context))
        action_pct = action.quantity * action.price / context.total_value if context.total_value > 0.0 else 0.0
        protect_pct = min(max(0.0, action_pct * self.PROTECTED_RECOVERY_FRACTION), room_asset, room_portfolio)
        if protect_pct <= 1e-12:
            return
        protect_qty = protect_pct * context.total_value / action.price
        ledger = self._protected_recovery_by_symbol.setdefault(
            context.symbol,
            {"quantity": 0.0, "avg_entry": 0.0, "entry_low": context.price, "entry_call": self._call_count},
        )
        old_qty = float(ledger.get("quantity", 0.0) or 0.0)
        old_entry = float(ledger.get("avg_entry", context.price) or context.price)
        new_qty = old_qty + protect_qty
        ledger["quantity"] = new_qty
        ledger["avg_entry"] = (old_entry * old_qty + context.price * protect_qty) / new_qty if new_qty > 0.0 else 0.0
        ledger["entry_low"] = min(float(ledger.get("entry_low", context.price) or context.price), context.price)
        ledger["last_buy_call"] = self._call_count
        self._diag["v4_2_protected_recovery_buy_count"] = self._diag.get("v4_2_protected_recovery_buy_count", 0) + 1
        self._protected_recovery_events.append(self._protected_recovery_event_row(
            context=context,
            sizing=sizing,
            event="protect_buy",
            quantity=protect_qty,
            price=action.price,
            reason=sizing.setup,
        ))

    def _consume_protected_recovery(
        self,
        context: V42Context,
        sizing: V42Sizing,
        action: Action,
        quantity: float,
        reason: str,
    ) -> None:
        ledger = self._protected_recovery_by_symbol.get(context.symbol)
        if not ledger:
            return
        consume = min(max(0.0, quantity), self._protected_recovery_quantity(context))
        if consume <= 1e-12:
            return
        remaining = max(0.0, float(ledger.get("quantity", 0.0) or 0.0) - consume)
        ledger["quantity"] = remaining
        if remaining <= 1e-12:
            ledger["quantity"] = 0.0
            ledger["avg_entry"] = 0.0
        self._diag["v4_2_protected_recovery_sell_count"] = self._diag.get("v4_2_protected_recovery_sell_count", 0) + 1
        self._protected_recovery_events.append(self._protected_recovery_event_row(
            context=context,
            sizing=sizing,
            event="protect_sell",
            quantity=consume,
            price=action.price,
            reason=reason,
        ))

    def _protected_recovery_quantity(self, context: V42Context) -> float:
        ledger = self._protected_recovery_by_symbol.get(context.symbol, {})
        qty = max(0.0, float(ledger.get("quantity", 0.0) or 0.0))
        return min(qty, max(0.0, super()._main_quantity(context)))

    def _protected_recovery_pct(self, context: V42Context) -> float:
        if context.total_value <= 0.0 or context.price <= 0.0:
            return 0.0
        return self._protected_recovery_quantity(context) * context.price / context.total_value

    def _protected_recovery_portfolio_pct(self, context: V42Context) -> float:
        total = 0.0
        for symbol, ledger in self._protected_recovery_by_symbol.items():
            qty = max(0.0, float(ledger.get("quantity", 0.0) or 0.0))
            if symbol == context.symbol:
                price = context.price
                total_value = context.total_value
            else:
                price = float(ledger.get("last_price", 0.0) or 0.0)
                total_value = context.total_value
            if price > 0.0 and total_value > 0.0:
                total += qty * price / total_value
        return total

    def _protected_recovery_exit_allowed(self, context: V42Context) -> bool:
        ledger = self._protected_recovery_by_symbol.get(context.symbol)
        if not ledger or float(ledger.get("quantity", 0.0) or 0.0) <= 1e-12:
            return False
        entry_low = float(ledger.get("entry_low", context.price) or context.price)
        return bool(entry_low > 0.0 and context.price <= entry_low * self.PROTECTED_RECOVERY_HARD_STOP)

    def _protected_recovery_low_location(self, context: V42Context, regime: V42Regime) -> bool:
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.35)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.35)
            or (not pd.isna(regime.price_vs_ema168) and regime.price_vs_ema168 <= -0.15)
        )

    def _protected_recovery_asset_cap(self, symbol: str) -> float:
        return max(0.0, float(self.PROTECTED_RECOVERY_CAP.get(symbol, 0.0)))

    def _protected_recovery_event_row(
        self,
        *,
        context: V42Context,
        sizing: V42Sizing,
        event: str,
        quantity: float,
        price: float,
        reason: str,
    ) -> dict:
        ledger = self._protected_recovery_by_symbol.get(context.symbol, {})
        ledger["last_price"] = context.price
        protected_qty = self._protected_recovery_quantity(context)
        return {
            "timestamp": context.latest.get("timestamp"),
            "symbol": context.symbol,
            "event": event,
            "setup": sizing.setup,
            "reason": reason,
            "quantity": float(quantity),
            "price": float(price),
            "notional": float(quantity) * float(price),
            "protected_quantity_after": protected_qty,
            "protected_pct_after": self._protected_recovery_pct(context),
            "main_quantity_visible_after": max(0.0, super()._main_quantity(context) - protected_qty),
            "avg_entry": float(ledger.get("avg_entry", 0.0) or 0.0),
            "entry_low": float(ledger.get("entry_low", 0.0) or 0.0),
        }


class V42ExpRecoveryOverlayExecV1Strategy(V42ExpBtcTcOffBaseExitStrategy):
    """Execution-only recovery overlay on top of the clean no-leverage V4.2 strategy."""

    EXECUTION_TRANSFORM_BORROW_APR = 0.10
    EXECUTION_TRANSFORM_MIN_TARGET_GAP = 0.005
    EXECUTION_TRANSFORM_MIN_NOTIONAL = 5.0
    EXECUTION_TRANSFORM_MAINTENANCE_MARGIN = 0.25
    EXECUTION_TRANSFORM_WARNING_GROSS = 1.15

    RECOVERY_OVERLAY_CAP = {"BTC/USDT": 0.12, "ETH/USDT": 0.12, "BNB/USDT": 0.08}
    RECOVERY_OVERLAY_PORTFOLIO_CAP = 0.25
    RECOVERY_OVERLAY_TOTAL_CAP = 1.20
    RECOVERY_OVERLAY_MIN_RAW = 0.15

    @property
    def name(self) -> str:
        return "v4_2_exp_recovery_overlay_exec_v1"

    def execution_target_for_symbol(
        self,
        symbol: str,
        raw_position_pct: float,
        candles_by_symbol: dict[str, pd.DataFrame],
        current_prices: dict[str, float],
    ) -> float:
        target, _reason = self.execution_transform_diagnostics_for_symbol(
            symbol=symbol,
            raw_position_pct=raw_position_pct,
            candles_by_symbol=candles_by_symbol,
            current_prices=current_prices,
        )
        return target

    def execution_transform_diagnostics_for_symbol(
        self,
        symbol: str,
        raw_position_pct: float,
        candles_by_symbol: dict[str, pd.DataFrame],
        current_prices: dict[str, float],
    ) -> tuple[float, str]:
        raw = max(0.0, float(raw_position_pct))
        overlay, reason = self._recovery_overlay_pct(symbol, raw, candles_by_symbol)
        return min(self.RECOVERY_OVERLAY_TOTAL_CAP, raw + overlay), reason

    def _recovery_overlay_pct(
        self,
        symbol: str,
        raw: float,
        candles_by_symbol: dict[str, pd.DataFrame],
    ) -> tuple[float, str]:
        if raw < self.RECOVERY_OVERLAY_MIN_RAW:
            return 0.0, "raw_below_overlay_min"
        df = candles_by_symbol.get(symbol)
        if df is None or len(df) < 90:
            return 0.0, "insufficient_history"
        latest = df.iloc[-1]
        if self._recovery_overlay_risk_off(latest):
            return 0.0, "risk_off"
        score = self._recovery_overlay_score(df)
        if score < 4.0:
            return 0.0, "overlay_score_low"
        raw_overlay = 0.04
        if score >= 5.0:
            raw_overlay = 0.08
        if score >= 6.0:
            raw_overlay = 0.12
        asset_cap = max(0.0, float(self.RECOVERY_OVERLAY_CAP.get(symbol, 0.0)))
        overlay = min(raw_overlay, asset_cap, max(0.0, self.RECOVERY_OVERLAY_TOTAL_CAP - raw))
        if overlay <= 1e-12:
            return 0.0, "overlay_cap_filled"
        return overlay, "recovery_overlay"

    def _recovery_overlay_score(self, df: pd.DataFrame) -> float:
        close = pd.to_numeric(df["close"], errors="coerce")
        rolling_pos = self._exec_position_in_window(close, 365)
        donchian_pos = self._exec_position_in_window(close, 20)
        dd_180 = self._exec_drawdown_from_high(close, 180)
        dd_365 = self._exec_drawdown_from_high(close, 365)
        rebound_20 = self._exec_rebound_from_low(close, 20)
        roc_5 = self._exec_series_ratio(close, 5)
        roc_10 = self._exec_series_ratio(close, 10)
        roc_20 = self._exec_series_ratio(close, 20)

        score = 0.0
        low_pos = min(rolling_pos, donchian_pos)
        if low_pos <= 0.15:
            score += 2.0
        elif low_pos <= 0.35:
            score += 1.0
        if dd_365 <= -0.55:
            score += 1.5
        elif dd_180 <= -0.35:
            score += 1.0
        if roc_20 <= -0.20:
            score += 1.0
        if rebound_20 >= 0.08:
            score += 1.0
        if roc_5 >= -0.04:
            score += 0.5
        if roc_10 >= 0.0:
            score += 0.5
        return float(score)

    @staticmethod
    def _recovery_overlay_risk_off(latest: pd.Series) -> bool:
        btc_regime = str(latest.get("btc_regime", "") or "")
        btc_roc_20 = latest.get("btc_roc_20", 0.0)
        btc_price_vs_ema168 = latest.get("btc_price_vs_ema168", 0.0)
        return bool(
            btc_regime == "BEAR"
            and (pd.isna(btc_roc_20) or float(btc_roc_20) <= -0.08)
            and (pd.isna(btc_price_vs_ema168) or float(btc_price_vs_ema168) <= -0.15)
        )

    @staticmethod
    def _exec_position_in_window(series: pd.Series, window: int) -> float:
        values = pd.to_numeric(series, errors="coerce").dropna().tail(window)
        if values.empty:
            return 0.5
        low = float(values.min())
        high = float(values.max())
        if high <= low:
            return 0.5
        return float((values.iloc[-1] - low) / (high - low))

    @staticmethod
    def _exec_series_ratio(series: pd.Series, periods: int) -> float:
        values = pd.to_numeric(series, errors="coerce").dropna()
        if len(values) <= periods or values.iloc[-periods - 1] <= 0.0:
            return 0.0
        return float(values.iloc[-1] / values.iloc[-periods - 1] - 1.0)

    @staticmethod
    def _exec_drawdown_from_high(series: pd.Series, window: int) -> float:
        values = pd.to_numeric(series, errors="coerce").dropna().tail(window)
        if values.empty or values.max() <= 0.0:
            return 0.0
        return float(values.iloc[-1] / values.max() - 1.0)

    @staticmethod
    def _exec_rebound_from_low(series: pd.Series, window: int) -> float:
        values = pd.to_numeric(series, errors="coerce").dropna().tail(window)
        if values.empty or values.min() <= 0.0:
            return 0.0
        return float(values.iloc[-1] / values.min() - 1.0)


