class V42ExpRecoveryBudgetReconcileV1Strategy(V42ExpBtcTcOffBaseExitStrategy):
    """V4.2 experiment: keep recovery cycles open until cumulative budget is materially restored."""

    RECOVERY_CONFIRM_MIN_BUDGET_RATIO = 0.50

    @property
    def name(self) -> str:
        return "v4_2_exp_recovery_budget_reconcile_v1"

    def _update_episode(self, context: V42Context, regime: V42Regime) -> dict:
        symbol = context.symbol
        price = context.price
        episode = self._episodes_by_symbol.get(symbol)
        if episode is not None:
            episode["lowest_price"] = min(float(episode.get("lowest_price", price)), price)
            episode["cycle_lowest_price"] = min(float(episode.get("cycle_lowest_price", episode.get("lowest_price", price)) or price), price)
            episode["last_call"] = self._call_count
            if self._call_count - int(episode.get("start_call", self._call_count)) > self.EPISODE_MAX_CALLS:
                self._close_episode(symbol, "expired")
                episode = None

        if episode is None:
            return {"state": "NORMAL"}

        state = str(episode.get("state", "NORMAL"))
        age = self._call_count - int(episode.get("start_call", self._call_count))
        if state == "RECOVERY_TEST":
            recovery_start = int(episode.get("recovery_start_call", episode.get("start_call", self._call_count)) or self._call_count)
            recovery_age = self._call_count - recovery_start
            if self._recovery_quality_ok(context, regime) and recovery_age >= self.RECOVERY_TEST_CALLS:
                if self._recovery_budget_reconciled(episode):
                    self._close_episode(symbol, "recovery_confirmed_budget_reconciled")
                    return {"state": "NORMAL"}
                self._diag["v4_2_recovery_budget_confirm_blocked_count"] = (
                    self._diag.get("v4_2_recovery_budget_confirm_blocked_count", 0) + 1
                )
                episode["blocked_reason"] = self._join_guard(
                    str(episode.get("blocked_reason", "")),
                    "recovery_budget_open",
                )
            if regime.regime == "BEAR" or self._failed_recovery(context, episode):
                episode["state"] = "FAILED_RECOVERY_LOCK"
                episode["blocked_reason"] = self._join_guard(str(episode.get("blocked_reason", "")), "failed_recovery")
        elif state == "FAILED_RECOVERY_LOCK":
            if age >= self.FAILED_RECOVERY_CALLS and self._recovery_quality_ok(context, regime):
                episode["state"] = "RECOVERY_TEST"
        elif state == "DISTRIBUTION_LOCK":
            if age >= self.DISTRIBUTION_LOCK_CALLS and not self._distribution_exhaustion(context, regime):
                self._close_episode(symbol, "distribution_cooled")
                return {"state": "NORMAL"}
        elif state == "STRUCTURAL_BEAR_LOCK":
            if age >= self.FAILED_RECOVERY_CALLS and self._recovery_quality_ok(context, regime):
                episode["state"] = "RECOVERY_TEST"

        return episode

    def _episode_recovery_budget(self, episode: dict) -> float:
        cumulative = float(episode.get("cumulative_sold_pct", 0.0) or 0.0)
        if cumulative > 0.0 and self._is_protective_setup(str(episode.get("setup", ""))):
            return cumulative
        return super()._episode_recovery_budget(episode)

    @staticmethod
    def _episode_recovered_pct(episode: dict) -> float:
        cumulative = float(episode.get("cumulative_recovered_pct", 0.0) or 0.0)
        if cumulative > 0.0:
            return max(0.0, cumulative)
        return max(0.0, float(episode.get("recovery_bought_pct", 0.0) or 0.0))

    def _recovery_budget_reconciled(self, episode: dict) -> bool:
        budget = self._episode_recovery_budget(episode)
        if budget < self.RECOVERY_MIN_STEP:
            return True
        recovered = self._episode_recovered_pct(episode)
        if budget - recovered <= self.RECOVERY_MIN_STEP:
            return True
        return recovered / max(budget, 1e-12) >= self.RECOVERY_CONFIRM_MIN_BUDGET_RATIO


class V42RecoveryBudgetLabelAuditV1Strategy(V42ExpBtcTcOffBaseExitStrategy):
    """V4.2 audit: label signal recovery separately from budget recovery without changing actions."""

    RECOVERY_CONFIRM_MIN_BUDGET_RATIO = 0.50

    @property
    def name(self) -> str:
        return "v4_2_recovery_budget_label_audit_v1"

    def _close_episode(self, symbol: str, reason: str) -> None:
        episode = self._episodes_by_symbol.pop(symbol, None)
        if episode is None:
            return
        budget = self._cycle_recovery_budget(episode)
        recovered = self._cycle_recovered_pct(episode)
        open_budget = max(0.0, budget - recovered)
        ratio = recovered / budget if budget > 1e-12 else 1.0
        reconciled = bool(open_budget <= self.RECOVERY_MIN_STEP or ratio >= self.RECOVERY_CONFIRM_MIN_BUDGET_RATIO)
        if reason == "recovery_confirmed" and not reconciled:
            reason = "recovery_signal_confirmed_budget_open"
            self._diag["v4_2_recovery_signal_confirmed_budget_open_count"] = (
                self._diag.get("v4_2_recovery_signal_confirmed_budget_open_count", 0) + 1
            )
        episode["budget_recovery_ratio"] = ratio
        episode["budget_open_pct"] = open_budget
        episode["budget_reconciled"] = reconciled
        episode["close_reason"] = reason
        episode["close_call"] = self._call_count
        episode["state"] = "CLOSED"
        self._episode_log.append(dict(episode))
        self._diag["v4_2_episode_closed_count"] += 1

    def _episode_row(self, episode: dict) -> dict:
        row = super()._episode_row(episode)
        budget = self._cycle_recovery_budget(episode)
        recovered = self._cycle_recovered_pct(episode)
        open_budget = max(0.0, budget - recovered)
        row["budget_recovery_ratio"] = recovered / budget if budget > 1e-12 else 1.0
        row["budget_open_pct"] = open_budget
        row["budget_reconciled"] = bool(open_budget <= self.RECOVERY_MIN_STEP or row["budget_recovery_ratio"] >= self.RECOVERY_CONFIRM_MIN_BUDGET_RATIO)
        return row

    @staticmethod
    def _cycle_recovery_budget(episode: dict) -> float:
        cumulative = float(episode.get("cumulative_sold_pct", 0.0) or 0.0)
        if cumulative > 0.0:
            return cumulative
        budget = float(episode.get("recovery_budget_pct", 0.0) or 0.0)
        if budget > 0.0:
            return budget
        return max(
            0.0,
            float(episode.get("sell_position_pct", 0.0) or 0.0)
            - float(episode.get("sell_target_pct", 0.0) or 0.0),
        )

    @staticmethod
    def _cycle_recovered_pct(episode: dict) -> float:
        cumulative = float(episode.get("cumulative_recovered_pct", 0.0) or 0.0)
        if cumulative > 0.0:
            return cumulative
        return max(0.0, float(episode.get("recovery_bought_pct", 0.0) or 0.0))


class V42ExpRecoveryCreditSoftV1Strategy(V42RecoveryBudgetLabelAuditV1Strategy):
    """V4.2 experiment: carry open recovery budget as soft future buy credit."""

    RECOVERY_CREDIT_ALLOWED_CLOSE_REASONS: set[str] | None = None
    RECOVERY_CREDIT_SYMBOL_CAP = 0.30
    RECOVERY_CREDIT_PORTFOLIO_AVG_CAP = 0.18
    RECOVERY_CREDIT_DECAY_CALLS = 180
    RECOVERY_CREDIT_DECAY_FRACTION = 0.25
    RECOVERY_CREDIT_DROP_MIN = {
        "BTC/USDT": 0.04,
        "ETH/USDT": 0.04,
        "BNB/USDT": 0.04,
    }
    RECOVERY_CREDIT_ROLLING_POS_MAX = {
        "BTC/USDT": 0.55,
        "ETH/USDT": 0.55,
        "BNB/USDT": 0.55,
    }
    RECOVERY_CREDIT_DONCHIAN_POS_MAX = {
        "BTC/USDT": 0.60,
        "ETH/USDT": 0.60,
        "BNB/USDT": 0.60,
    }
    RECOVERY_CREDIT_RELEASE_CAP = {
        "BTC/USDT": 0.04,
        "ETH/USDT": 0.05,
        "BNB/USDT": 0.04,
    }

    @property
    def name(self) -> str:
        return "v4_2_exp_recovery_credit_soft_v1"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._recovery_credit_ledger: dict[str, dict] = {}
        self._recovery_credit_events: list[dict] = []
        self._recovery_credit_checks: list[dict] = []
        self._current_context_by_symbol: dict[str, V42Context] = {}

    def strategy_recovery_credit_events(self) -> list[dict]:
        return list(self._recovery_credit_events)

    def strategy_recovery_credit_checks(self) -> list[dict]:
        return list(self._recovery_credit_checks)

    def _update_episode(self, context: V42Context, regime: V42Regime) -> dict:
        self._current_context_by_symbol[context.symbol] = context
        return super()._update_episode(context, regime)

    def _build_decision_snapshot(
        self,
        candles_by_symbol: dict[str, pd.DataFrame],
        portfolio: PortfolioState,
        current_prices: dict[str, float],
    ) -> V42DecisionSnapshot | None:
        snapshot = super()._build_decision_snapshot(candles_by_symbol, portfolio, current_prices)
        if snapshot is not None:
            self._current_context_by_symbol[snapshot.context.symbol] = snapshot.context
        return snapshot

    def _close_episode(self, symbol: str, reason: str) -> None:
        episode = self._episodes_by_symbol.pop(symbol, None)
        if episode is None:
            return
        budget = self._cycle_recovery_budget(episode)
        recovered = self._cycle_recovered_pct(episode)
        open_budget = max(0.0, budget - recovered)
        ratio = recovered / budget if budget > 1e-12 else 1.0
        reconciled = bool(open_budget <= self.RECOVERY_MIN_STEP or ratio >= self.RECOVERY_CONFIRM_MIN_BUDGET_RATIO)
        if reason == "recovery_confirmed" and not reconciled:
            reason = "recovery_signal_confirmed_budget_open"
            self._diag["v4_2_recovery_signal_confirmed_budget_open_count"] = (
                self._diag.get("v4_2_recovery_signal_confirmed_budget_open_count", 0) + 1
            )
        episode["budget_recovery_ratio"] = ratio
        episode["budget_open_pct"] = open_budget
        episode["budget_reconciled"] = reconciled
        episode["close_reason"] = reason
        episode["close_call"] = self._call_count
        episode["state"] = "CLOSED"
        allowed_reasons = self.RECOVERY_CREDIT_ALLOWED_CLOSE_REASONS
        source_allowed = allowed_reasons is None or reason in allowed_reasons
        if open_budget > self.RECOVERY_MIN_STEP and source_allowed:
            self._open_recovery_credit(symbol, episode, open_budget, reason)
        self._episode_log.append(dict(episode))
        self._diag["v4_2_episode_closed_count"] += 1

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        self._decay_recovery_credit(context)
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        if sizing.side or str(sizing.blocked_reason or "") not in {"", "target_reached"}:
            return sizing
        if str(getattr(decision, "main_intent", decision.intent)) not in {"HOLD", "ACCUMULATE"}:
            return sizing
        credit_sizing = self._recovery_credit_sizing(context, regime, signals)
        if credit_sizing.side or credit_sizing.blocked_reason:
            return credit_sizing if credit_sizing.side else sizing
        return sizing

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "buy" and "v4_2_recovery_credit_soft" in str(sizing.guard):
            self._release_recovery_credit(context, sizing)

    def _build_action(self, context: V42Context, regime: V42Regime, decision: V42DecisionPlan, sizing: V42Sizing) -> Action | None:
        action = super()._build_action(context, regime, decision, sizing)
        if action is None:
            return None
        diagnostics = dict(getattr(action, "diagnostics", {}) or {})
        for key in (
            "recovery_credit_before",
            "recovery_credit_used",
            "recovery_credit_after",
            "recovery_credit_anchor_price",
        ):
            if hasattr(sizing, key):
                diagnostics[key] = float(getattr(sizing, key) or 0.0)
        action.diagnostics = diagnostics
        return action

    def _open_recovery_credit(self, symbol: str, episode: dict, open_budget: float, reason: str) -> None:
        before = float(self._recovery_credit_ledger.get(symbol, {}).get("remaining", 0.0) or 0.0)
        symbol_room = max(0.0, self.RECOVERY_CREDIT_SYMBOL_CAP - before)
        portfolio_room = max(0.0, self._recovery_credit_portfolio_cap() - self._recovery_credit_total())
        delta = min(open_budget, symbol_room, portfolio_room)
        anchor = float(episode.get("avg_sell_price", episode.get("sell_price", 0.0)) or 0.0)
        if delta > 0.0:
            ledger = dict(self._recovery_credit_ledger.get(symbol, {}))
            prior_anchor = float(ledger.get("anchor_price", anchor) or anchor)
            prior_remaining = before
            after = before + delta
            ledger.update({
                "remaining": after,
                "anchor_price": (
                    (prior_anchor * prior_remaining + anchor * delta) / after
                    if after > 0.0 and prior_anchor > 0.0 and anchor > 0.0
                    else anchor or prior_anchor
                ),
                "opened_call": int(ledger.get("opened_call", self._call_count) or self._call_count),
                "last_decay_call": self._call_count,
                "episode_id": episode.get("episode_id", ""),
                "source_close_reason": reason,
            })
            source_ids = list(ledger.get("source_episode_ids", []) or [])
            source_ids.append(episode.get("episode_id", ""))
            ledger["source_episode_ids"] = [item for item in source_ids if item]
            self._recovery_credit_ledger[symbol] = ledger
            self._record_recovery_credit_event(
                symbol=symbol,
                event="credit_opened",
                episode=episode,
                source_close_reason=reason,
                credit_before=before,
                credit_delta=delta,
                credit_after=after,
                anchor_price=float(ledger.get("anchor_price", 0.0) or 0.0),
                guard="",
                blocked_reason="",
            )
        if open_budget - delta > 1e-12:
            self._record_recovery_credit_event(
                symbol=symbol,
                event="credit_capped",
                episode=episode,
                source_close_reason=reason,
                credit_before=before + delta,
                credit_delta=0.0,
                credit_after=before + delta,
                anchor_price=anchor,
                guard="",
                blocked_reason="credit_cap",
            )

    def _decay_recovery_credit(self, context: V42Context) -> None:
        ledger = self._recovery_credit_ledger.get(context.symbol)
        if not ledger:
            return
        remaining = float(ledger.get("remaining", 0.0) or 0.0)
        if remaining <= self.RECOVERY_MIN_STEP:
            return
        last_decay = int(ledger.get("last_decay_call", ledger.get("opened_call", self._call_count)) or self._call_count)
        periods = (self._call_count - last_decay) // self.RECOVERY_CREDIT_DECAY_CALLS
        if periods <= 0:
            return
        before = remaining
        for _ in range(periods):
            remaining *= 1.0 - self.RECOVERY_CREDIT_DECAY_FRACTION
        ledger["remaining"] = remaining
        ledger["last_decay_call"] = last_decay + periods * self.RECOVERY_CREDIT_DECAY_CALLS
        self._recovery_credit_ledger[context.symbol] = ledger
        self._record_recovery_credit_event(
            symbol=context.symbol,
            event="credit_decayed",
            episode={"episode_id": ledger.get("episode_id", "")},
            source_close_reason=str(ledger.get("source_close_reason", "")),
            credit_before=before,
            credit_delta=remaining - before,
            credit_after=remaining,
            anchor_price=float(ledger.get("anchor_price", 0.0) or 0.0),
            guard="",
            blocked_reason="",
        )

    def _recovery_credit_sizing(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> V42Sizing:
        plan = self._recovery_credit_plan(context, regime, signals)
        if not bool(plan.get("allowed", False)):
            return V42Sizing(blocked_reason=str(plan.get("blocked_reason", "")))
        credit_before = float(plan.get("remaining_budget", 0.0) or 0.0)
        cooldown = max(self._buy_cooldown(context, regime, "recovery-probe-buy"), 8)
        last_buy = self._last_buy_call_by_symbol.get(context.symbol, -10_000)
        if self._call_count - last_buy < cooldown:
            self._diag["v4_2_cooldown_blocked_count"] += 1
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="cooldown")
        release_cap = self.RECOVERY_CREDIT_RELEASE_CAP.get(context.symbol, 0.04)
        buy_pct = min(credit_before, release_cap)
        buy_qty = context.total_value * buy_pct / context.price
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="min_notional")
        guard = self._join_guard(self._sizing_guard(context, regime, {"state": "NORMAL"}, "recovery-probe-buy"), "v4_2_recovery_credit_soft")
        target = min(self.TARGET_CAP, context.current_pct + buy_pct)
        sizing = V42Sizing(
            side="buy",
            setup="recovery-probe-buy",
            quantity=buy_qty,
            target=target,
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=buy_pct,
            actual_step_pct=buy_pct,
            remaining_gap_after=0.0,
        )
        setattr(sizing, "recovery_credit_before", credit_before)
        setattr(sizing, "recovery_credit_used", buy_pct)
        setattr(sizing, "recovery_credit_after", max(0.0, credit_before - buy_pct))
        setattr(sizing, "recovery_credit_anchor_price", float(plan.get("target", 0.0) or 0.0))
        return sizing

    def _recovery_credit_plan(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> V42RecoveryPlan:
        ledger = self._recovery_credit_ledger.get(context.symbol)
        if not ledger or float(ledger.get("remaining", 0.0) or 0.0) <= self.RECOVERY_MIN_STEP:
            return V42RecoveryPlan(blocked_reason="no_recovery_credit")
        remaining = float(ledger.get("remaining", 0.0) or 0.0)
        anchor = float(ledger.get("anchor_price", 0.0) or 0.0)
        current_drop = max(0.0, 1.0 - context.price / anchor) if anchor > 0.0 else 0.0
        rolling_pos = self._value(context.latest, "rolling_365d_pos")
        donchian_pos = self._value(context.latest, "donchian_pos")
        drop_min = self.RECOVERY_CREDIT_DROP_MIN.get(context.symbol, 0.04)
        rolling_max = self.RECOVERY_CREDIT_ROLLING_POS_MAX.get(context.symbol, 0.55)
        donchian_max = self.RECOVERY_CREDIT_DONCHIAN_POS_MAX.get(context.symbol, 0.60)
        if regime.structural_bear:
            self._record_recovery_credit_check(context, regime, signals, ledger, False, "structural_bear_active", current_drop, rolling_pos, donchian_pos, drop_min, rolling_max, donchian_max)
            return V42RecoveryPlan(blocked_reason="structural_bear_active")
        if regime.regime not in {"BULL", "RANGE", "TRANSITION"}:
            self._record_recovery_credit_check(context, regime, signals, ledger, False, "regime_not_allowed", current_drop, rolling_pos, donchian_pos, drop_min, rolling_max, donchian_max)
            return V42RecoveryPlan(blocked_reason="regime_not_allowed")
        if regime.btc_regime == "BEAR":
            self._record_recovery_credit_check(context, regime, signals, ledger, False, "btc_bear", current_drop, rolling_pos, donchian_pos, drop_min, rolling_max, donchian_max)
            return V42RecoveryPlan(blocked_reason="btc_bear")
        if context.trend_risk > 2:
            self._record_recovery_credit_check(context, regime, signals, ledger, False, "trend_risk_high", current_drop, rolling_pos, donchian_pos, drop_min, rolling_max, donchian_max)
            return V42RecoveryPlan(blocked_reason="trend_risk_high")
        if signals.distribution_exhaustion:
            self._record_recovery_credit_check(context, regime, signals, ledger, False, "distribution_exhaustion", current_drop, rolling_pos, donchian_pos, drop_min, rolling_max, donchian_max)
            return V42RecoveryPlan(blocked_reason="distribution_exhaustion")
        if not (signals.recovery_signal or signals.recovery_quality_ok or signals.value_recovery):
            self._record_recovery_credit_check(context, regime, signals, ledger, False, "recovery_signal_missing", current_drop, rolling_pos, donchian_pos, drop_min, rolling_max, donchian_max)
            return V42RecoveryPlan(blocked_reason="recovery_signal_missing")
        location_filter_ok = bool(
            (pd.isna(rolling_pos) or rolling_pos <= rolling_max)
            and (pd.isna(donchian_pos) or donchian_pos <= donchian_max)
        )
        location_ok = bool(current_drop >= drop_min and location_filter_ok)
        if not location_ok:
            self._record_recovery_credit_check(context, regime, signals, ledger, False, "credit_location_hot", current_drop, rolling_pos, donchian_pos, drop_min, rolling_max, donchian_max)
            return V42RecoveryPlan(blocked_reason="credit_location_hot")
        self._record_recovery_credit_check(context, regime, signals, ledger, True, "", current_drop, rolling_pos, donchian_pos, drop_min, rolling_max, donchian_max)
        return V42RecoveryPlan(
            allowed=True,
            target=anchor,
            remaining_budget=remaining,
            guard="v4_2_recovery_credit_soft",
        )

    def _release_recovery_credit(self, context: V42Context, sizing: V42Sizing) -> None:
        ledger = self._recovery_credit_ledger.get(context.symbol)
        if not ledger:
            return
        before = float(ledger.get("remaining", 0.0) or 0.0)
        used = min(before, max(0.0, float(getattr(sizing, "recovery_credit_used", 0.0) or 0.0)))
        after = max(0.0, before - used)
        ledger["remaining"] = after
        self._recovery_credit_ledger[context.symbol] = ledger
        self._record_recovery_credit_event(
            symbol=context.symbol,
            event="credit_released",
            episode={"episode_id": ledger.get("episode_id", "")},
            source_close_reason=str(ledger.get("source_close_reason", "")),
            credit_before=before,
            credit_delta=-used,
            credit_after=after,
            anchor_price=float(ledger.get("anchor_price", 0.0) or 0.0),
            guard=str(sizing.guard),
            blocked_reason="",
        )

    def _record_recovery_credit_event(
        self,
        *,
        symbol: str,
        event: str,
        episode: dict,
        source_close_reason: str,
        credit_before: float,
        credit_delta: float,
        credit_after: float,
        anchor_price: float,
        guard: str,
        blocked_reason: str,
    ) -> None:
        context = self._current_context_by_symbol.get(symbol)
        timestamp = context.latest.get("timestamp") if context is not None else None
        self._recovery_credit_events.append({
            "timestamp": timestamp,
            "symbol": symbol,
            "event": event,
            "episode_id": episode.get("episode_id", ""),
            "source_close_reason": source_close_reason,
            "credit_before": float(credit_before),
            "credit_delta": float(credit_delta),
            "credit_after": float(credit_after),
            "anchor_price": float(anchor_price),
            "guard": guard,
            "blocked_reason": blocked_reason,
        })

    def _record_recovery_credit_check(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        ledger: dict,
        allowed: bool,
        blocked_reason: str,
        current_drop: float,
        rolling_pos: float,
        donchian_pos: float,
        drop_min: float,
        rolling_max: float,
        donchian_max: float,
    ) -> None:
        self._recovery_credit_checks.append({
            "timestamp": context.latest.get("timestamp"),
            "symbol": context.symbol,
            "allowed": bool(allowed),
            "blocked_reason": blocked_reason,
            "remaining": float(ledger.get("remaining", 0.0) or 0.0),
            "anchor_price": float(ledger.get("anchor_price", 0.0) or 0.0),
            "price": float(context.price),
            "current_drop": float(current_drop),
            "drop_min": float(drop_min),
            "rolling_365d_pos": float(rolling_pos) if not pd.isna(rolling_pos) else float("nan"),
            "rolling_pos_max": float(rolling_max),
            "donchian_pos": float(donchian_pos) if not pd.isna(donchian_pos) else float("nan"),
            "donchian_pos_max": float(donchian_max),
            "regime": regime.regime,
            "btc_regime": regime.btc_regime,
            "trend_risk": int(context.trend_risk),
            "risk_score": int(context.risk_score),
            "recovery_signal": bool(signals.recovery_signal),
            "recovery_quality_ok": bool(signals.recovery_quality_ok),
            "value_recovery": bool(signals.value_recovery),
            "distribution_exhaustion": bool(signals.distribution_exhaustion),
            "source_close_reason": str(ledger.get("source_close_reason", "")),
            "episode_id": str(ledger.get("episode_id", "")),
        })

    def _recovery_credit_total(self) -> float:
        return sum(float(item.get("remaining", 0.0) or 0.0) for item in self._recovery_credit_ledger.values())

    def _recovery_credit_portfolio_cap(self) -> float:
        return self.RECOVERY_CREDIT_PORTFOLIO_AVG_CAP * max(1, len(getattr(self, "TARGET_ALLOC", {}) or {}))


