class V42ExpRecoveryCreditConsumeMainBuyV1Strategy(V42ExpRecoveryCreditMainlineCandidateV1Strategy):
    """V4.2 recovery credit: let existing main recovery buys consume open credit without adding orders."""

    RECOVERY_CREDIT_CONSUME_MAIN_BUY_SET = {"value-recovery", "recovery-probe-buy"}
    RECOVERY_CREDIT_CONSUME_LOOKBACK_CALLS = 8

    @property
    def name(self) -> str:
        return "v4_2_exp_recovery_credit_consume_main_buy_v1"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._last_main_buy_for_credit_by_symbol: dict[str, dict] = {}
        self._credit_consumed_buy_calls: set[tuple[str, int]] = set()

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "buy":
            self._track_main_buy_for_credit(context, sizing)
            self._consume_recovery_credit_from_current_buy(context, regime, signals=None, sizing=sizing)
            return
        if (
            action is None
            and sizing.side == "buy"
            and sizing.setup == "recovery-probe-buy"
            and sizing.blocked_reason == "cooldown"
        ):
            self._consume_recovery_credit_from_recent_buy(context, regime)

    def _track_main_buy_for_credit(self, context: V42Context, sizing: V42Sizing) -> None:
        if sizing.setup not in self.RECOVERY_CREDIT_CONSUME_MAIN_BUY_SET:
            return
        if "v4_2_recovery_credit_soft" in str(sizing.guard):
            return
        self._last_main_buy_for_credit_by_symbol[context.symbol] = {
            "call": self._call_count,
            "setup": sizing.setup,
            "step_pct": max(0.0, float(sizing.actual_step_pct or 0.0)),
            "price": float(context.price),
        }

    def _consume_recovery_credit_from_current_buy(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals | None,
        sizing: V42Sizing,
    ) -> None:
        if sizing.setup not in self.RECOVERY_CREDIT_CONSUME_MAIN_BUY_SET:
            return
        if "v4_2_recovery_credit_soft" in str(sizing.guard):
            return
        if sizing.actual_step_pct <= 0.0:
            return
        self._consume_recovery_credit_by_main_buy(
            context=context,
            regime=regime,
            signals=signals,
            buy_call=self._call_count,
            buy_setup=sizing.setup,
            buy_step_pct=float(sizing.actual_step_pct),
            guard_suffix="current_main_buy",
        )

    def _consume_recovery_credit_from_recent_buy(self, context: V42Context, regime: V42Regime) -> None:
        last = self._last_main_buy_for_credit_by_symbol.get(context.symbol)
        if not last:
            return
        buy_call = int(last.get("call", -10_000) or -10_000)
        if self._call_count - buy_call > self.RECOVERY_CREDIT_CONSUME_LOOKBACK_CALLS:
            return
        self._consume_recovery_credit_by_main_buy(
            context=context,
            regime=regime,
            signals=None,
            buy_call=buy_call,
            buy_setup=str(last.get("setup", "")),
            buy_step_pct=float(last.get("step_pct", 0.0) or 0.0),
            guard_suffix="recent_main_buy",
        )

    def _consume_recovery_credit_by_main_buy(
        self,
        *,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals | None,
        buy_call: int,
        buy_setup: str,
        buy_step_pct: float,
        guard_suffix: str,
    ) -> None:
        if buy_step_pct <= 0.0:
            return
        key = (context.symbol, buy_call)
        if key in self._credit_consumed_buy_calls:
            return
        active_signals = signals if signals is not None else self._build_signals(context, regime, {"state": "NORMAL"})
        plan = self._recovery_credit_plan(context, regime, active_signals)
        if not bool(plan.get("allowed", False)):
            return
        ledger = self._recovery_credit_ledger.get(context.symbol)
        if not ledger:
            return
        before = float(ledger.get("remaining", 0.0) or 0.0)
        release_cap = self.RECOVERY_CREDIT_RELEASE_CAP.get(context.symbol, 0.04)
        used = min(before, release_cap, buy_step_pct)
        if used <= self.RECOVERY_MIN_STEP:
            return
        after = max(0.0, before - used)
        ledger["remaining"] = after
        self._recovery_credit_ledger[context.symbol] = ledger
        self._credit_consumed_buy_calls.add(key)
        self._record_recovery_credit_event(
            symbol=context.symbol,
            event="credit_consumed_by_main_buy",
            episode={"episode_id": ledger.get("episode_id", "")},
            source_close_reason=str(ledger.get("source_close_reason", "")),
            credit_before=before,
            credit_delta=-used,
            credit_after=after,
            anchor_price=float(ledger.get("anchor_price", 0.0) or 0.0),
            guard=f"v4_2_recovery_credit_consumed_by_{guard_suffix}_{buy_setup}",
            blocked_reason="",
        )


class V42ExpRecoveryCreditBtcDeepOverlayV1Strategy(V42ExpRecoveryCreditConsumeMainBuyV1Strategy):
    """V4.2 recovery credit: allow one tiny BTC deep-discount overlay through recent-buy cooldown."""

    RECOVERY_CREDIT_BTC_DEEP_DROP_MIN = 0.25
    RECOVERY_CREDIT_BTC_DEEP_RELEASE_CAP = 0.02
    RECOVERY_CREDIT_BTC_DEEP_LOOKBACK_CALLS = 8

    @property
    def name(self) -> str:
        return "v4_2_exp_recovery_credit_btc_deep_overlay_v1"

    def _recovery_credit_sizing(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> V42Sizing:
        plan = self._recovery_credit_plan(context, regime, signals)
        if not bool(plan.get("allowed", False)):
            return V42Sizing(blocked_reason=str(plan.get("blocked_reason", "")))
        credit_before = float(plan.get("remaining_budget", 0.0) or 0.0)
        cooldown = max(self._buy_cooldown(context, regime, "recovery-probe-buy"), 8)
        last_buy = self._last_buy_call_by_symbol.get(context.symbol, -10_000)
        cooldown_active = self._call_count - last_buy < cooldown
        btc_deep_overlay = bool(cooldown_active and self._allow_btc_deep_credit_overlay(context))
        if cooldown_active and not btc_deep_overlay:
            self._diag["v4_2_cooldown_blocked_count"] += 1
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="cooldown")
        release_cap = (
            self.RECOVERY_CREDIT_BTC_DEEP_RELEASE_CAP
            if btc_deep_overlay
            else self.RECOVERY_CREDIT_RELEASE_CAP.get(context.symbol, 0.04)
        )
        buy_pct = min(credit_before, release_cap)
        buy_qty = context.total_value * buy_pct / context.price
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="min_notional")
        guard = self._join_guard(
            self._sizing_guard(context, regime, {"state": "NORMAL"}, "recovery-probe-buy"),
            "v4_2_recovery_credit_soft",
        )
        if btc_deep_overlay:
            guard = self._join_guard(guard, "v4_2_btc_deep_credit_overlay")
        target = min(self.TARGET_CAP, context.current_pct + buy_pct)
        sizing = V42Sizing(
            side="buy",
            setup="recovery-probe-buy",
            quantity=buy_qty,
            target=target,
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=buy_pct,
            actual_step_pct=buy_pct,
            remaining_gap_after=0.0,
        )
        setattr(sizing, "recovery_credit_before", credit_before)
        setattr(sizing, "recovery_credit_used", buy_pct)
        setattr(sizing, "recovery_credit_after", max(0.0, credit_before - buy_pct))
        setattr(sizing, "recovery_credit_anchor_price", float(plan.get("target", 0.0) or 0.0))
        return sizing

    def _allow_btc_deep_credit_overlay(self, context: V42Context) -> bool:
        if context.symbol != "BTC/USDT":
            return False
        ledger = self._recovery_credit_ledger.get(context.symbol)
        if not ledger:
            return False
        anchor = float(ledger.get("anchor_price", 0.0) or 0.0)
        if anchor <= 0.0:
            return False
        current_drop = max(0.0, 1.0 - context.price / anchor)
        if current_drop < self.RECOVERY_CREDIT_BTC_DEEP_DROP_MIN:
            return False
        last = self._last_main_buy_for_credit_by_symbol.get(context.symbol)
        if not last or str(last.get("setup", "")) != "value-recovery":
            return False
        buy_call = int(last.get("call", -10_000) or -10_000)
        return bool(0 <= self._call_count - buy_call <= self.RECOVERY_CREDIT_BTC_DEEP_LOOKBACK_CALLS)


class V42ExpRecoveryCreditBtcDeepOverlayOnce2PctV1Strategy(V42ExpRecoveryCreditBtcDeepOverlayV1Strategy):
    """V4.2 recovery credit: one BTC deep overlay per credit episode, capped at 2%."""

    RECOVERY_CREDIT_BTC_DEEP_RELEASE_CAP = 0.02

    @property
    def name(self) -> str:
        return "v4_2_exp_recovery_credit_btc_deep_overlay_once_2pct_v1"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._btc_deep_overlay_used_episode_ids: set[str] = set()

    def _allow_btc_deep_credit_overlay(self, context: V42Context) -> bool:
        if not super()._allow_btc_deep_credit_overlay(context):
            return False
        ledger = self._recovery_credit_ledger.get(context.symbol) or {}
        episode_id = str(ledger.get("episode_id", ""))
        return bool(episode_id and episode_id not in self._btc_deep_overlay_used_episode_ids)

    def _release_recovery_credit(self, context: V42Context, sizing: V42Sizing) -> None:
        ledger = self._recovery_credit_ledger.get(context.symbol) or {}
        episode_id = str(ledger.get("episode_id", ""))
        super()._release_recovery_credit(context, sizing)
        if context.symbol == "BTC/USDT" and "v4_2_btc_deep_credit_overlay" in str(sizing.guard) and episode_id:
            self._btc_deep_overlay_used_episode_ids.add(episode_id)


