class V43ExpReversalMaturityV1Strategy(V42ExpRecoveryCreditMainlineCandidateV2Strategy):
    """V4.3 experiment: wait for repeated recovery reversals before probe buys."""

    REVERSAL_MATURITY_REQUIRED_COUNT = 2
    REVERSAL_MATURITY_REBOUND_PCT = 0.08
    REVERSAL_MATURITY_MIN_CALL_GAP = 8
    REVERSAL_MATURITY_STATES = {"DEFENSE_LOCK", "RECOVERY_TEST", "FAILED_RECOVERY_LOCK", "STRUCTURAL_BEAR_LOCK"}

    @property
    def name(self) -> str:
        return "v4_3_exp_reversal_maturity_v1"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._reversal_maturity_by_symbol: dict[str, dict] = {}

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        reversal_count = self._update_reversal_maturity(context, regime, episode, signals)
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        if (
            sizing.side == "buy"
            and sizing.setup == "recovery-probe-buy"
            and str(episode.get("state", "NORMAL")) in self.REVERSAL_MATURITY_STATES
            and reversal_count < self.REVERSAL_MATURITY_REQUIRED_COUNT
        ):
            self._diag["v4_3_reversal_maturity_probe_blocked_count"] = (
                self._diag.get("v4_3_reversal_maturity_probe_blocked_count", 0) + 1
            )
            return V42Sizing(side="buy", setup=sizing.setup, blocked_reason="reversal_maturity_wait")
        return sizing

    def _update_reversal_maturity(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
    ) -> int:
        state = str(episode.get("state", "NORMAL"))
        episode_id = str(episode.get("episode_id", ""))
        if state not in self.REVERSAL_MATURITY_STATES or not episode_id:
            self._reversal_maturity_by_symbol.pop(context.symbol, None)
            return 0

        tracker = self._reversal_maturity_by_symbol.setdefault(
            context.symbol,
            {
                "episode_id": episode_id,
                "low_price": float(context.price),
                "count": 0,
                "last_signal": False,
                "last_reversal_call": -10_000,
            },
        )
        if str(tracker.get("episode_id", "")) != episode_id:
            tracker.clear()
            tracker.update({
                "episode_id": episode_id,
                "low_price": float(context.price),
                "count": 0,
                "last_signal": False,
                "last_reversal_call": -10_000,
            })

        low_price = min(float(tracker.get("low_price", context.price) or context.price), float(context.price))
        tracker["low_price"] = low_price
        signal_active = bool(signals.recovery_signal or signals.strong_recovery_signal or signals.recovery_quality_ok)
        last_signal = bool(tracker.get("last_signal", False))
        rebound_ok = bool(low_price > 0.0 and context.price >= low_price * (1.0 + self.REVERSAL_MATURITY_REBOUND_PCT))
        risk_ok = bool(not regime.structural_bear and context.trend_risk <= 2)
        enough_gap = bool(self._call_count - int(tracker.get("last_reversal_call", -10_000) or -10_000) >= self.REVERSAL_MATURITY_MIN_CALL_GAP)
        if signal_active and not last_signal and rebound_ok and risk_ok and enough_gap:
            tracker["count"] = int(tracker.get("count", 0) or 0) + 1
            tracker["last_reversal_call"] = self._call_count
            tracker["low_price"] = float(context.price)
            self._diag["v4_3_reversal_maturity_confirmed_count"] = (
                self._diag.get("v4_3_reversal_maturity_confirmed_count", 0) + 1
            )
        tracker["last_signal"] = signal_active
        return int(tracker.get("count", 0) or 0)


class V43ExpReversalMaturityV2Strategy(V43ExpReversalMaturityV1Strategy):
    """V4.3 experiment: skip only the first immature recovery bounce."""

    REVERSAL_MATURITY_REQUIRED_COUNT = 1

    @property
    def name(self) -> str:
        return "v4_3_exp_reversal_maturity_v2"


class V43ExpOpportunityFloorV1Strategy(V42ExpRecoveryCreditMainlineCandidateV2Strategy):
    """V4.3 experiment: small low-location floor exposure inside the total position target."""

    OPPORTUNITY_FLOOR_SYMBOLS = {"ETH/USDT", "BNB/USDT"}
    OPPORTUNITY_FLOOR_TARGET = {"ETH/USDT": 0.08, "BNB/USDT": 0.08}
    OPPORTUNITY_FLOOR_MAX_BUY_PCT = 0.02
    OPPORTUNITY_FLOOR_COOLDOWN_CALLS = 18

    @property
    def name(self) -> str:
        return "v4_3_exp_opportunity_floor_v1"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        if sizing.side == "sell" and sizing.quantity > 1e-12:
            return sizing
        floor = self._opportunity_floor_sizing(context, regime, signals, sizing)
        if floor.side or floor.blocked_reason:
            return floor if floor.side else sizing
        return sizing

    def _opportunity_floor_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        if context.symbol not in self.OPPORTUNITY_FLOOR_SYMBOLS:
            return V42Sizing()
        target = float(self.OPPORTUNITY_FLOOR_TARGET.get(context.symbol, 0.0))
        if target <= 0.0 or context.current_pct >= target - self.RECOVERY_MIN_STEP:
            return V42Sizing(blocked_reason="opportunity_floor_filled")
        if not self._opportunity_floor_low_location(context, regime):
            return V42Sizing()
        if not self._opportunity_floor_stabilizing(context, regime, signals):
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="opportunity_floor_not_stabilizing")
        last_buy = self._last_buy_call_by_symbol.get(context.symbol, -10_000)
        if self._call_count - last_buy < self.OPPORTUNITY_FLOOR_COOLDOWN_CALLS:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="cooldown")
        gap = max(0.0, target - context.current_pct)
        buy_pct = min(gap, self.OPPORTUNITY_FLOOR_MAX_BUY_PCT)
        buy_qty = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="min_notional")
        self._diag["v4_3_opportunity_floor_buy_count"] = self._diag.get("v4_3_opportunity_floor_buy_count", 0) + 1
        guard = self._join_guard(
            self._sizing_guard(context, regime, {"state": str(getattr(prior_sizing, "setup", "") or "NORMAL")}, "opportunity-floor-buy"),
            "v4_3_opportunity_floor",
        )
        return V42Sizing(
            side="buy",
            setup="opportunity-floor-buy",
            quantity=buy_qty,
            target=min(target, self.TARGET_CAP),
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=gap,
            actual_step_pct=buy_pct,
            remaining_gap_after=max(0.0, gap - buy_pct),
        )

    def _opportunity_floor_low_location(self, context: V42Context, regime: V42Regime) -> bool:
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.10)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.12)
            or (not pd.isna(regime.price_vs_ema168) and regime.price_vs_ema168 <= -0.20)
        )

    def _opportunity_floor_stabilizing(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> bool:
        if regime.structural_bear and context.trend_risk >= 3:
            return False
        if context.risk_score >= 5:
            return False
        recent = context.df.tail(12)
        if recent.empty or "close" not in recent.columns:
            return bool(signals.recovery_signal or signals.recovery_quality_ok)
        recent_low = float(recent["close"].min())
        rebound = context.price / recent_low - 1.0 if recent_low > 0.0 else 0.0
        roc_5 = self._value(context.latest, "roc_5", 0.0)
        return bool(
            rebound >= 0.035
            or (not pd.isna(roc_5) and roc_5 >= -0.03)
            or signals.recovery_signal
            or signals.recovery_quality_ok
        )


class V43ExpOpportunityFloorV2Strategy(V43ExpOpportunityFloorV1Strategy):
    """V4.3 experiment: low floor with softer local-stability filter."""

    @property
    def name(self) -> str:
        return "v4_3_exp_opportunity_floor_v2"

    def _opportunity_floor_stabilizing(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> bool:
        if context.risk_score >= 5:
            return False
        recent = context.df.tail(20)
        if recent.empty or "close" not in recent.columns:
            return True
        recent_low = float(recent["close"].min())
        rebound = context.price / recent_low - 1.0 if recent_low > 0.0 else 0.0
        roc_5 = self._value(context.latest, "roc_5", 0.0)
        roc_20 = self._value(context.latest, "roc_20", 0.0)
        waterfall = bool(
            not pd.isna(roc_20)
            and roc_20 <= -0.28
            and rebound < 0.015
        )
        if waterfall:
            return False
        return bool(
            rebound >= 0.015
            or (not pd.isna(roc_5) and roc_5 >= -0.08)
            or signals.recovery_signal
            or signals.recovery_quality_ok
        )


class V43ExpOpportunityFloorV3Strategy(V43ExpOpportunityFloorV2Strategy):
    """V4.3 experiment: opportunity floor uses an independent buy channel."""

    @property
    def name(self) -> str:
        return "v4_3_exp_opportunity_floor_v3"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._last_opportunity_floor_buy_call_by_symbol: dict[str, int] = {}

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super(V43ExpOpportunityFloorV1Strategy, self)._compute_sizing(context, regime, episode, signals, decision)
        if sizing.side:
            return sizing
        floor = self._opportunity_floor_sizing(context, regime, signals, sizing)
        if floor.side or floor.blocked_reason:
            return floor if floor.side else sizing
        return sizing

    def _opportunity_floor_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        if context.symbol not in self.OPPORTUNITY_FLOOR_SYMBOLS:
            return V42Sizing()
        target = float(self.OPPORTUNITY_FLOOR_TARGET.get(context.symbol, 0.0))
        if target <= 0.0 or context.current_pct >= target - self.RECOVERY_MIN_STEP:
            return V42Sizing(blocked_reason="opportunity_floor_filled")
        if not self._opportunity_floor_low_location(context, regime):
            return V42Sizing()
        if not self._opportunity_floor_stabilizing(context, regime, signals):
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="opportunity_floor_not_stabilizing")
        last_buy = self._last_opportunity_floor_buy_call_by_symbol.get(context.symbol, -10_000)
        if self._call_count - last_buy < self.OPPORTUNITY_FLOOR_COOLDOWN_CALLS:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="opportunity_floor_cooldown")
        gap = max(0.0, target - context.current_pct)
        buy_pct = min(gap, self.OPPORTUNITY_FLOOR_MAX_BUY_PCT)
        buy_qty = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="min_notional")
        self._diag["v4_3_opportunity_floor_buy_count"] = self._diag.get("v4_3_opportunity_floor_buy_count", 0) + 1
        guard = self._join_guard(
            self._sizing_guard(context, regime, {"state": "OPPORTUNITY_FLOOR"}, "opportunity-floor-buy"),
            "v4_3_opportunity_floor_independent",
        )
        return V42Sizing(
            side="buy",
            setup="opportunity-floor-buy",
            quantity=buy_qty,
            target=min(target, self.TARGET_CAP),
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=gap,
            actual_step_pct=buy_pct,
            remaining_gap_after=max(0.0, gap - buy_pct),
        )

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        if action is None or sizing.setup != "opportunity-floor-buy" or action.side != "buy":
            return super()._record_event(context, regime, episode, decision, sizing, action)

        symbol = context.symbol
        self._diag["v4_2_action_buy_count"] += 1
        self._diag["v4_3_opportunity_floor_executed_count"] = self._diag.get("v4_3_opportunity_floor_executed_count", 0) + 1
        self._last_opportunity_floor_buy_call_by_symbol[symbol] = self._call_count
        if hasattr(self, "_record_sleeve_accounting"):
            self._record_sleeve_accounting(context, decision, sizing, action)


class V43ExpOpportunityFloorV4Strategy(V43ExpOpportunityFloorV3Strategy):
    """V4.3 experiment: independent floor may act when the main buy channel is blocked."""

    @property
    def name(self) -> str:
        return "v4_3_exp_opportunity_floor_v4"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super(V43ExpOpportunityFloorV1Strategy, self)._compute_sizing(context, regime, episode, signals, decision)
        if sizing.side == "sell":
            return sizing
        if sizing.side == "buy" and sizing.quantity > 1e-12:
            return sizing
        floor = self._opportunity_floor_sizing(context, regime, signals, sizing)
        if floor.side or floor.blocked_reason:
            return floor if floor.side else sizing
        return sizing


class V43ExpProtectedFloorV1Strategy(V43ExpOpportunityFloorV4Strategy):
    """V4.3 experiment: protect low-location floor from ordinary main-sleeve sells."""

    PROTECTED_FLOOR_STOP_LOSS_PCT = 0.30
    PROTECTED_FLOOR_TAKE_PROFIT_PCT = 0.80
    PROTECTED_FLOOR_HIGH_ROLLING_POS = 0.75
    PROTECTED_FLOOR_HIGH_DONCHIAN_POS = 0.78

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v1"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._protected_floor_ledger_by_symbol: dict[str, dict] = {}
        self._current_regime_for_protected_floor_by_symbol: dict[str, V42Regime] = {}

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        self._current_regime_for_protected_floor_by_symbol[context.symbol] = regime
        return super()._compute_sizing(context, regime, episode, signals, decision)

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        if action is not None and action.side == "sell":
            self._consume_protected_floor_for_sell(context, regime, action)
        super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "buy" and sizing.setup == "opportunity-floor-buy":
            self._record_protected_floor_buy(context, regime, action)

    def _build_action(self, context: V42Context, regime: V42Regime, decision: V42DecisionPlan, sizing: V42Sizing) -> Action | None:
        action = super()._build_action(context, regime, decision, sizing)
        if action is None or action.side != "sell":
            return action
        if sizing.setup == "bear-base-exit":
            return action
        main_state = getattr(self, "_main_sleeve_by_symbol", {}).get(context.symbol)
        accounting_main_qty = max(0.0, float(getattr(main_state, "quantity", 0.0) or 0.0))
        if self._protected_floor_exit_allowed(context, regime):
            sellable_qty = accounting_main_qty
        else:
            protected_qty = self._protected_floor_quantity(context)
            sellable_qty = max(0.0, accounting_main_qty - protected_qty)
        protected_qty = self._protected_floor_quantity(context)
        if float(action.quantity) <= sellable_qty + 1e-12:
            return action
        if sellable_qty <= 1e-12 or sellable_qty * context.price < self.min_notional:
            self._diag["v4_3_protected_floor_sell_blocked_count"] = (
                self._diag.get("v4_3_protected_floor_sell_blocked_count", 0) + 1
            )
            return None
        clipped_qty = min(float(action.quantity), sellable_qty)
        self._diag["v4_3_protected_floor_sell_clipped_count"] = (
            self._diag.get("v4_3_protected_floor_sell_clipped_count", 0) + 1
        )
        action.quantity = clipped_qty
        sizing.actual_step_pct = clipped_qty * context.price / context.total_value if context.total_value > 0.0 else 0.0
        sizing.actual_position_after = max(0.0, context.current_pct - sizing.actual_step_pct)
        sizing.remaining_gap_after = max(0.0, float(sizing.target_gap_before) - sizing.actual_step_pct)
        action.reason = f"{action.reason}-v4_3_protected_floor_sell_clipped"
        return action

    def _record_protected_floor_buy(self, context: V42Context, regime: V42Regime, action: Action) -> None:
        ledger = self._protected_floor_ledger_by_symbol.setdefault(
            context.symbol,
            {
                "quantity": 0.0,
                "avg_entry": 0.0,
                "entry_call": self._call_count,
                "entry_price": context.price,
                "entry_structural_bear": regime.structural_bear,
            },
        )
        old_qty = max(0.0, float(ledger.get("quantity", 0.0) or 0.0))
        old_entry = float(ledger.get("avg_entry", context.price) or context.price)
        new_qty = old_qty + float(action.quantity)
        ledger["quantity"] = new_qty
        ledger["avg_entry"] = (old_entry * old_qty + context.price * float(action.quantity)) / new_qty if new_qty > 0.0 else 0.0
        ledger["entry_price"] = min(float(ledger.get("entry_price", context.price) or context.price), float(context.price))
        ledger["entry_call"] = min(int(ledger.get("entry_call", self._call_count) or self._call_count), self._call_count)
        ledger["entry_structural_bear"] = bool(ledger.get("entry_structural_bear", False) or regime.structural_bear)
        ledger["peak_price"] = max(float(ledger.get("peak_price", context.price) or context.price), float(context.price))

    def _consume_protected_floor_for_sell(self, context: V42Context, regime: V42Regime, action: Action) -> None:
        if not self._protected_floor_exit_allowed(context, regime):
            return
        floor_qty = self._protected_floor_quantity(context)
        if floor_qty <= 1e-12:
            return
        non_floor_qty = max(0.0, super()._main_quantity(context) - floor_qty)
        consume = max(0.0, float(action.quantity) - non_floor_qty)
        if consume <= 1e-12:
            return
        ledger = self._protected_floor_ledger_by_symbol.get(context.symbol)
        if not ledger:
            return
        remaining = max(0.0, floor_qty - consume)
        ledger["quantity"] = remaining
        if remaining <= 1e-12:
            ledger["quantity"] = 0.0
            ledger["avg_entry"] = 0.0

    def _protected_floor_quantity(self, context: V42Context) -> float:
        ledger = self._protected_floor_ledger_by_symbol.get(context.symbol, {})
        qty = max(0.0, float(ledger.get("quantity", 0.0) or 0.0))
        return min(qty, max(0.0, float(context.pos.quantity)))

    def _protected_floor_exit_allowed(self, context: V42Context, regime: V42Regime) -> bool:
        ledger = self._protected_floor_ledger_by_symbol.get(context.symbol)
        if not ledger or float(ledger.get("quantity", 0.0) or 0.0) <= 1e-12:
            return False
        avg_entry = float(ledger.get("avg_entry", 0.0) or 0.0)
        if avg_entry <= 0.0:
            return False
        loss = 1.0 - context.price / avg_entry
        profit = context.price / avg_entry - 1.0
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        high_location = bool(
            (not pd.isna(rolling_pos) and rolling_pos >= self.PROTECTED_FLOOR_HIGH_ROLLING_POS)
            or (not pd.isna(donchian_pos) and donchian_pos >= self.PROTECTED_FLOOR_HIGH_DONCHIAN_POS)
        )
        hard_stop = loss >= self.PROTECTED_FLOOR_STOP_LOSS_PCT
        take_profit = profit >= self.PROTECTED_FLOOR_TAKE_PROFIT_PCT and high_location
        if hard_stop:
            self._diag["v4_3_protected_floor_stop_exit_allowed_count"] = (
                self._diag.get("v4_3_protected_floor_stop_exit_allowed_count", 0) + 1
            )
        if take_profit:
            self._diag["v4_3_protected_floor_profit_exit_allowed_count"] = (
                self._diag.get("v4_3_protected_floor_profit_exit_allowed_count", 0) + 1
            )
        return bool(hard_stop or take_profit)


class V43ExpProtectedFloorV2Strategy(V43ExpProtectedFloorV1Strategy):
    """V4.3 experiment: protected floor only after true low location and stabilization."""

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v2"

    def _opportunity_floor_low_location(self, context: V42Context, regime: V42Regime) -> bool:
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        price_vs_ema168 = regime.price_vs_ema168

        if (
            regime.regime == "BEAR"
            and context.trend_risk >= 3
            and not pd.isna(rolling_pos)
            and rolling_pos > 0.25
        ):
            return False
        if (
            regime.regime == "BEAR"
            and context.trend_risk >= 3
            and not pd.isna(donchian_pos)
            and donchian_pos > 0.25
        ):
            return False

        extreme_low = bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.15)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.15)
        )
        deep_discount = bool(
            not pd.isna(price_vs_ema168)
            and price_vs_ema168 <= -0.28
            and (
                (not pd.isna(rolling_pos) and rolling_pos <= 0.25)
                or (not pd.isna(donchian_pos) and donchian_pos <= 0.25)
            )
        )
        return bool(extreme_low or deep_discount)

    def _opportunity_floor_stabilizing(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> bool:
        if context.risk_score >= 5:
            return False
        recent = context.df.tail(20)
        if recent.empty or "close" not in recent.columns:
            return bool(signals.recovery_signal or signals.recovery_quality_ok)

        recent_low = float(recent["close"].min())
        rebound = context.price / recent_low - 1.0 if recent_low > 0.0 else 0.0
        roc_5 = self._value(context.latest, "roc_5", 0.0)
        roc_20 = self._value(context.latest, "roc_20", 0.0)
        waterfall = bool(
            not pd.isna(roc_20)
            and roc_20 <= -0.20
            and rebound < 0.05
        )
        if waterfall:
            return False

        panic = bool(regime.regime == "BEAR" and context.trend_risk >= 3)
        if panic:
            return bool(
                rebound >= 0.05
                and not pd.isna(roc_5)
                and roc_5 > 0.0
            )
        return bool(
            rebound >= 0.03
            or (not pd.isna(roc_5) and roc_5 >= -0.02)
            or signals.recovery_signal
            or signals.recovery_quality_ok
        )


class V43ExpProtectedFloorV3Strategy(V43ExpProtectedFloorV2Strategy):
    """V4.3 experiment: stricter true-low protected floor entry."""

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v3"

    def _opportunity_floor_low_location(self, context: V42Context, regime: V42Regime) -> bool:
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.15)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.15)
        )

    def _opportunity_floor_stabilizing(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> bool:
        if context.risk_score >= 5:
            return False
        recent = context.df.tail(20)
        if recent.empty or "close" not in recent.columns:
            return bool(signals.recovery_signal or signals.recovery_quality_ok)

        recent_low_idx = recent["close"].idxmin()
        recent_low = float(recent.loc[recent_low_idx, "close"])
        rebound = context.price / recent_low - 1.0 if recent_low > 0.0 else 0.0
        days_since_low = max(0, len(recent) - 1 - recent.index.get_loc(recent_low_idx))
        roc_5 = self._value(context.latest, "roc_5", 0.0)
        roc_20 = self._value(context.latest, "roc_20", 0.0)
        roc_60 = self._value(context.latest, "roc_60", 0.0)

        waterfall = bool(
            not pd.isna(roc_20)
            and roc_20 <= -0.20
            and rebound < 0.05
        )
        if waterfall:
            return False

        deep_collapse_too_fresh = bool(
            not pd.isna(roc_60)
            and roc_60 <= -0.40
            and days_since_low < 10
        )
        if deep_collapse_too_fresh:
            return False

        panic = bool(regime.regime == "BEAR" and context.trend_risk >= 3)
        if panic:
            return bool(
                rebound >= 0.05
                and days_since_low >= 2
                and not pd.isna(roc_5)
                and roc_5 >= 0.0
            )
        return bool(
            rebound >= 0.03
            or (not pd.isna(roc_5) and roc_5 >= -0.02)
            or signals.recovery_signal
            or signals.recovery_quality_ok
        )


class V43ExpProtectedFloorV4Strategy(V43ExpProtectedFloorV3Strategy):
    """V4.3 experiment: 365-day true-low is mandatory for protected floor entry."""

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v4"

    def _opportunity_floor_low_location(self, context: V42Context, regime: V42Regime) -> bool:
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        if pd.isna(rolling_pos) or rolling_pos > 0.15:
            return False
        if not pd.isna(donchian_pos) and donchian_pos > 0.25:
            return False
        return True


class V43ExpProtectedFloorV5Strategy(V43ExpProtectedFloorV4Strategy):
    """V4.3 experiment: protected floor is accounted as base sleeve, not clipped main."""

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v5"

    def _build_action(self, context: V42Context, regime: V42Regime, decision: V42DecisionPlan, sizing: V42Sizing) -> Action | None:
        return super(V43ExpProtectedFloorV1Strategy, self)._build_action(context, regime, decision, sizing)

    def _action_sleeve(self, decision: V42DecisionPlan, sizing: V42Sizing) -> str:
        if sizing.setup == "opportunity-floor-buy":
            return "base"
        return super()._action_sleeve(decision, sizing)


class V43ExpProtectedFloorV6Strategy(V43ExpProtectedFloorV5Strategy):
    """V4.3 experiment: base-sleeve protected floor with synchronized base ledger."""

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v6"

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "buy" and sizing.setup == "opportunity-floor-buy":
            self._record_protected_floor_base_buy(context, action)

    def _record_protected_floor_base_buy(self, context: V42Context, action: Action) -> None:
        ledger = self._base_ledger_by_symbol.setdefault(context.symbol, self._new_base_ledger())
        buy_pct = action.quantity * action.price / context.total_value if context.total_value > 0.0 else 0.0
        old_base_qty = float(ledger.get("base_quantity", 0.0) or 0.0)
        old_entry = float(ledger.get("base_avg_entry_price", context.price) or context.price)
        new_base_qty = old_base_qty + float(action.quantity)
        if new_base_qty > 0.0:
            ledger["base_avg_entry_price"] = (old_entry * old_base_qty + context.price * float(action.quantity)) / new_base_qty
        ledger["base_budget_used_pct"] = self._ledger_base_budget_used_pct(ledger) + max(0.0, buy_pct)
        ledger["base_quantity"] = new_base_qty
        ledger["base_position_pct"] = self._base_pct_from_quantity(context, new_base_qty)
        ledger["base_source"] = self._join_guard(str(ledger.get("base_source", "")), "protected_floor")
        ledger["base_layer"] = max(int(ledger.get("base_layer", 0) or 0), 1)
        if ledger.get("base_entry_call") is None:
            ledger["base_entry_call"] = self._call_count
            ledger["base_peak_price"] = context.price
            ledger["base_peak_profit"] = 0.0


class V43ExpProtectedFloorV7Strategy(V43ExpProtectedFloorV6Strategy):
    """V4.3 experiment: unified high-release signal with protected-floor base exit."""

    PROTECTED_FLOOR_EXIT_MIN_HOLD_CALLS = 90
    PROTECTED_FLOOR_EXIT_PROFIT = 0.80
    PROTECTED_FLOOR_EXIT_HIGH_ROLLING = 0.70
    PROTECTED_FLOOR_EXIT_HIGH_DONCHIAN = 0.80
    PROTECTED_FLOOR_EXIT_DIRECT_PROFIT = 1.20
    PROTECTED_FLOOR_EXIT_FRACTION = 0.40

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v7"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        protected_exit = self._protected_floor_exit_sizing(context, regime, signals, decision)
        if protected_exit.side or protected_exit.blocked_reason:
            return protected_exit if protected_exit.side else super()._compute_sizing(context, regime, episode, signals, decision)
        return super()._compute_sizing(context, regime, episode, signals, decision)

    def _protected_floor_exit_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        ledger = self._base_ledger_by_symbol.get(context.symbol)
        if not ledger or "protected_floor" not in str(ledger.get("base_source", "")):
            return V42Sizing()
        base_qty = self._base_quantity(context)
        if base_qty <= 1e-12:
            return V42Sizing()
        entry_call = ledger.get("base_entry_call")
        if entry_call is None or self._call_count - int(entry_call) < self.PROTECTED_FLOOR_EXIT_MIN_HOLD_CALLS:
            return V42Sizing(side="sell", setup="protected-floor-exit", blocked_reason="protected_floor_min_hold")
        avg_entry = float(ledger.get("base_avg_entry_price", 0.0) or 0.0)
        if avg_entry <= 0.0:
            return V42Sizing(side="sell", setup="protected-floor-exit", blocked_reason="protected_floor_missing_entry")
        profit = context.price / avg_entry - 1.0
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        high_release = bool(
            profit >= self.PROTECTED_FLOOR_EXIT_DIRECT_PROFIT
            or (
                profit >= self.PROTECTED_FLOOR_EXIT_PROFIT
                and (
                    (not pd.isna(rolling_pos) and rolling_pos >= self.PROTECTED_FLOOR_EXIT_HIGH_ROLLING)
                    or (not pd.isna(donchian_pos) and donchian_pos >= self.PROTECTED_FLOOR_EXIT_HIGH_DONCHIAN)
                    or signals.distribution_exhaustion
                )
            )
        )
        if not high_release:
            return V42Sizing()
        sell_qty = min(base_qty, base_qty * self.PROTECTED_FLOOR_EXIT_FRACTION)
        notional = sell_qty * context.price
        if sell_qty <= 1e-12:
            return V42Sizing(side="sell", setup="protected-floor-exit", blocked_reason="zero_quantity")
        if notional < self.min_notional:
            return V42Sizing(side="sell", setup="protected-floor-exit", blocked_reason="min_notional")
        step_pct = notional / context.total_value if context.total_value > 0.0 else 0.0
        self._diag["v4_3_protected_floor_exit_count"] = self._diag.get("v4_3_protected_floor_exit_count", 0) + 1
        guard = self._join_guard(
            self._sizing_guard(context, regime, {"state": "PROTECTED_FLOOR_EXIT"}, "protected-floor-exit"),
            "v4_3_protected_floor_high_release",
        )
        return V42Sizing(
            side="sell",
            setup="protected-floor-exit",
            quantity=sell_qty,
            target=max(0.0, context.current_pct - step_pct),
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=max(0.0, context.current_pct - step_pct),
            target_gap_before=step_pct,
            actual_step_pct=step_pct,
            remaining_gap_after=0.0,
        )

    def _action_sleeve(self, decision: V42DecisionPlan, sizing: V42Sizing) -> str:
        if sizing.setup in {"opportunity-floor-buy", "protected-floor-exit"}:
            return "base"
        return super()._action_sleeve(decision, sizing)

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "sell" and sizing.setup == "protected-floor-exit":
            self._record_protected_floor_base_exit(context, action)

    def _record_protected_floor_base_exit(self, context: V42Context, action: Action) -> None:
        ledger = self._base_ledger_by_symbol.get(context.symbol)
        if not ledger:
            return
        base_qty = self._base_quantity(context)
        remaining = max(0.0, base_qty - float(action.quantity))
        ledger["base_quantity"] = remaining
        ledger["base_position_pct"] = self._base_pct_from_quantity(context, remaining)
        if remaining <= 1e-12:
            ledger["base_quantity"] = 0.0
            ledger["base_position_pct"] = 0.0
            ledger["base_avg_entry_price"] = 0.0
            ledger["base_entry_call"] = None
            ledger["base_layer"] = 0
            ledger["base_peak_price"] = 0.0
            ledger["base_peak_profit"] = 0.0
            ledger["base_source"] = ""


class V43ExpProtectedFloorV8Strategy(V43ExpProtectedFloorV7Strategy):
    """V4.3 experiment: protected-floor exit is one staged release per cycle."""

    PROTECTED_FLOOR_EXIT_COOLDOWN_CALLS = 120

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v8"

    def _protected_floor_exit_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        ledger = self._base_ledger_by_symbol.get(context.symbol)
        if ledger:
            last_exit = int(ledger.get("protected_floor_last_exit_call", -10_000) or -10_000)
            if self._call_count - last_exit < self.PROTECTED_FLOOR_EXIT_COOLDOWN_CALLS:
                return V42Sizing(side="sell", setup="protected-floor-exit", blocked_reason="protected_floor_exit_cooldown")
        return super()._protected_floor_exit_sizing(context, regime, signals, decision)

    def _record_protected_floor_base_exit(self, context: V42Context, action: Action) -> None:
        ledger = self._base_ledger_by_symbol.get(context.symbol)
        if ledger is not None:
            ledger["protected_floor_last_exit_call"] = self._call_count
        super()._record_protected_floor_base_exit(context, action)


class V43ExpProtectedFloorV9Strategy(V43ExpProtectedFloorV8Strategy):
    """V4.3 experiment: protected-floor blocked exits never preempt main flow."""

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v9"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        protected_exit = self._protected_floor_exit_sizing(context, regime, signals, decision)
        if protected_exit.side and protected_exit.quantity > 1e-12:
            return protected_exit
        return super(V43ExpProtectedFloorV7Strategy, self)._compute_sizing(context, regime, episode, signals, decision)


class V43ExpProtectedFloorV10Strategy(V43ExpProtectedFloorV6Strategy):
    """V4.3 experiment: event-based release for protected floor base sleeve."""

    PROTECTED_FLOOR_EXIT_MIN_HOLD_CALLS = 120
    PROTECTED_FLOOR_EXIT_PROFIT = 1.20
    PROTECTED_FLOOR_EXIT_REBOUND_PROFIT = 0.80
    PROTECTED_FLOOR_EXIT_FRACTION = 0.35
    PROTECTED_FLOOR_EXIT_MIN_NEW_HIGH = 0.18

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v10"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        protected_exit = self._protected_floor_exit_sizing(context, regime, signals, decision)
        if protected_exit.side and protected_exit.quantity > 1e-12:
            return protected_exit
        return super()._compute_sizing(context, regime, episode, signals, decision)

    def _record_protected_floor_base_buy(self, context: V42Context, action: Action) -> None:
        super()._record_protected_floor_base_buy(context, action)
        ledger = self._base_ledger_by_symbol.setdefault(context.symbol, self._new_base_ledger())
        old_qty = float(ledger.get("protected_floor_quantity", 0.0) or 0.0)
        old_entry = float(ledger.get("protected_floor_avg_entry_price", context.price) or context.price)
        add_qty = float(action.quantity)
        new_qty = old_qty + add_qty
        if new_qty > 0.0:
            ledger["protected_floor_avg_entry_price"] = (old_entry * old_qty + context.price * add_qty) / new_qty
        ledger["protected_floor_quantity"] = new_qty
        ledger["protected_floor_entry_call"] = ledger.get("protected_floor_entry_call") or self._call_count
        ledger["protected_floor_last_exit_call"] = ledger.get("protected_floor_last_exit_call")
        ledger["protected_floor_last_exit_price"] = float(ledger.get("protected_floor_last_exit_price", 0.0) or 0.0)

    def _protected_floor_exit_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        ledger = self._base_ledger_by_symbol.get(context.symbol)
        if not ledger or "protected_floor" not in str(ledger.get("base_source", "")):
            return V42Sizing()
        protected_qty = min(
            float(ledger.get("protected_floor_quantity", 0.0) or 0.0),
            self._base_quantity(context),
        )
        if protected_qty <= 1e-12:
            return V42Sizing()
        entry_call = ledger.get("protected_floor_entry_call") or ledger.get("base_entry_call")
        if entry_call is None or self._call_count - int(entry_call) < self.PROTECTED_FLOOR_EXIT_MIN_HOLD_CALLS:
            return V42Sizing()
        avg_entry = float(ledger.get("protected_floor_avg_entry_price", 0.0) or 0.0)
        if avg_entry <= 0.0:
            avg_entry = float(ledger.get("base_avg_entry_price", 0.0) or 0.0)
        if avg_entry <= 0.0:
            return V42Sizing()

        profit = context.price / avg_entry - 1.0
        if not self._protected_floor_exit_event(context, regime, signals, profit):
            return V42Sizing()
        if not self._protected_floor_new_release_event(context, ledger):
            return V42Sizing()

        sell_qty = min(protected_qty, protected_qty * self.PROTECTED_FLOOR_EXIT_FRACTION)
        notional = sell_qty * context.price
        if sell_qty <= 1e-12 or notional < self.min_notional:
            return V42Sizing()
        step_pct = notional / context.total_value if context.total_value > 0.0 else 0.0
        self._diag["v4_3_protected_floor_event_exit_count"] = (
            self._diag.get("v4_3_protected_floor_event_exit_count", 0) + 1
        )
        guard = self._join_guard(
            self._sizing_guard(context, regime, {"state": "PROTECTED_FLOOR_EVENT_EXIT"}, "protected-floor-exit"),
            "v4_3_protected_floor_event_release",
        )
        return V42Sizing(
            side="sell",
            setup="protected-floor-exit",
            quantity=sell_qty,
            target=max(0.0, context.current_pct - step_pct),
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=max(0.0, context.current_pct - step_pct),
            target_gap_before=step_pct,
            actual_step_pct=step_pct,
            remaining_gap_after=0.0,
        )

    def _protected_floor_exit_event(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        profit: float,
    ) -> bool:
        latest = context.latest
        rolling_pos = self._value(latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(latest, "donchian_pos", 0.5)
        roc_10 = self._value(latest, "roc_10", 0.0)
        roc_20 = self._value(latest, "roc_20", 0.0)
        price_vs_ema168 = self._value(
            latest,
            "price_vs_ema168",
            default=self._price_vs(latest, context.price, "ema168"),
        )
        strong_expansion = bool(
            roc_20 > 0.15
            and not signals.distribution_exhaustion
            and context.risk_score == 0
            and context.drawdown_risk == 0
        )
        if strong_expansion:
            return False

        high_location = bool(
            (not pd.isna(rolling_pos) and rolling_pos >= 0.80)
            or (not pd.isna(donchian_pos) and donchian_pos >= 0.88)
            or price_vs_ema168 >= 0.35
        )
        exhaustion = bool(
            signals.distribution_exhaustion
            or context.risk_score >= 1
            or (roc_10 <= 0.03 and roc_20 <= 0.10)
        )
        bull_exhaustion_release = bool(
            profit >= self.PROTECTED_FLOOR_EXIT_PROFIT
            and high_location
            and exhaustion
        )

        rebound_failure = bool(
            profit >= self.PROTECTED_FLOOR_EXIT_REBOUND_PROFIT
            and not pd.isna(donchian_pos)
            and donchian_pos >= 0.75
            and price_vs_ema168 >= 0.12
            and (signals.distribution_exhaustion or roc_10 <= 0.0 or context.risk_score >= 2)
        )
        return bull_exhaustion_release or rebound_failure

    def _protected_floor_new_release_event(self, context: V42Context, ledger: dict) -> bool:
        last_exit_price = float(ledger.get("protected_floor_last_exit_price", 0.0) or 0.0)
        if last_exit_price <= 0.0:
            return True
        return bool(context.price >= last_exit_price * (1.0 + self.PROTECTED_FLOOR_EXIT_MIN_NEW_HIGH))

    def _action_sleeve(self, decision: V42DecisionPlan, sizing: V42Sizing) -> str:
        if sizing.setup in {"opportunity-floor-buy", "protected-floor-exit"}:
            return "base"
        return super()._action_sleeve(decision, sizing)

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "sell" and sizing.setup == "protected-floor-exit":
            self._record_protected_floor_base_exit(context, action)

    def _record_protected_floor_base_exit(self, context: V42Context, action: Action) -> None:
        ledger = self._base_ledger_by_symbol.get(context.symbol)
        if not ledger:
            return
        sell_qty = float(action.quantity)
        protected_qty = max(0.0, float(ledger.get("protected_floor_quantity", 0.0) or 0.0) - sell_qty)
        base_qty = max(0.0, self._base_quantity(context) - sell_qty)
        ledger["protected_floor_quantity"] = protected_qty
        ledger["protected_floor_last_exit_call"] = self._call_count
        ledger["protected_floor_last_exit_price"] = context.price
        ledger["base_quantity"] = base_qty
        ledger["base_position_pct"] = self._base_pct_from_quantity(context, base_qty)
        if protected_qty <= 1e-12:
            ledger["protected_floor_quantity"] = 0.0
            ledger["protected_floor_avg_entry_price"] = 0.0
            ledger["protected_floor_entry_call"] = None
        if base_qty <= 1e-12:
            ledger["base_quantity"] = 0.0
            ledger["base_position_pct"] = 0.0
            ledger["base_avg_entry_price"] = 0.0
            ledger["base_entry_call"] = None
            ledger["base_layer"] = 0
            ledger["base_peak_price"] = 0.0
            ledger["base_peak_profit"] = 0.0
            ledger["base_source"] = ""


class V43ExpProtectedFloorV11Strategy(V43ExpProtectedFloorV10Strategy):
    """V4.3 experiment: event-based protected-floor release only for BNB."""

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v11"

    def _protected_floor_exit_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        if context.symbol != "BNB/USDT":
            return V42Sizing()
        return super()._protected_floor_exit_sizing(context, regime, signals, decision)


class V43ExpProtectedFloorV12Strategy(V43ExpProtectedFloorV11Strategy):
    """V4.3 experiment: later BNB protected-floor release after larger profit."""

    PROTECTED_FLOOR_EXIT_PROFIT = 2.20
    PROTECTED_FLOOR_EXIT_REBOUND_PROFIT = 2.20

    @property
    def name(self) -> str:
        return "v4_3_exp_protected_floor_v12"


class V44RecoveryPathV1Strategy(V43ExpProtectedFloorV11Strategy):
    """V4.4 architecture: established base becomes stage one of recovery path."""

    BASE_RECOVERY_MIN_BASE_PCT = 0.015
    BASE_RECOVERY_TARGET = {"BTC/USDT": 0.0, "ETH/USDT": 0.54, "BNB/USDT": 0.54}
    BASE_RECOVERY_MAX_TARGET = {"BTC/USDT": 0.0, "ETH/USDT": 0.78, "BNB/USDT": 0.78}
    BASE_RECOVERY_MAX_BUY_PCT = 0.08
    BASE_RECOVERY_COOLDOWN_CALLS = 6

    @property
    def name(self) -> str:
        return "v4_4_recovery_path_v1"

    def _base_recovery_established(self, context: V42Context) -> bool:
        if context.symbol == "BTC/USDT":
            return False
        return bool(self._base_pct_from_quantity(context, self._base_quantity(context)) >= self.BASE_RECOVERY_MIN_BASE_PCT)

    def _base_recovery_stabilized(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> bool:
        if regime.structural_bear:
            return False
        if signals.distribution_exhaustion:
            return False
        if context.trend_risk >= 4 or context.risk_score >= 5:
            return False
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        roc_10 = self._value(context.latest, "roc_10", 0.0)
        roc_20 = self._value(context.latest, "roc_20", 0.0)
        low_location = bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.45)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.55)
            or regime.price_vs_ema168 <= -0.08
        )
        stabilizing = bool(
            signals.recovery_signal
            or signals.recovery_quality_ok
            or signals.value_recovery
            or (context.trend_risk <= 2 and roc_10 > -0.08 and roc_20 > -0.16)
        )
        return bool(low_location and stabilizing)

    def _base_recovery_target(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> float:
        base_target = float(self.BASE_RECOVERY_TARGET.get(context.symbol, 0.0))
        if base_target <= 0.0:
            return 0.0
        if signals.strong_recovery_signal or signals.trend_continuation:
            base_target = max(base_target, 0.64)
        if regime.regime == "BULL" and context.risk_score <= 1:
            base_target = max(base_target, 0.70)
        cap = float(self.BASE_RECOVERY_MAX_TARGET.get(context.symbol, base_target))
        return min(cap, base_target, self.TARGET_CAP)

    def _choose_intent(self, context: V42Context, regime: V42Regime, episode: dict, signals: V42Signals) -> str:
        intent = super()._choose_intent(context, regime, episode, signals)
        if intent in {"HOLD", "DEFEND"} and self._base_recovery_should_accumulate(context, regime, signals):
            self._diag["v4_4_base_led_recovery_intent_count"] = self._diag.get("v4_4_base_led_recovery_intent_count", 0) + 1
            return "ACCUMULATE"
        return intent

    def _base_recovery_should_accumulate(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> bool:
        if not self._base_recovery_established(context):
            return False
        if not self._base_recovery_stabilized(context, regime, signals):
            return False
        target = self._base_recovery_target(context, regime, signals)
        if target <= 0.0 or context.current_pct >= target - self.RECOVERY_MIN_STEP:
            return False
        return bool(context.trend_risk <= 3 and context.risk_score <= 4)

    def _build_target_plan(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        intent: str,
    ) -> V42TargetPlan:
        plan = super()._build_target_plan(context, regime, episode, signals, intent)
        if intent != "ACCUMULATE" or not self._base_recovery_should_accumulate(context, regime, signals):
            return plan
        target = self._base_recovery_target(context, regime, signals)
        if target <= 0.0:
            return plan
        plan.tactical_target = max(float(plan.tactical_target), target)
        plan.phase_target = max(float(plan.phase_target), target)
        plan.mature_target = max(float(plan.mature_target), target)
        plan.execution_target_today = max(float(plan.execution_target_today), target)
        return plan

    def _episode_recovery_plan(self, context: V42Context, regime: V42Regime, episode: dict, signals: V42Signals) -> V42RecoveryPlan:
        plan = super()._episode_recovery_plan(context, regime, episode, signals)
        if not self._base_recovery_established(context) or not self._base_recovery_stabilized(context, regime, signals):
            return plan

        state = str(episode.get("state", "NORMAL"))
        if state not in {"DEFENSE_LOCK", "RECOVERY_TEST", "FAILED_RECOVERY_LOCK", "STRUCTURAL_BEAR_LOCK"}:
            return plan

        budget = self._episode_recovery_budget(episode)
        recovered = self._episode_recovered_pct(episode)
        remaining = max(0.0, budget - recovered)
        target = max(
            float(plan.get("target", context.current_pct) or context.current_pct),
            min(self._base_recovery_target(context, regime, signals), context.current_pct + remaining),
        )
        max_buy = max(
            float(plan.get("max_buy", 0.0) or 0.0),
            min(self.BASE_RECOVERY_MAX_BUY_PCT, max(self.RECOVERY_MIN_STEP, remaining)),
        )
        if remaining < self.RECOVERY_MIN_STEP or target <= context.current_pct + self.RECOVERY_MIN_STEP:
            return plan

        self._diag["v4_4_base_led_recovery_plan_count"] = self._diag.get("v4_4_base_led_recovery_plan_count", 0) + 1
        return V42RecoveryPlan(
            allowed=True,
            target=min(self.TARGET_CAP, target),
            max_buy=max_buy,
            drawdown=float(plan.get("drawdown", 0.0) or 0.0),
            remaining_budget=remaining,
            guard=self._join_guard(str(plan.get("guard", "")), "v4_4_base_led_recovery"),
            quality="base_led",
        )

    def _recovery_permission(self, context: V42Context, regime: V42Regime, signals: V42Signals, low_drop: float) -> V42RecoveryPlan:
        permission = super()._recovery_permission(context, regime, signals, low_drop)
        if bool(permission.get("allowed", False)):
            return permission
        if self._base_recovery_established(context) and self._base_recovery_stabilized(context, regime, signals):
            self._diag["v4_4_base_led_recovery_permission_count"] = (
                self._diag.get("v4_4_base_led_recovery_permission_count", 0) + 1
            )
            return V42RecoveryPlan(allowed=True, quality="base_led")
        return permission

    def _buy_cooldown(self, context: V42Context, regime: V42Regime, setup: str) -> int:
        base = super()._buy_cooldown(context, regime, setup)
        if setup in {"recovery-probe-buy", "value-recovery"} and self._base_recovery_established(context):
            return min(base, self.BASE_RECOVERY_COOLDOWN_CALLS)
        return base

    def _max_buy_pct(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        setup: str,
        signals: V42Signals | None = None,
    ) -> float:
        base = super()._max_buy_pct(context, regime, episode, setup, signals)
        if setup in {"recovery-probe-buy", "value-recovery"} and self._base_recovery_established(context):
            if signals is None:
                signals = self._build_signals(context, regime, episode)
            if self._base_recovery_stabilized(context, regime, signals):
                base = max(base, self.BASE_RECOVERY_MAX_BUY_PCT)
        return base


class V44RecoveryPathV2Strategy(V44RecoveryPathV1Strategy):
    """V4.4 architecture v2: base-led recovery only before the low-base edge is gone."""

    BASE_RECOVERY_TARGET = {"BTC/USDT": 0.0, "ETH/USDT": 0.46, "BNB/USDT": 0.46}
    BASE_RECOVERY_MAX_TARGET = {"BTC/USDT": 0.0, "ETH/USDT": 0.62, "BNB/USDT": 0.62}
    BASE_RECOVERY_MAX_BUY_PCT = 0.05
    BASE_RECOVERY_MAX_ENTRY_MULTIPLE = 1.65

    @property
    def name(self) -> str:
        return "v4_4_recovery_path_v2"

    def _choose_intent(self, context: V42Context, regime: V42Regime, episode: dict, signals: V42Signals) -> str:
        intent = super(V44RecoveryPathV1Strategy, self)._choose_intent(context, regime, episode, signals)
        state = str(episode.get("state", "NORMAL"))
        if (
            intent in {"HOLD", "DEFEND"}
            and state in {"DEFENSE_LOCK", "RECOVERY_TEST", "FAILED_RECOVERY_LOCK", "STRUCTURAL_BEAR_LOCK"}
            and self._base_recovery_should_accumulate(context, regime, signals)
        ):
            self._diag["v4_4_base_led_recovery_intent_count"] = self._diag.get("v4_4_base_led_recovery_intent_count", 0) + 1
            return "ACCUMULATE"
        return intent

    def _base_recovery_stabilized(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> bool:
        if not super()._base_recovery_stabilized(context, regime, signals):
            return False
        if regime.regime == "BULL" or context.confirmed_state == "BULL":
            return False
        ledger = self._base_ledger_by_symbol.get(context.symbol, {})
        avg_entry = float(ledger.get("protected_floor_avg_entry_price", 0.0) or ledger.get("base_avg_entry_price", 0.0) or 0.0)
        if avg_entry > 0.0 and context.price > avg_entry * self.BASE_RECOVERY_MAX_ENTRY_MULTIPLE:
            return False
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.35)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.45)
            or regime.price_vs_ema168 <= 0.02
        )


class V44RecoveryPathV3Strategy(V43ExpProtectedFloorV11Strategy):
    """V4.4 architecture v3: base-led recovery adds to base sleeve, not main."""

    BASE_RECOVERY_MIN_BASE_PCT = 0.015
    BASE_LED_RECOVERY_TARGET = {"BTC/USDT": 0.0, "ETH/USDT": 0.12, "BNB/USDT": 0.12}
    BASE_LED_RECOVERY_MAX_BUY_PCT = 0.03
    BASE_LED_RECOVERY_COOLDOWN_CALLS = 20
    BASE_LED_RECOVERY_MAX_ENTRY_MULTIPLE = 1.45

    @property
    def name(self) -> str:
        return "v4_4_recovery_path_v3"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        primary = super()._compute_sizing(context, regime, episode, signals, decision)
        if primary.side and primary.quantity > 1e-12:
            return primary
        candidate = self._base_led_recovery_base_sizing(context, regime, episode, signals, decision, primary)
        if candidate.side:
            return candidate
        return primary

    def _base_led_recovery_base_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        primary: V42Sizing,
    ) -> V42Sizing:
        if not self._base_led_recovery_allowed(context, regime, episode, signals):
            return V42Sizing()
        target = float(self.BASE_LED_RECOVERY_TARGET.get(context.symbol, 0.0))
        base_pct = self._base_pct_from_quantity(context, self._base_quantity(context))
        if target <= 0.0 or base_pct >= target - self.RECOVERY_MIN_STEP:
            return V42Sizing()
        last_buy = int(getattr(self, "_last_base_led_recovery_buy_call_by_symbol", {}).get(context.symbol, -10_000))
        if self._call_count - last_buy < self.BASE_LED_RECOVERY_COOLDOWN_CALLS:
            return V42Sizing()
        gap = max(0.0, target - base_pct)
        buy_pct = min(gap, self.BASE_LED_RECOVERY_MAX_BUY_PCT)
        if buy_pct < self.RECOVERY_MIN_STEP:
            return V42Sizing()
        buy_qty = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup="base-led-recovery-buy", blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup="base-led-recovery-buy", blocked_reason="min_notional")
        self._diag["v4_4_base_led_recovery_base_buy_count"] = self._diag.get("v4_4_base_led_recovery_base_buy_count", 0) + 1
        guard = self._join_guard(
            self._sizing_guard(context, regime, episode, "recovery-probe-buy"),
            "v4_4_base_led_recovery_base",
        )
        decision.primary_sleeve = V42SleevePlan(
            sleeve="base-led-recovery",
            side="buy",
            setup="base-led-recovery-buy",
            target=min(self.TARGET_CAP, context.current_pct + buy_pct),
            guard=guard,
            priority=82,
            allowed=True,
        )
        return V42Sizing(
            side="buy",
            setup="base-led-recovery-buy",
            quantity=buy_qty,
            target=min(self.TARGET_CAP, context.current_pct + buy_pct),
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=gap,
            actual_step_pct=buy_pct,
            remaining_gap_after=max(0.0, gap - buy_pct),
        )

    def _base_led_recovery_allowed(self, context: V42Context, regime: V42Regime, episode: dict, signals: V42Signals) -> bool:
        if context.symbol == "BTC/USDT":
            return False
        if str(episode.get("state", "NORMAL")) not in {"DEFENSE_LOCK", "RECOVERY_TEST", "FAILED_RECOVERY_LOCK", "STRUCTURAL_BEAR_LOCK"}:
            return False
        if self._base_pct_from_quantity(context, self._base_quantity(context)) < self.BASE_RECOVERY_MIN_BASE_PCT:
            return False
        if regime.structural_bear or signals.distribution_exhaustion:
            return False
        if regime.regime == "BULL" or context.confirmed_state == "BULL":
            return False
        if context.trend_risk >= 3 or context.risk_score >= 4:
            return False
        ledger = self._base_ledger_by_symbol.get(context.symbol, {})
        avg_entry = float(ledger.get("protected_floor_avg_entry_price", 0.0) or ledger.get("base_avg_entry_price", 0.0) or 0.0)
        if avg_entry > 0.0 and context.price > avg_entry * self.BASE_LED_RECOVERY_MAX_ENTRY_MULTIPLE:
            return False
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        roc_10 = self._value(context.latest, "roc_10", 0.0)
        return bool(
            (
                (not pd.isna(rolling_pos) and rolling_pos <= 0.32)
                or (not pd.isna(donchian_pos) and donchian_pos <= 0.42)
                or regime.price_vs_ema168 <= -0.04
            )
            and (signals.recovery_signal or signals.recovery_quality_ok or roc_10 > -0.06)
        )

    def _action_sleeve(self, decision: V42DecisionPlan, sizing: V42Sizing) -> str:
        if sizing.setup == "base-led-recovery-buy":
            return "base"
        return super()._action_sleeve(decision, sizing)

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        if action is not None and action.side == "buy" and sizing.setup == "base-led-recovery-buy":
            self._record_base_led_recovery_buy(context, action)
            calls = getattr(self, "_last_base_led_recovery_buy_call_by_symbol", None)
            if calls is None:
                self._last_base_led_recovery_buy_call_by_symbol = {}
                calls = self._last_base_led_recovery_buy_call_by_symbol
            calls[context.symbol] = self._call_count
        return super()._record_event(context, regime, episode, decision, sizing, action)

    def _record_base_led_recovery_buy(self, context: V42Context, action: Action) -> None:
        ledger = self._base_ledger_by_symbol.setdefault(context.symbol, self._new_base_ledger())
        buy_pct = action.quantity * action.price / context.total_value if context.total_value > 0.0 else 0.0
        old_base_qty = float(ledger.get("base_quantity", 0.0) or 0.0)
        old_entry = float(ledger.get("base_avg_entry_price", context.price) or context.price)
        new_base_qty = old_base_qty + float(action.quantity)
        if new_base_qty > 0.0:
            ledger["base_avg_entry_price"] = (old_entry * old_base_qty + context.price * float(action.quantity)) / new_base_qty
        ledger["base_budget_used_pct"] = self._ledger_base_budget_used_pct(ledger) + max(0.0, buy_pct)
        ledger["base_quantity"] = new_base_qty
        ledger["base_position_pct"] = self._base_pct_from_quantity(context, new_base_qty)
        ledger["base_source"] = self._join_guard(str(ledger.get("base_source", "")), "base_led_recovery")
        ledger["base_layer"] = max(int(ledger.get("base_layer", 0) or 0), 2)
        if ledger.get("base_entry_call") is None:
            ledger["base_entry_call"] = self._call_count
            ledger["base_peak_price"] = context.price
            ledger["base_peak_profit"] = 0.0


class V44RecoveryPathV4Strategy(V44RecoveryPathV3Strategy):
    """V4.4 architecture v4: BNB base-led lots release only through protected event exits."""

    @property
    def name(self) -> str:
        return "v4_4_recovery_path_v4"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        if (
            context.symbol == "BNB/USDT"
            and sizing.side == "sell"
            and sizing.setup == "bear-base-exit"
            and "base_led_recovery" in str(self._base_ledger_by_symbol.get(context.symbol, {}).get("base_source", ""))
        ):
            self._diag["v4_4_bnb_base_led_bear_exit_blocked_count"] = (
                self._diag.get("v4_4_bnb_base_led_bear_exit_blocked_count", 0) + 1
            )
            return V42Sizing()
        return sizing

    def _record_base_led_recovery_buy(self, context: V42Context, action: Action) -> None:
        super()._record_base_led_recovery_buy(context, action)
        if context.symbol != "BNB/USDT":
            return
        ledger = self._base_ledger_by_symbol.setdefault(context.symbol, self._new_base_ledger())
        old_qty = float(ledger.get("protected_floor_quantity", 0.0) or 0.0)
        old_entry = float(ledger.get("protected_floor_avg_entry_price", context.price) or context.price)
        add_qty = float(action.quantity)
        new_qty = old_qty + add_qty
        if new_qty > 0.0:
            ledger["protected_floor_avg_entry_price"] = (old_entry * old_qty + context.price * add_qty) / new_qty
        ledger["protected_floor_quantity"] = new_qty
        ledger["protected_floor_entry_call"] = ledger.get("protected_floor_entry_call") or self._call_count


class V44RecoveryPathV5Strategy(V43ExpProtectedFloorV11Strategy):
    """V4.4 architecture v5: route existing low recovery buys into base without adding budget."""

    RECOVERY_ROUTE_MAX_ENTRY_MULTIPLE = 1.50

    @property
    def name(self) -> str:
        return "v4_4_recovery_path_v5"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        if self._route_recovery_buy_to_base(context, regime, episode, signals, sizing):
            sizing.setup = "base-led-recovery-buy"
            sizing.guard = self._join_guard(str(sizing.guard), "v4_4_base_led_recovery_route")
            if decision.primary_sleeve is not None:
                decision.primary_sleeve = V42SleevePlan(
                    sleeve="base-led-recovery",
                    side="buy",
                    setup="base-led-recovery-buy",
                    target=sizing.target,
                    guard=sizing.guard,
                    priority=max(82, int(decision.primary_sleeve.priority)),
                    allowed=True,
                )
            self._diag["v4_4_base_led_recovery_routed_count"] = (
                self._diag.get("v4_4_base_led_recovery_routed_count", 0) + 1
            )
        return sizing

    def _route_recovery_buy_to_base(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        sizing: V42Sizing,
    ) -> bool:
        if context.symbol == "BTC/USDT":
            return False
        if sizing.side != "buy" or sizing.quantity <= 1e-12:
            return False
        if sizing.setup not in {"recovery-probe-buy", "value-recovery"}:
            return False
        if str(episode.get("state", "NORMAL")) not in {"DEFENSE_LOCK", "RECOVERY_TEST", "FAILED_RECOVERY_LOCK", "STRUCTURAL_BEAR_LOCK"}:
            return False
        if self._base_pct_from_quantity(context, self._base_quantity(context)) < 0.015:
            return False
        if regime.structural_bear or signals.distribution_exhaustion:
            return False
        if context.trend_risk >= 3 or context.risk_score >= 4:
            return False
        ledger = self._base_ledger_by_symbol.get(context.symbol, {})
        avg_entry = float(ledger.get("protected_floor_avg_entry_price", 0.0) or ledger.get("base_avg_entry_price", 0.0) or 0.0)
        if avg_entry > 0.0 and context.price > avg_entry * self.RECOVERY_ROUTE_MAX_ENTRY_MULTIPLE:
            return False
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.35)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.45)
            or regime.price_vs_ema168 <= 0.02
        )

    def _action_sleeve(self, decision: V42DecisionPlan, sizing: V42Sizing) -> str:
        if sizing.setup == "base-led-recovery-buy":
            return "base"
        return super()._action_sleeve(decision, sizing)

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        if action is not None and action.side == "buy" and sizing.setup == "base-led-recovery-buy":
            self._record_routed_recovery_base_buy(context, action)
        return super()._record_event(context, regime, episode, decision, sizing, action)

    def _record_routed_recovery_base_buy(self, context: V42Context, action: Action) -> None:
        ledger = self._base_ledger_by_symbol.setdefault(context.symbol, self._new_base_ledger())
        buy_pct = action.quantity * action.price / context.total_value if context.total_value > 0.0 else 0.0
        old_base_qty = float(ledger.get("base_quantity", 0.0) or 0.0)
        old_entry = float(ledger.get("base_avg_entry_price", context.price) or context.price)
        new_base_qty = old_base_qty + float(action.quantity)
        if new_base_qty > 0.0:
            ledger["base_avg_entry_price"] = (old_entry * old_base_qty + context.price * float(action.quantity)) / new_base_qty
        ledger["base_budget_used_pct"] = self._ledger_base_budget_used_pct(ledger) + max(0.0, buy_pct)
        ledger["base_quantity"] = new_base_qty
        ledger["base_position_pct"] = self._base_pct_from_quantity(context, new_base_qty)
        ledger["base_source"] = self._join_guard(str(ledger.get("base_source", "")), "base_led_recovery")
        ledger["base_layer"] = max(int(ledger.get("base_layer", 0) or 0), 2)


class V44RecoveryPathV6Strategy(V43ExpProtectedFloorV11Strategy):
    """V4.4 architecture v6: source-level base ledger with explicit sell permissions."""

    @property
    def name(self) -> str:
        return "v4_4_recovery_path_v6"

    def _source_ledger(self, symbol: str) -> dict:
        ledger = self._base_ledger_by_symbol.setdefault(symbol, self._new_base_ledger())
        sources = ledger.setdefault("source_ledger", {})
        return sources

    def _sync_base_from_sources(self, context: V42Context) -> None:
        ledger = self._base_ledger_by_symbol.setdefault(context.symbol, self._new_base_ledger())
        sources = ledger.setdefault("source_ledger", {})
        total_qty = sum(max(0.0, float(src.get("quantity", 0.0) or 0.0)) for src in sources.values())
        ledger["base_quantity"] = total_qty
        ledger["base_position_pct"] = self._base_pct_from_quantity(context, total_qty)
        if total_qty > 0.0:
            total_cost = sum(
                max(0.0, float(src.get("quantity", 0.0) or 0.0)) * max(0.0, float(src.get("avg_entry", 0.0) or 0.0))
                for src in sources.values()
            )
            ledger["base_avg_entry_price"] = total_cost / total_qty if total_qty > 0.0 else 0.0
            ledger["base_source"] = "-".join(sorted(src for src, row in sources.items() if float(row.get("quantity", 0.0) or 0.0) > 1e-12))
        else:
            ledger["base_quantity"] = 0.0
            ledger["base_position_pct"] = 0.0
            ledger["base_avg_entry_price"] = 0.0
            ledger["base_entry_call"] = None
            ledger["base_layer"] = 0
            ledger["base_peak_price"] = 0.0
            ledger["base_peak_profit"] = 0.0
            ledger["base_source"] = ""

    def _add_base_source(self, context: V42Context, action: Action, source: str, layer: int = 1) -> None:
        ledger = self._base_ledger_by_symbol.setdefault(context.symbol, self._new_base_ledger())
        sources = ledger.setdefault("source_ledger", {})
        row = sources.setdefault(source, {"quantity": 0.0, "avg_entry": 0.0, "entry_call": self._call_count})
        old_qty = float(row.get("quantity", 0.0) or 0.0)
        old_entry = float(row.get("avg_entry", context.price) or context.price)
        add_qty = float(action.quantity)
        new_qty = old_qty + add_qty
        row["quantity"] = new_qty
        row["avg_entry"] = (old_entry * old_qty + context.price * add_qty) / new_qty if new_qty > 0.0 else 0.0
        row["entry_call"] = row.get("entry_call") or self._call_count
        ledger["base_layer"] = max(int(ledger.get("base_layer", 0) or 0), int(layer))
        if ledger.get("base_entry_call") is None:
            ledger["base_entry_call"] = self._call_count
            ledger["base_peak_price"] = context.price
            ledger["base_peak_profit"] = 0.0
        self._sync_base_from_sources(context)

    def _source_quantity(self, context: V42Context, source: str) -> float:
        sources = self._base_ledger_by_symbol.get(context.symbol, {}).get("source_ledger", {})
        return max(0.0, float(sources.get(source, {}).get("quantity", 0.0) or 0.0))

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        if context.symbol == "BNB/USDT" and sizing.side == "sell" and sizing.setup == "bear-base-exit":
            strategic_qty = min(self._source_quantity(context, "strategic_base"), self._base_quantity(context))
            if strategic_qty <= 1e-12:
                return V42Sizing()
            if sizing.quantity > strategic_qty:
                sizing.quantity = strategic_qty
                actual_sell_pct = sizing.quantity * context.price / context.total_value if context.total_value > 0.0 else 0.0
                sizing.actual_step_pct = -actual_sell_pct
                sizing.actual_position_after = max(0.0, context.current_pct - actual_sell_pct)
                sizing.remaining_gap_after = sizing.target - sizing.actual_position_after
                sizing.guard = self._join_guard(str(sizing.guard), "v4_4_source_limited_base_exit")
        return sizing

    def _consume_base_sources(self, context: V42Context, quantity: float, sources_allowed: tuple[str, ...]) -> float:
        ledger = self._base_ledger_by_symbol.get(context.symbol)
        if not ledger:
            return 0.0
        sources = ledger.setdefault("source_ledger", {})
        remaining = max(0.0, float(quantity))
        consumed = 0.0
        for source in sources_allowed:
            if remaining <= 1e-12:
                break
            row = sources.get(source)
            if not row:
                continue
            qty = max(0.0, float(row.get("quantity", 0.0) or 0.0))
            take = min(qty, remaining)
            row["quantity"] = max(0.0, qty - take)
            remaining -= take
            consumed += take
        self._sync_base_from_sources(context)
        return consumed

    def _record_protected_floor_base_buy(self, context: V42Context, action: Action) -> None:
        super()._record_protected_floor_base_buy(context, action)
        self._add_base_source(context, action, "protected_floor", layer=1)
        ledger = self._base_ledger_by_symbol.setdefault(context.symbol, self._new_base_ledger())
        source_qty = self._source_quantity(context, "protected_floor")
        source = ledger.get("source_ledger", {}).get("protected_floor", {})
        ledger["protected_floor_quantity"] = source_qty
        ledger["protected_floor_avg_entry_price"] = float(source.get("avg_entry", 0.0) or 0.0)
        ledger["protected_floor_entry_call"] = source.get("entry_call") or self._call_count

    def _record_bear_base_buy(self, context: V42Context, action: Action) -> None:
        super()._record_bear_base_buy(context, action)
        layer = int(self._base_ledger_by_symbol.get(context.symbol, {}).get("base_layer", 1) or 1)
        self._add_base_source(context, action, "strategic_base", layer=layer)

    def _record_base_led_recovery_buy(self, context: V42Context, action: Action) -> None:
        self._add_base_source(context, action, "base_led_recovery", layer=2)

    def _protected_floor_exit_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        if context.symbol != "BNB/USDT":
            return V42Sizing()
        ledger = self._base_ledger_by_symbol.get(context.symbol)
        if not ledger:
            return V42Sizing()
        protected_qty = min(self._source_quantity(context, "protected_floor"), self._base_quantity(context))
        if protected_qty <= 1e-12:
            return V42Sizing()
        return super(V43ExpProtectedFloorV11Strategy, self)._protected_floor_exit_sizing(context, regime, signals, decision)

    def _record_protected_floor_base_exit(self, context: V42Context, action: Action) -> None:
        ledger = self._base_ledger_by_symbol.get(context.symbol)
        if not ledger:
            return
        consumed = self._consume_base_sources(context, float(action.quantity), ("protected_floor",))
        ledger["protected_floor_quantity"] = self._source_quantity(context, "protected_floor")
        ledger["protected_floor_last_exit_call"] = self._call_count
        ledger["protected_floor_last_exit_price"] = context.price
        if consumed <= 1e-12:
            return

    def _record_base_exit_sell(self, context: V42Context, action: Action) -> None:
        ledger = self._base_ledger_by_symbol.get(context.symbol)
        if ledger and "source_ledger" in ledger:
            allowed = ("strategic_base",)
            if context.symbol != "BNB/USDT":
                allowed = ("strategic_base", "protected_floor", "base_led_recovery")
            consumed = self._consume_base_sources(context, float(action.quantity), allowed)
            if consumed > 1e-12:
                self._diag["v4_2_bear_base_exit_count"] += 1
            return
        return super()._record_base_exit_sell(context, action)


class V44RecoveryPathV7Strategy(V44RecoveryPathV6Strategy):
    """V4.4 architecture v7: ETH recovery fills become base source without adding budget."""

    RECOVERY_ROUTE_MAX_ENTRY_MULTIPLE = 1.50

    @property
    def name(self) -> str:
        return "v4_4_recovery_path_v7"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        if self._route_eth_recovery_buy_to_base(context, regime, episode, signals, sizing):
            sizing.setup = "base-led-recovery-buy"
            sizing.guard = self._join_guard(str(sizing.guard), "v4_4_eth_recovery_to_base")
            decision.primary_sleeve = V42SleevePlan(
                sleeve="base-led-recovery",
                side="buy",
                setup="base-led-recovery-buy",
                target=sizing.target,
                guard=sizing.guard,
                priority=82,
                allowed=True,
            )
            self._diag["v4_4_eth_recovery_to_base_count"] = self._diag.get("v4_4_eth_recovery_to_base_count", 0) + 1
        return sizing

    def _route_eth_recovery_buy_to_base(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        sizing: V42Sizing,
    ) -> bool:
        if context.symbol != "ETH/USDT":
            return False
        if sizing.side != "buy" or sizing.quantity <= 1e-12:
            return False
        if sizing.setup not in {"recovery-probe-buy", "value-recovery"}:
            return False
        if str(episode.get("state", "NORMAL")) not in {"DEFENSE_LOCK", "RECOVERY_TEST", "FAILED_RECOVERY_LOCK", "STRUCTURAL_BEAR_LOCK"}:
            return False
        if self._base_pct_from_quantity(context, self._base_quantity(context)) < 0.015:
            return False
        if regime.structural_bear or signals.distribution_exhaustion:
            return False
        if context.trend_risk >= 3 or context.risk_score >= 4:
            return False
        ledger = self._base_ledger_by_symbol.get(context.symbol, {})
        avg_entry = float(ledger.get("base_avg_entry_price", 0.0) or 0.0)
        if avg_entry > 0.0 and context.price > avg_entry * self.RECOVERY_ROUTE_MAX_ENTRY_MULTIPLE:
            return False
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.35)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.45)
            or regime.price_vs_ema168 <= 0.02
        )

    def _action_sleeve(self, decision: V42DecisionPlan, sizing: V42Sizing) -> str:
        if sizing.setup == "base-led-recovery-buy":
            return "base"
        return super()._action_sleeve(decision, sizing)

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        if action is not None and action.side == "buy" and sizing.setup == "base-led-recovery-buy":
            self._add_base_source(context, action, "base_led_recovery", layer=2)
        return super()._record_event(context, regime, episode, decision, sizing, action)


class V45LifecycleStrategy(V44RecoveryPathV7Strategy):
    """V4.5 refactor pass: formal lifecycle state shadow over the accepted v4.4/v7 behavior."""

    ENABLE_ARCH_AUDIT = True
    ENABLE_LIFECYCLE_LOW_BASE_BEHAVIOR = False
    ENABLE_LIFECYCLE_BASE_EXIT_BEHAVIOR = False
    LIFECYCLE_LOW_BASE_CAP = {"BTC/USDT": 0.00, "ETH/USDT": 0.00, "BNB/USDT": 0.00}
    LIFECYCLE_LOW_BASE_PORTFOLIO_CAP = 0.14
    LIFECYCLE_LOW_BASE_MAX_BUY_PCT = 0.02
    LIFECYCLE_LOW_BASE_COOLDOWN_CALLS = 45
    LIFECYCLE_BASE_EXIT_MIN_HOLD_CALLS = 90
    LIFECYCLE_BASE_EXIT_PROFIT_PCT = 0.75
    LIFECYCLE_BASE_EXIT_DISTRIBUTION_PROFIT_PCT = 0.45
    SPOT_EXPOSURE_CAP = 1.00

    @property
    def name(self) -> str:
        return "v4_5"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._lifecycle_state_shadow: list[dict] = []
        self._last_lifecycle_low_base_buy_call_by_symbol: dict[str, int] = {}
        self._v45_lifecycle_policy = V45LifecyclePolicy(
            target_cap=self.TARGET_CAP,
            target_table=self.TARGET_TABLE,
            recovery_min_step=self.RECOVERY_MIN_STEP,
        )

    def strategy_lifecycle_state_shadow(self) -> list[dict]:
        return list(self._lifecycle_state_shadow)

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        if sizing.side == "sell" and sizing.quantity > 1e-12:
            return sizing
        if bool(getattr(self, "ENABLE_LIFECYCLE_BASE_EXIT_BEHAVIOR", False)):
            base_exit = self._lifecycle_protected_base_exit_sizing(context, regime, signals, decision)
            if base_exit.side:
                return base_exit
        if sizing.side == "buy" and sizing.quantity > 1e-12:
            return sizing
        if bool(getattr(self, "ENABLE_LIFECYCLE_LOW_BASE_BEHAVIOR", False)):
            low_base = self._lifecycle_low_base_sizing(context, regime, episode, signals, decision, sizing)
            if low_base.side:
                return low_base
        return sizing

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        result = super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "buy" and "v4_5_lifecycle_low_base" in str(sizing.guard):
            self._last_lifecycle_low_base_buy_call_by_symbol[context.symbol] = self._call_count
        self._record_lifecycle_state_shadow(context, regime, episode, decision, sizing, action)
        return result

    def _lifecycle_low_base_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        cap = max(0.0, float(self.LIFECYCLE_LOW_BASE_CAP.get(context.symbol, 0.0)))
        if cap <= 0.0:
            return V42Sizing()
        if context.current_pct > cap + self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="lifecycle_low_base_total_exposure_filled")
        if not self._lifecycle_low_base_entry_location(context, regime):
            return V42Sizing()
        if not self._lifecycle_low_base_stabilizing(context, regime, signals):
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="lifecycle_low_base_not_stabilizing")
        if signals.distribution_exhaustion:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="lifecycle_low_base_distribution")
        source_qty = self._source_quantity(context, "protected_floor")
        source_pct = self._base_pct_from_quantity(context, source_qty)
        if source_pct >= cap - self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="lifecycle_low_base_cap_filled")
        portfolio_room = max(0.0, self.LIFECYCLE_LOW_BASE_PORTFOLIO_CAP - self._lifecycle_protected_floor_portfolio_pct(context))
        if portfolio_room < self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="lifecycle_low_base_portfolio_cap")
        spot_room = max(0.0, self.SPOT_EXPOSURE_CAP - float(context.current_pct))
        if spot_room < self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="spot_exposure_cap")
        last_buy = self._last_lifecycle_low_base_buy_call_by_symbol.get(context.symbol, -10_000)
        if self._call_count - last_buy < self.LIFECYCLE_LOW_BASE_COOLDOWN_CALLS:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="lifecycle_low_base_cooldown")
        gap = min(max(0.0, cap - source_pct), portfolio_room, spot_room)
        buy_pct = min(gap, self.LIFECYCLE_LOW_BASE_MAX_BUY_PCT)
        if buy_pct < self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="lifecycle_low_base_step_too_small")
        buy_qty = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="min_notional")
        guard = self._join_guard(
            self._sizing_guard(context, regime, episode, "opportunity-floor-buy"),
            "v4_5_lifecycle_low_base",
        )
        decision.primary_sleeve = V42SleevePlan(
            sleeve="lifecycle-low-base",
            side="buy",
            setup="opportunity-floor-buy",
            target=min(self.SPOT_EXPOSURE_CAP, context.current_pct + buy_pct),
            guard=guard,
            priority=86,
            allowed=True,
        )
        self._diag["v4_5_lifecycle_low_base_buy_count"] = self._diag.get("v4_5_lifecycle_low_base_buy_count", 0) + 1
        return V42Sizing(
            side="buy",
            setup="opportunity-floor-buy",
            quantity=buy_qty,
            target=min(self.SPOT_EXPOSURE_CAP, context.current_pct + buy_pct),
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=gap,
            actual_step_pct=buy_pct,
            remaining_gap_after=max(0.0, gap - buy_pct),
        )

    def _lifecycle_protected_base_exit_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        source_qty = min(self._source_quantity(context, "protected_floor"), self._base_quantity(context))
        if source_qty <= 1e-12:
            return V42Sizing()
        sources = self._base_ledger_by_symbol.get(context.symbol, {}).get("source_ledger", {})
        row = sources.get("protected_floor", {})
        avg_entry = float(row.get("avg_entry", 0.0) or 0.0)
        if avg_entry <= 0.0:
            return V42Sizing()
        entry_call = int(row.get("entry_call", self._call_count) or self._call_count)
        if self._call_count - entry_call < self.LIFECYCLE_BASE_EXIT_MIN_HOLD_CALLS:
            return V42Sizing(side="sell", setup="protected-floor-exit", blocked_reason="lifecycle_base_exit_min_hold")
        profit = context.price / avg_entry - 1.0
        high_location = self._lifecycle_base_exit_high_location(context, regime)
        distribution_exit = bool(signals.distribution_exhaustion and profit >= self.LIFECYCLE_BASE_EXIT_DISTRIBUTION_PROFIT_PCT)
        normal_exit = bool(high_location and profit >= self.LIFECYCLE_BASE_EXIT_PROFIT_PCT)
        if not (distribution_exit or normal_exit):
            return V42Sizing()
        sell_qty = source_qty
        if sell_qty <= 1e-12:
            return V42Sizing(side="sell", setup="protected-floor-exit", blocked_reason="zero_quantity")
        notional = sell_qty * context.price
        if notional < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="sell", setup="protected-floor-exit", blocked_reason="min_notional")
        sell_pct = notional / context.total_value if context.total_value > 0.0 else 0.0
        guard = self._join_guard(
            self._sizing_guard(context, regime, {"state": "LIFECYCLE_BASE_EXIT"}, "protected-floor-exit"),
            "v4_5_lifecycle_base_exit",
        )
        decision.primary_sleeve = V42SleevePlan(
            sleeve="lifecycle-base-exit",
            side="sell",
            setup="protected-floor-exit",
            target=max(0.0, context.current_pct - sell_pct),
            guard=guard,
            priority=84,
            allowed=True,
        )
        self._diag["v4_5_lifecycle_base_exit_count"] = self._diag.get("v4_5_lifecycle_base_exit_count", 0) + 1
        return V42Sizing(
            side="sell",
            setup="protected-floor-exit",
            quantity=sell_qty,
            target=max(0.0, context.current_pct - sell_pct),
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=max(0.0, context.current_pct - sell_pct),
            target_gap_before=sell_pct,
            actual_step_pct=-sell_pct,
            remaining_gap_after=0.0,
        )

    def _lifecycle_base_exit_high_location(self, context: V42Context, regime: V42Regime) -> bool:
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos >= 0.78)
            or (not pd.isna(donchian_pos) and donchian_pos >= 0.82)
            or (not pd.isna(regime.price_vs_ema168) and regime.price_vs_ema168 >= 0.28)
        )

    def _lifecycle_low_base_entry_location(self, context: V42Context, regime: V42Regime) -> bool:
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        deep_discount = bool(
            not pd.isna(regime.price_vs_ema168)
            and regime.price_vs_ema168 <= -0.20
            and (
                (not pd.isna(rolling_pos) and rolling_pos <= 0.35)
                or (not pd.isna(donchian_pos) and donchian_pos <= 0.35)
            )
        )
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.18)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.25)
            or deep_discount
        )

    def _lifecycle_low_base_stabilizing(self, context: V42Context, regime: V42Regime, signals: V42Signals) -> bool:
        if context.risk_score >= 5:
            return False
        recent = context.df.tail(20)
        if recent.empty or "close" not in recent.columns:
            return bool(signals.recovery_signal or signals.recovery_quality_ok)
        recent_low = float(recent["close"].min())
        rebound = context.price / recent_low - 1.0 if recent_low > 0.0 else 0.0
        roc_5 = self._value(context.latest, "roc_5", 0.0)
        roc_20 = self._value(context.latest, "roc_20", 0.0)
        waterfall = bool(not pd.isna(roc_20) and roc_20 <= -0.25 and rebound < 0.04)
        if waterfall:
            return False
        return bool(
            rebound >= 0.025
            or (not pd.isna(roc_5) and roc_5 >= -0.03)
            or signals.recovery_signal
            or signals.recovery_quality_ok
        )

    def _lifecycle_protected_floor_portfolio_pct(self, context: V42Context) -> float:
        total = 0.0
        for symbol in self.TARGET_ALLOC:
            if symbol == context.symbol:
                total += self._base_pct_from_quantity(context, self._source_quantity(context, "protected_floor"))
                continue
            ledger = self._base_ledger_by_symbol.get(symbol, {})
            sources = ledger.get("source_ledger", {})
            protected = max(0.0, float(sources.get("protected_floor", {}).get("quantity", 0.0) or 0.0))
            base_qty = max(0.0, float(ledger.get("base_quantity", 0.0) or 0.0))
            base_pct = max(0.0, float(ledger.get("base_position_pct", 0.0) or 0.0))
            total += base_pct * protected / base_qty if base_qty > 1e-12 else 0.0
        return total

    def _record_lifecycle_state_shadow(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        signals = self._build_signals(context, regime, episode)
        lifecycle = self._v45_lifecycle_policy.build_view(
            context=context,
            regime=regime,
            episode=episode,
            signals=signals,
            decision=decision,
            sizing=sizing,
        )
        source_qty = self._lifecycle_source_quantities(context)
        target_plan = decision.target_plan
        primary = decision.primary_sleeve
        self._lifecycle_state_shadow.append({
            "timestamp": context.latest.get("timestamp"),
            "symbol": context.symbol,
            "call_count": int(self._call_count),
            "lifecycle_state": lifecycle.state,
            "lifecycle_reason": lifecycle.reason,
            "regime": regime.regime,
            "regime_reason": regime.reason,
            "btc_regime": regime.btc_regime,
            "raw_state": context.raw_state,
            "confirmed_state": context.confirmed_state,
            "episode_id": str(episode.get("id", "")),
            "episode_state": str(episode.get("state", "NORMAL")),
            "episode_setup": str(episode.get("setup", "")),
            "episode_cumulative_sold_pct": float(episode.get("cumulative_sold_pct", 0.0) or 0.0),
            "episode_cumulative_recovered_pct": float(episode.get("cumulative_recovered_pct", 0.0) or 0.0),
            "episode_open_recovery_budget_pct": max(
                0.0,
                float(episode.get("recovery_budget_pct", episode.get("cumulative_sold_pct", 0.0)) or 0.0)
                - float(episode.get("cumulative_recovered_pct", episode.get("recovery_bought_pct", 0.0)) or 0.0),
            ),
            "risk_score": int(context.risk_score),
            "trend_risk": int(context.trend_risk),
            "drawdown_risk": int(context.drawdown_risk),
            "structural_bear": bool(regime.structural_bear),
            "current_pct": float(context.current_pct),
            "mature_target": float(decision.mature_target),
            "phase_target": float(decision.phase_target),
            "execution_target_today": float(decision.execution_target_today),
            "decision_target": float(decision.target),
            "risk_ceiling_shadow": float(lifecycle.risk_ceiling),
            "lifecycle_target_shadow": float(lifecycle.target),
            "target_gap_to_lifecycle_shadow": max(0.0, float(lifecycle.target) - float(context.current_pct)),
            "base_target_shadow": float(target_plan.desired_base if target_plan is not None else 0.0),
            "bear_base_floor": float(target_plan.bear_base_floor if target_plan is not None else self._bear_base_floor(context)),
            "main_quantity": float(self._main_quantity(context)),
            "base_quantity": float(self._base_quantity(context)),
            "source_protected_floor_qty": source_qty["protected_floor"],
            "source_strategic_base_qty": source_qty["strategic_base"],
            "source_base_led_recovery_qty": source_qty["base_led_recovery"],
            "source_other_base_qty": source_qty["other_base"],
            "buy_allowed_shadow": bool(sizing.side == "buy" and not sizing.blocked_reason and sizing.quantity > 1e-12),
            "sell_allowed_sources": lifecycle.sell_allowed_sources,
            "low_location_shadow": bool(lifecycle.low_location),
            "recovery_active_shadow": bool(str(episode.get("state", "NORMAL")) in {"DEFENSE_LOCK", "RECOVERY_TEST", "FAILED_RECOVERY_LOCK", "STRUCTURAL_BEAR_LOCK"}),
            "trend_confirmed_shadow": bool(regime.regime == "BULL" and context.trend_risk <= 1),
            "distribution_shadow": bool(signals.distribution_exhaustion or sizing.setup in {"distribution-sell", "bear-base-exit", "protected-floor-exit"}),
            "starter_signal": bool(signals.starter),
            "value_recovery_signal": bool(signals.value_recovery),
            "trend_continuation_signal": bool(signals.trend_continuation),
            "recovery_signal": bool(signals.recovery_signal),
            "strong_recovery_signal": bool(signals.strong_recovery_signal),
            "recovery_quality_ok": bool(signals.recovery_quality_ok),
            "selected_sleeve": primary.sleeve if primary is not None else "",
            "selected_setup": primary.setup if primary is not None else "",
            "selected_priority": int(primary.priority) if primary is not None else 0,
            "sizing_side": sizing.side,
            "sizing_setup": sizing.setup,
            "sizing_quantity": float(sizing.quantity),
            "sizing_target": float(sizing.target),
            "sizing_guard": sizing.guard,
            "sizing_blocked_reason": sizing.blocked_reason,
            "actual_position_before": float(sizing.actual_position_before),
            "actual_position_after": float(sizing.actual_position_after),
            "actual_step_pct": float(sizing.actual_step_pct),
            "action_side": action.side if action is not None else "",
            "action_setup": sizing.setup if action is not None else "",
            "action_quantity": float(action.quantity) if action is not None else 0.0,
            "action_reason": action.reason if action is not None else "",
        })

    def _classify_lifecycle_state(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> tuple[str, str]:
        view = self._v45_lifecycle_policy.build_view(
            context=context,
            regime=regime,
            episode=episode,
            signals=signals,
            decision=decision,
            sizing=sizing,
        )
        return view.state, view.reason

    def _lifecycle_low_location(self, context: V42Context, regime: V42Regime) -> bool:
        return self._v45_lifecycle_policy.low_location(context=context, regime=regime)

    def _lifecycle_source_quantities(self, context: V42Context) -> dict[str, float]:
        sources = self._base_ledger_by_symbol.get(context.symbol, {}).get("source_ledger", {})
        protected = max(0.0, float(sources.get("protected_floor", {}).get("quantity", 0.0) or 0.0))
        strategic = max(0.0, float(sources.get("strategic_base", {}).get("quantity", 0.0) or 0.0))
        recovery = max(0.0, float(sources.get("base_led_recovery", {}).get("quantity", 0.0) or 0.0))
        total = max(0.0, float(self._base_quantity(context)))
        return {
            "protected_floor": protected,
            "strategic_base": strategic,
            "base_led_recovery": recovery,
            "other_base": max(0.0, total - protected - strategic - recovery),
        }

    def _lifecycle_sell_allowed_sources(self, context: V42Context, sizing: V42Sizing, action: Action | None) -> str:
        return self._v45_lifecycle_policy.sell_allowed_sources(context=context, sizing=sizing)

    def _lifecycle_risk_ceiling_shadow(self, context: V42Context, regime: V42Regime, lifecycle_state: str) -> float:
        return self._v45_lifecycle_policy.risk_ceiling(
            context=context,
            regime=regime,
            lifecycle_state=lifecycle_state,
        )


class V45ExpRecoveryExecutorV1Strategy(V45LifecycleStrategy):
    """V4.5 experiment: narrow main-sleeve executor for audited BTC/BNB recovery gaps."""

    RECOVERY_EXECUTOR_SYMBOL_BLOCKS = {
        "BTC/USDT": {"insufficient_sell_to_low_drawdown"},
        "BNB/USDT": {"recovery_step_too_small"},
    }
    RECOVERY_EXECUTOR_MAX_BUY_PCT = {"BTC/USDT": 0.02, "BNB/USDT": 0.02}
    RECOVERY_EXECUTOR_MIN_BUDGET = 0.03
    RECOVERY_EXECUTOR_MIN_TARGET_GAP = 0.03
    RECOVERY_EXECUTOR_COOLDOWN_CALLS = {"BTC/USDT": 14, "BNB/USDT": 14}
    SPOT_EXPOSURE_CAP = 1.00

    @property
    def name(self) -> str:
        return "v4_5_exp_recovery_executor_v1"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._last_recovery_executor_buy_call_by_symbol: dict[str, int] = {}

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        executor = self._recovery_executor_sizing(context, regime, episode, signals, decision, sizing)
        if executor.side and executor.quantity > 1e-12:
            return executor
        return sizing

    def _recovery_executor_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        allowed_blocks = self.RECOVERY_EXECUTOR_SYMBOL_BLOCKS.get(context.symbol)
        if not allowed_blocks:
            return V42Sizing()
        state = str(episode.get("state", "NORMAL"))
        if state not in {"DEFENSE_LOCK", "RECOVERY_TEST", "FAILED_RECOVERY_LOCK", "STRUCTURAL_BEAR_LOCK"}:
            return V42Sizing()
        if prior_sizing.side != "buy" or prior_sizing.quantity > 1e-12:
            return V42Sizing()
        blocked = str(prior_sizing.blocked_reason or "")
        if blocked not in allowed_blocks:
            return V42Sizing()
        if signals.distribution_exhaustion:
            return V42Sizing()
        if not bool(signals.strong_recovery_signal or signals.recovery_quality_ok):
            return V42Sizing()
        if regime.btc_regime == "BEAR" and not signals.recovery_quality_ok:
            return V42Sizing()
        if context.trend_risk >= 3:
            return V42Sizing()
        lifecycle = self._v45_lifecycle_policy.build_view(
            context=context,
            regime=regime,
            episode=episode,
            signals=signals,
            decision=decision,
            sizing=prior_sizing,
        )
        if lifecycle.state != "RECOVERY":
            return V42Sizing()
        open_budget = self._recovery_executor_open_budget(episode)
        if open_budget < self.RECOVERY_EXECUTOR_MIN_BUDGET:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="recovery_executor_budget_too_small")
        target = min(float(decision.execution_target_today), lifecycle.target, self.SPOT_EXPOSURE_CAP)
        target_gap = max(0.0, target - float(context.current_pct))
        if target_gap < self.RECOVERY_EXECUTOR_MIN_TARGET_GAP:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="recovery_executor_target_gap_too_small")
        spot_room = max(0.0, self.SPOT_EXPOSURE_CAP - float(context.current_pct))
        if spot_room < self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="spot_exposure_cap")
        cooldown = int(self.RECOVERY_EXECUTOR_COOLDOWN_CALLS.get(context.symbol, 14))
        last_buy = self._last_recovery_executor_buy_call_by_symbol.get(context.symbol, -10_000)
        if self._call_count - last_buy < cooldown:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="recovery_executor_cooldown")
        buy_pct = min(
            open_budget,
            target_gap,
            spot_room,
            float(self.RECOVERY_EXECUTOR_MAX_BUY_PCT.get(context.symbol, 0.02)),
        )
        if buy_pct < self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="recovery_executor_step_too_small")
        buy_qty = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="min_notional")
        guard = self._join_guard(
            self._sizing_guard(context, regime, episode, "recovery-probe-buy"),
            f"v4_5_recovery_executor_{blocked}",
        )
        decision.primary_sleeve = V42SleevePlan(
            sleeve="main",
            side="buy",
            setup="recovery-probe-buy",
            target=target,
            guard=guard,
            priority=83,
            allowed=True,
        )
        self._diag["v4_5_recovery_executor_buy_count"] = self._diag.get("v4_5_recovery_executor_buy_count", 0) + 1
        self._diag[f"v4_5_recovery_executor_{context.symbol.split('/')[0].lower()}_count"] = (
            self._diag.get(f"v4_5_recovery_executor_{context.symbol.split('/')[0].lower()}_count", 0) + 1
        )
        return V42Sizing(
            side="buy",
            setup="recovery-probe-buy",
            quantity=buy_qty,
            target=target,
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=target_gap,
            actual_step_pct=buy_pct,
            remaining_gap_after=max(0.0, target_gap - buy_pct),
        )

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        result = super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "buy" and "v4_5_recovery_executor" in str(sizing.guard):
            self._last_recovery_executor_buy_call_by_symbol[context.symbol] = self._call_count
        return result

    def _recovery_executor_open_budget(self, episode: dict) -> float:
        budget = float(episode.get("recovery_budget_pct", 0.0) or 0.0)
        recovered = float(episode.get("recovery_bought_pct", 0.0) or 0.0)
        return max(0.0, budget - recovered)


class V45ExpRecoveryExecutorV2Strategy(V45ExpRecoveryExecutorV1Strategy):
    """V4.5 experiment: path-safe recovery executor; never starts a recovery path by itself."""

    RECOVERY_EXECUTOR_COOLDOWN_CALLS = {"BTC/USDT": 28, "BNB/USDT": 28}
    RECOVERY_EXECUTOR_MAX_CHASE_FROM_LAST_BUY = 0.03

    @property
    def name(self) -> str:
        return "v4_5_exp_recovery_executor_v2"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._recovery_executor_episode_ids: set[str] = set()

    def _recovery_executor_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        state = str(episode.get("state", "NORMAL"))
        if state not in {"DEFENSE_LOCK", "RECOVERY_TEST"}:
            return V42Sizing()
        episode_id = str(episode.get("episode_id", ""))
        if episode_id and episode_id in self._recovery_executor_episode_ids:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="recovery_executor_episode_used")
        if int(episode.get("recovery_buy_count", 0) or 0) <= 0:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="recovery_executor_no_prior_recovery_leg")
        last_buy_price = float(episode.get("last_recovery_buy_price", 0.0) or 0.0)
        if last_buy_price <= 0.0:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="recovery_executor_no_last_buy_price")
        if context.price > last_buy_price * (1.0 + self.RECOVERY_EXECUTOR_MAX_CHASE_FROM_LAST_BUY):
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="recovery_executor_chasing_price")
        return super()._recovery_executor_sizing(context, regime, episode, signals, decision, prior_sizing)

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        result = super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "buy" and "v4_5_recovery_executor" in str(sizing.guard):
            episode_id = str(episode.get("episode_id", ""))
            if episode_id:
                self._recovery_executor_episode_ids.add(episode_id)
        return result


class V45ExpRecoveryExecutorProtectedV3Strategy(V45ExpRecoveryExecutorV2Strategy):
    """V4.5 experiment: route narrow recovery-executor fills into protected base sleeve."""

    @property
    def name(self) -> str:
        return "v4_5_exp_recovery_executor_protected_v3"

    def _recovery_executor_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        sizing = super()._recovery_executor_sizing(context, regime, episode, signals, decision, prior_sizing)
        if sizing.side == "buy" and sizing.quantity > 1e-12:
            guard = self._join_guard(str(sizing.guard), "v4_5_protected_recovery")
            sizing.setup = "protected-recovery-buy"
            sizing.guard = guard
            decision.primary_sleeve = V42SleevePlan(
                sleeve="protected-recovery",
                side="buy",
                setup="protected-recovery-buy",
                target=sizing.target,
                guard=guard,
                priority=84,
                allowed=True,
            )
        return sizing

    def _action_sleeve(self, decision: V42DecisionPlan, sizing: V42Sizing) -> str:
        if sizing.setup == "protected-recovery-buy":
            return "base"
        return super()._action_sleeve(decision, sizing)

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        result = super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "buy" and sizing.setup == "protected-recovery-buy":
            self._add_base_source(context, action, "protected_recovery", layer=2)
            self._diag["v4_5_protected_recovery_buy_count"] = (
                self._diag.get("v4_5_protected_recovery_buy_count", 0) + 1
            )
        return result


class V45ExpProtectedRecoveryRouteV4Strategy(V45LifecycleStrategy):
    """V4.5 experiment: protect existing low-exposure recovery-probe buys without adding orders."""

    PROTECTED_RECOVERY_SYMBOLS = {"BTC/USDT", "BNB/USDT"}
    PROTECTED_RECOVERY_MAX_POSITION_BEFORE = 0.12
    PROTECTED_RECOVERY_MAX_STEP = 0.08

    @property
    def name(self) -> str:
        return "v4_5_exp_protected_recovery_route_v4"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        if self._should_route_recovery_to_protected_base(context, regime, episode, signals, sizing):
            guard = self._join_guard(str(sizing.guard), "v4_5_protected_recovery_route")
            sizing.setup = "protected-recovery-buy"
            sizing.guard = guard
            decision.primary_sleeve = V42SleevePlan(
                sleeve="protected-recovery",
                side="buy",
                setup="protected-recovery-buy",
                target=sizing.target,
                guard=guard,
                priority=84,
                allowed=True,
            )
        return sizing

    def _should_route_recovery_to_protected_base(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        sizing: V42Sizing,
    ) -> bool:
        if context.symbol not in self.PROTECTED_RECOVERY_SYMBOLS:
            return False
        if sizing.side != "buy" or sizing.quantity <= 1e-12 or sizing.setup != "recovery-probe-buy":
            return False
        if str(episode.get("state", "NORMAL")) not in {"DEFENSE_LOCK", "RECOVERY_TEST", "FAILED_RECOVERY_LOCK"}:
            return False
        if signals.distribution_exhaustion:
            return False
        if regime.regime == "BULL" and context.raw_state == "BULL":
            return False
        if float(sizing.actual_position_before) > self.PROTECTED_RECOVERY_MAX_POSITION_BEFORE:
            return False
        if float(sizing.actual_step_pct) > self.PROTECTED_RECOVERY_MAX_STEP:
            return False
        return "v4_2_staged_recovery" in str(sizing.guard)

    def _action_sleeve(self, decision: V42DecisionPlan, sizing: V42Sizing) -> str:
        if sizing.setup == "protected-recovery-buy":
            return "base"
        return super()._action_sleeve(decision, sizing)

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        result = super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "buy" and sizing.setup == "protected-recovery-buy":
            self._add_base_source(context, action, "protected_recovery", layer=2)
            self._diag["v4_5_protected_recovery_route_buy_count"] = (
                self._diag.get("v4_5_protected_recovery_route_buy_count", 0) + 1
            )
        return result


class V45ExpRecoveryVectorV1Strategy(V45LifecycleStrategy):
    """V4.5 experiment: recovery-stage target vector decoupled from episode buyback budget."""

    RECOVERY_VECTOR_BLOCKED_REASONS = {
        "insufficient_sell_to_low_drawdown",
        "recovery_step_too_small",
        "recovery_budget_filled",
        "cooldown",
        "defense_cooldown",
    }
    RECOVERY_VECTOR_SETUP = "recovery-vector-buy"
    SPOT_EXPOSURE_CAP = 1.00

    @property
    def name(self) -> str:
        return "v4_5_exp_recovery_vector_v1"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._recovery_vector_by_symbol: dict[str, dict] = {}

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        shield = self._recovery_vector_sell_shield_sizing(context, regime, episode, sizing)
        if shield.blocked_reason:
            return shield
        vector = self._recovery_vector_buy_sizing(context, regime, episode, signals, decision, sizing)
        if vector.side and vector.quantity > 1e-12:
            return vector
        return sizing

    def _recovery_vector_buy_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        state = str(episode.get("state", "NORMAL"))
        if state not in {"DEFENSE_LOCK", "RECOVERY_TEST", "FAILED_RECOVERY_LOCK", "STRUCTURAL_BEAR_LOCK"}:
            return V42Sizing()
        blocked = str(prior_sizing.blocked_reason or "")
        no_action_buy = prior_sizing.side == "buy" and prior_sizing.quantity <= 1e-12
        if prior_sizing.quantity > 1e-12 or (not no_action_buy and prior_sizing.side):
            return V42Sizing()
        if blocked and blocked not in self.RECOVERY_VECTOR_BLOCKED_REASONS:
            return V42Sizing()
        if regime.structural_bear and not self._structural_recovery_ready(context, regime, signals):
            return V42Sizing()
        if context.trend_risk >= 3:
            return V42Sizing()
        if not (signals.recovery_signal or signals.strong_recovery_signal or signals.recovery_quality_ok or self._staged_recovery_ready(context, regime, episode)):
            return V42Sizing()
        if signals.distribution_exhaustion:
            return V42Sizing()

        lifecycle = self._v45_lifecycle_policy.build_view(
            context=context,
            regime=regime,
            episode=episode,
            signals=signals,
            decision=decision,
            sizing=prior_sizing,
        )
        if lifecycle.state != "RECOVERY":
            return V42Sizing()
        target = min(float(decision.execution_target_today), float(lifecycle.target), self.SPOT_EXPOSURE_CAP)
        target_gap = max(0.0, target - float(context.current_pct))
        spot_room = max(0.0, self.SPOT_EXPOSURE_CAP - float(context.current_pct))
        if target_gap < self.RECOVERY_MIN_STEP or spot_room < self.RECOVERY_MIN_STEP:
            return V42Sizing()

        last_buy = int(self._recovery_vector_by_symbol.get(context.symbol, {}).get("last_buy_call", -10_000))
        cooldown = self._buy_cooldown(context, regime, "recovery-probe-buy")
        if self._call_count - last_buy < cooldown:
            return V42Sizing()

        base_setup = str(prior_sizing.setup or decision.primary_sleeve.setup if decision.primary_sleeve is not None else "recovery-probe-buy")
        if base_setup not in {"recovery-probe-buy", "value-recovery", "trend-cont"}:
            base_setup = "recovery-probe-buy"
        buy_pct = min(
            target_gap,
            spot_room,
            self._setup_base_buy_pct(base_setup),
        )
        if buy_pct < self.RECOVERY_MIN_STEP:
            return V42Sizing()
        buy_qty = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
        if buy_qty <= 1e-12:
            return V42Sizing()
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing()

        guard = self._join_guard(
            self._sizing_guard(context, regime, episode, "recovery-probe-buy"),
            f"v4_5_recovery_vector_{blocked or 'target_gap'}",
        )
        decision.primary_sleeve = V42SleevePlan(
            sleeve="main",
            side="buy",
            setup=self.RECOVERY_VECTOR_SETUP,
            target=target,
            guard=guard,
            priority=85,
            allowed=True,
        )
        self._diag["v4_5_recovery_vector_buy_count"] = self._diag.get("v4_5_recovery_vector_buy_count", 0) + 1
        return V42Sizing(
            side="buy",
            setup=self.RECOVERY_VECTOR_SETUP,
            quantity=buy_qty,
            target=target,
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=target_gap,
            actual_step_pct=buy_pct,
            remaining_gap_after=max(0.0, target_gap - buy_pct),
        )

    def _recovery_vector_sell_shield_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        sizing: V42Sizing,
    ) -> V42Sizing:
        if sizing.side != "sell" or sizing.quantity <= 1e-12:
            return V42Sizing()
        if sizing.setup not in {"defense-sell", "structural-exit-sell"}:
            return V42Sizing()
        vector = self._recovery_vector_by_symbol.get(context.symbol)
        if not vector or int(vector.get("quantity_active", 0)) <= 0:
            return V42Sizing()
        entry = float(vector.get("last_buy_price", 0.0) or 0.0)
        failure = bool(
            regime.structural_bear
            or context.trend_risk >= 3
            or (regime.btc_regime == "BEAR" and entry > 0.0 and context.price < entry * 0.94)
        )
        if failure:
            return V42Sizing()
        self._diag["v4_5_recovery_vector_sell_shield_count"] = (
            self._diag.get("v4_5_recovery_vector_sell_shield_count", 0) + 1
        )
        return V42Sizing(side=sizing.side, setup=sizing.setup, blocked_reason="recovery_vector_hold")

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        result = super()._record_event(context, regime, episode, decision, sizing, action)
        if action is None:
            return result
        vector = self._recovery_vector_by_symbol.setdefault(context.symbol, {"quantity_active": 0.0})
        if action.side == "buy" and sizing.setup == self.RECOVERY_VECTOR_SETUP:
            vector["quantity_active"] = float(vector.get("quantity_active", 0.0) or 0.0) + float(action.quantity)
            vector["last_buy_call"] = self._call_count
            vector["last_buy_price"] = float(action.price)
        elif action.side == "sell" and sizing.setup in {"defense-sell", "structural-exit-sell"}:
            vector["quantity_active"] = max(0.0, float(vector.get("quantity_active", 0.0) or 0.0) - float(action.quantity))
        return result


class V45ExpRecoveryVectorV2Strategy(V45ExpRecoveryVectorV1Strategy):
    """V4.5 experiment: narrow recovery vector; unlock buyback math without sell shielding."""

    RECOVERY_VECTOR_BLOCKED_REASONS = {
        "insufficient_sell_to_low_drawdown",
        "recovery_step_too_small",
        "recovery_budget_filled",
    }

    @property
    def name(self) -> str:
        return "v4_5_exp_recovery_vector_v2"

    def _recovery_vector_buy_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        state = str(episode.get("state", "NORMAL"))
        if state not in {"DEFENSE_LOCK", "RECOVERY_TEST"}:
            return V42Sizing()
        if regime.structural_bear or state == "STRUCTURAL_BEAR_LOCK":
            return V42Sizing()
        if regime.regime == "BULL" and context.confirmed_state == "BULL":
            return V42Sizing()
        sizing = super()._recovery_vector_buy_sizing(context, regime, episode, signals, decision, prior_sizing)
        if sizing.side == "buy" and sizing.quantity > 1e-12:
            buy_pct = min(float(sizing.actual_step_pct), self._setup_base_buy_pct("recovery-probe-buy"))
            if buy_pct < self.RECOVERY_MIN_STEP:
                return V42Sizing()
            sizing.quantity = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
            sizing.actual_position_after = context.current_pct + buy_pct
            sizing.actual_step_pct = buy_pct
            sizing.remaining_gap_after = max(0.0, float(sizing.target_gap_before) - buy_pct)
        return sizing

    def _recovery_vector_sell_shield_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        sizing: V42Sizing,
    ) -> V42Sizing:
        return V42Sizing()


class V45ExpRecoveryVectorV3Strategy(V45ExpRecoveryVectorV2Strategy):
    """V4.5 experiment: unlock only audited symbol/block recovery math failures."""

    RECOVERY_VECTOR_SYMBOL_BLOCKS = {
        "BTC/USDT": {"insufficient_sell_to_low_drawdown"},
        "BNB/USDT": {"recovery_step_too_small"},
    }

    @property
    def name(self) -> str:
        return "v4_5_exp_recovery_vector_v3"

    def _recovery_vector_buy_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        allowed = self.RECOVERY_VECTOR_SYMBOL_BLOCKS.get(context.symbol)
        if not allowed or str(prior_sizing.blocked_reason or "") not in allowed:
            return V42Sizing()
        return super()._recovery_vector_buy_sizing(context, regime, episode, signals, decision, prior_sizing)


class V45ExpRecoveryVectorCreditV1Strategy(V45LifecycleStrategy):
    """V4.5 experiment: defer audited recovery-vector gaps into the next valid buy."""

    RECOVERY_VECTOR_CREDIT_BLOCKS = {
        "BTC/USDT": {"insufficient_sell_to_low_drawdown"},
        "BNB/USDT": {"recovery_step_too_small"},
    }
    RECOVERY_VECTOR_CREDIT_BUY_SET = {"recovery-probe-buy", "value-recovery", "starter-buy", "trend-cont"}
    SPOT_EXPOSURE_CAP = 1.00

    @property
    def name(self) -> str:
        return "v4_5_exp_recovery_vector_credit_v1"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._recovery_vector_credit_by_symbol: dict[str, float] = {}

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        self._record_recovery_vector_credit(context, regime, episode, signals, decision, sizing)
        return self._apply_recovery_vector_credit(context, regime, decision, sizing)

    def _record_recovery_vector_credit(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
    ) -> None:
        allowed = self.RECOVERY_VECTOR_CREDIT_BLOCKS.get(context.symbol)
        blocked = str(sizing.blocked_reason or "")
        if not allowed or blocked not in allowed:
            return
        if sizing.side != "buy" or sizing.quantity > 1e-12:
            return
        state = str(episode.get("state", "NORMAL"))
        if state not in {"DEFENSE_LOCK", "RECOVERY_TEST"}:
            return
        if regime.structural_bear or context.trend_risk >= 3 or signals.distribution_exhaustion:
            return
        if not (signals.recovery_signal or signals.strong_recovery_signal or signals.recovery_quality_ok or self._staged_recovery_ready(context, regime, episode)):
            return
        target_gap = max(0.0, float(decision.execution_target_today) - float(context.current_pct))
        credit = min(target_gap, self._setup_base_buy_pct("recovery-probe-buy"))
        if credit < self.RECOVERY_MIN_STEP:
            return
        prior = float(self._recovery_vector_credit_by_symbol.get(context.symbol, 0.0) or 0.0)
        self._recovery_vector_credit_by_symbol[context.symbol] = max(prior, credit)
        self._diag["v4_5_recovery_vector_credit_open_count"] = (
            self._diag.get("v4_5_recovery_vector_credit_open_count", 0) + 1
        )

    def _apply_recovery_vector_credit(
        self,
        context: V42Context,
        regime: V42Regime,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
    ) -> V42Sizing:
        credit = float(self._recovery_vector_credit_by_symbol.get(context.symbol, 0.0) or 0.0)
        if credit < self.RECOVERY_MIN_STEP:
            return sizing
        if sizing.side != "buy" or sizing.quantity <= 1e-12 or sizing.setup not in self.RECOVERY_VECTOR_CREDIT_BUY_SET:
            return sizing
        if context.trend_risk >= 3:
            return sizing
        target = min(float(sizing.target or decision.execution_target_today), self.SPOT_EXPOSURE_CAP)
        current_after = float(sizing.actual_position_after)
        target_room = max(0.0, target - current_after)
        spot_room = max(0.0, self.SPOT_EXPOSURE_CAP - current_after)
        add_pct = min(credit, target_room, spot_room)
        if add_pct < self.RECOVERY_MIN_STEP:
            return sizing
        add_qty = context.total_value * add_pct / context.price if context.price > 0.0 else 0.0
        if add_qty <= 1e-12:
            return sizing
        sizing.quantity += add_qty
        sizing.actual_position_after = current_after + add_pct
        sizing.actual_step_pct = float(sizing.actual_step_pct) + add_pct
        sizing.remaining_gap_after = max(0.0, float(sizing.remaining_gap_after) - add_pct)
        sizing.guard = self._join_guard(str(sizing.guard), "v4_5_recovery_vector_credit")
        self._recovery_vector_credit_by_symbol[context.symbol] = max(0.0, credit - add_pct)
        self._diag["v4_5_recovery_vector_credit_used_count"] = (
            self._diag.get("v4_5_recovery_vector_credit_used_count", 0) + 1
        )
        return sizing


class V45ExpRecoveryVectorCreditV2Strategy(V45ExpRecoveryVectorCreditV1Strategy):
    """V4.5 experiment: recovery-vector credit can only enlarge recovery-probe buys."""

    RECOVERY_VECTOR_CREDIT_BUY_SET = {"recovery-probe-buy"}

    @property
    def name(self) -> str:
        return "v4_5_exp_recovery_vector_credit_v2"


