class V45ExecTransformBroadLowMixin(V45ExecTransformLowAware200V1Strategy):
    EXEC_BROAD_LOW_ROLLING_MAX = 0.55
    EXEC_BROAD_LOW_DONCHIAN_MAX = 0.55
    EXEC_BROAD_LOW_EMA_DISCOUNT = -0.05
    EXEC_BROAD_LOW_MIN_RAW = 0.15

    def execution_target_for_symbol(
        self,
        symbol: str,
        raw_position_pct: float,
        candles_by_symbol: dict[str, pd.DataFrame],
        current_prices: dict[str, float],
    ) -> float:
        target, _reason = self.execution_transform_diagnostics_for_symbol(
            symbol=symbol,
            raw_position_pct=raw_position_pct,
            candles_by_symbol=candles_by_symbol,
            current_prices=current_prices,
        )
        return target

    def execution_transform_diagnostics_for_symbol(
        self,
        symbol: str,
        raw_position_pct: float,
        candles_by_symbol: dict[str, pd.DataFrame],
        current_prices: dict[str, float],
    ) -> tuple[float, str]:
        raw = max(0.0, float(raw_position_pct))
        row = self._latest_lifecycle_shadow_row(symbol)
        if row is None:
            return raw, "raw_no_lifecycle"
        risk = int(row.get("risk_score", 0) or 0)
        state = str(row.get("lifecycle_state", "") or "")
        main_intent = str(row.get("main_intent", "") or "")
        confirmed = str(row.get("confirmed_state", "") or "")
        structural = bool(row.get("structural_bear", False))
        distribution = bool(row.get("distribution_shadow", False))
        trend_confirmed = bool(row.get("trend_confirmed_shadow", False))
        risk_off = bool(
            state in {"DEFENSE", "DISTRIBUTION"}
            or main_intent in {"DEFEND", "EXIT", "DISTRIBUTE"}
            or structural
            or risk >= 3
            or distribution
            or raw <= 0.05
        )
        if risk_off:
            return raw, "risk_off"
        if self._exec_broad_low_location(symbol, candles_by_symbol) and raw >= self.EXEC_BROAD_LOW_MIN_RAW:
            return min(self.EXEC_LOW_AWARE_LOW_CAP, raw * self.EXEC_LOW_AWARE_LOW_MULT), "broad_low"
        if trend_confirmed and confirmed == "BULL" and risk <= 1 and raw >= 0.50:
            return min(self.EXEC_LOW_AWARE_TREND_CAP, raw * self.EXEC_LOW_AWARE_TREND_MULT), "trend_confirmed"
        return raw, "raw"

    def _exec_broad_low_location(self, symbol: str, candles_by_symbol: dict[str, pd.DataFrame]) -> bool:
        df = candles_by_symbol.get(symbol)
        if df is None or df.empty:
            return False
        latest = df.iloc[-1]
        rolling_pos = self._value(latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(latest, "donchian_pos", 0.5)
        price_vs_ema = self._value(latest, "price_vs_ema168", 0.0)
        return bool(
            (not pd.isna(rolling_pos) and float(rolling_pos) <= self.EXEC_BROAD_LOW_ROLLING_MAX)
            or (not pd.isna(donchian_pos) and float(donchian_pos) <= self.EXEC_BROAD_LOW_DONCHIAN_MAX)
            or (not pd.isna(price_vs_ema) and float(price_vs_ema) <= self.EXEC_BROAD_LOW_EMA_DISCOUNT)
        )


