class V46OuterQtyV1Strategy(V46Strategy, V42ExpRecoveryOverlayOuterQtyV1Strategy):
    """V4.6 main leverage plus fixed-quantity 1x outer low-frequency lots."""

    @property
    def name(self) -> str:
        return "v4_6_outer_qty_v1"

    def __init__(self, *args, **kwargs):
        V46Strategy.__init__(self, *args, **kwargs)
        self._outer_overlay_state_by_symbol: dict[str, dict] = {}
        self._outer_overlay_last_eval: dict[str, tuple[int, float, str]] = {}
        self._outer_overlay_events: list[dict] = []
        self._outer_qty_last_eval: dict[str, tuple[int, float, str]] = {}

    def strategy_outer_overlay_events(self) -> list[dict]:
        return list(self._outer_overlay_events)

    def execution_target_for_symbol_with_portfolios(
        self,
        symbol: str,
        raw_position_pct: float,
        candles_by_symbol: dict[str, pd.DataFrame],
        current_prices: dict[str, float],
        decision_portfolio: PortfolioState,
        execution_portfolio: PortfolioState,
    ) -> float:
        target, _reason = self.execution_transform_diagnostics_for_symbol_with_portfolios(
            symbol=symbol,
            raw_position_pct=raw_position_pct,
            candles_by_symbol=candles_by_symbol,
            current_prices=current_prices,
            decision_portfolio=decision_portfolio,
            execution_portfolio=execution_portfolio,
        )
        return target

    def execution_transform_diagnostics_for_symbol_with_portfolios(
        self,
        symbol: str,
        raw_position_pct: float,
        candles_by_symbol: dict[str, pd.DataFrame],
        current_prices: dict[str, float],
        decision_portfolio: PortfolioState,
        execution_portfolio: PortfolioState,
    ) -> tuple[float, str]:
        cached = self._outer_qty_last_eval.get(symbol)
        if cached is not None and cached[0] == self._call_count:
            return cached[1], cached[2]
        price = float(current_prices.get(symbol, 0.0) or 0.0)
        if price <= 0.0:
            return max(0.0, float(raw_position_pct)), "outer_bad_price"
        execution_pos = execution_portfolio.positions.get(symbol, PositionState())
        execution_total = execution_portfolio.cash + execution_pos.quantity * price
        if execution_total <= 0.0:
            return max(0.0, float(raw_position_pct)), "outer_bad_total"
        main_target, main_reason = V46Strategy.execution_transform_diagnostics_for_symbol(
            self,
            symbol=symbol,
            raw_position_pct=raw_position_pct,
            candles_by_symbol=candles_by_symbol,
            current_prices=current_prices,
        )
        main_qty = max(0.0, float(main_target)) * execution_total / price
        outer_qty, outer_reason = self._outer_fixed_quantity(symbol, float(raw_position_pct), candles_by_symbol.get(symbol), price, execution_total)
        target = max(0.0, (main_qty + outer_qty) * price / execution_total)
        reason = f"{main_reason}+{outer_reason}"
        self._outer_qty_last_eval[symbol] = (self._call_count, target, reason)
        return target, reason


