class V45ExecTransformPanicRecoveryV1Strategy(V45ExecTransformLow26Trend175CleanV1Strategy):
    """Clean leverage baseline plus panic-value early recovery execution boost."""

    # The audit score includes a not-first-rebound pulse history.  The execution
    # transform is stateless, so use the base panic-value score here and keep the
    # BTC market-clean gate to avoid 2022 bear-rally false positives.
    EXEC_PANIC_RECOVERY_MIN_SCORE = 5.0
    EXEC_PANIC_RECOVERY_MULT = 1.35
    EXEC_PANIC_RECOVERY_CAP = 0.95
    EXEC_PANIC_RECOVERY_MIN_RAW = 0.20
    EXEC_PANIC_RECOVERY_MAX_RAW = 0.70

    @property
    def name(self) -> str:
        return "v4_5_exec_transform_panic_recovery_v1"

    def execution_transform_diagnostics_for_symbol(
        self,
        symbol: str,
        raw_position_pct: float,
        candles_by_symbol: dict[str, pd.DataFrame],
        current_prices: dict[str, float],
    ) -> tuple[float, str]:
        raw = max(0.0, float(raw_position_pct))
        row = self._latest_lifecycle_shadow_row(symbol)
        if row is None:
            return raw, "raw_no_lifecycle"
        risk = int(row.get("risk_score", 0) or 0)
        state = str(row.get("lifecycle_state", "") or "")
        main_intent = str(row.get("main_intent", "") or "")
        confirmed = str(row.get("confirmed_state", "") or "")
        structural = bool(row.get("structural_bear", False))
        distribution = bool(row.get("distribution_shadow", False))
        low_location = bool(row.get("low_location_shadow", False))
        recovery_active = bool(row.get("recovery_active_shadow", False))
        trend_confirmed = bool(row.get("trend_confirmed_shadow", False))
        hard_risk_off = bool(
            state in {"DEFENSE", "DISTRIBUTION"}
            or main_intent in {"DEFEND", "EXIT", "DISTRIBUTE"}
            or structural
            or risk >= 3
            or distribution
            or raw <= 0.05
        )
        if hard_risk_off:
            return raw, "risk_off"
        if trend_confirmed and confirmed == "BULL" and risk <= 1 and raw >= 0.50:
            return min(self.EXEC_LOW_AWARE_TREND_CAP, raw * self.EXEC_LOW_AWARE_TREND_MULT), "trend_confirmed"
        btc_regime = str(row.get("btc_regime", "") or "")
        if (
            state == "RECOVERY"
            and confirmed != "BULL"
            and btc_regime != "BEAR"
            and low_location
            and risk <= 1
            and raw >= self.EXEC_PANIC_RECOVERY_MIN_RAW
            and raw < self.EXEC_PANIC_RECOVERY_MAX_RAW
        ):
            return min(self.EXEC_PANIC_RECOVERY_CAP, raw * self.EXEC_PANIC_RECOVERY_MULT), "panic_recovery"
        if (
            raw >= self.EXEC_PANIC_RECOVERY_MIN_RAW
            and raw < self.EXEC_PANIC_RECOVERY_MAX_RAW
            and self._exec_panic_recovery_ok(symbol, candles_by_symbol)
        ):
            return min(self.EXEC_PANIC_RECOVERY_CAP, raw * self.EXEC_PANIC_RECOVERY_MULT), "panic_recovery"
        if low_location and recovery_active and risk <= 2 and raw >= 0.20:
            return min(self.EXEC_LOW_AWARE_LOW_CAP, raw * self.EXEC_LOW_AWARE_LOW_MULT), "low_recovery"
        return raw, "raw"

    def _exec_panic_recovery_ok(self, symbol: str, candles_by_symbol: dict[str, pd.DataFrame]) -> bool:
        df = candles_by_symbol.get(symbol)
        if df is None or len(df) < 90:
            return False
        latest = df.iloc[-1]
        score = self._exec_panic_value_score(df)
        if score < self.EXEC_PANIC_RECOVERY_MIN_SCORE:
            return False
        if not self._exec_btc_market_clean(latest):
            return False
        roc_5 = self._series_ratio(df["close"], 5)
        if roc_5 < -0.10:
            return False
        close = pd.to_numeric(df["close"], errors="coerce")
        rolling_pos = self._position_in_window(close, 365)
        donchian_pos = self._position_in_window(close, 20)
        dd_180 = self._drawdown_from_rolling_high(df["close"], 180)
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.35)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.35)
            or dd_180 <= -0.35
        )

    def _exec_panic_value_score(self, df: pd.DataFrame) -> float:
        close = pd.to_numeric(df["close"], errors="coerce")
        volume = pd.to_numeric(df["volume"], errors="coerce") if "volume" in df.columns else pd.Series(dtype=float)
        rolling_pos = self._position_in_window(close, 365)
        donchian_pos = self._position_in_window(close, 20)
        position_score = 0.0
        low_pos = min(
            rolling_pos if not pd.isna(rolling_pos) else 0.5,
            donchian_pos if not pd.isna(donchian_pos) else 0.5,
        )
        if low_pos <= 0.10:
            position_score = 2.0
        elif low_pos <= 0.20:
            position_score = 1.5
        elif low_pos <= 0.35:
            position_score = 1.0

        dd_90 = self._drawdown_from_rolling_high(close, 90)
        dd_180 = self._drawdown_from_rolling_high(close, 180)
        dd_365 = self._drawdown_from_rolling_high(close, 365)
        drawdown_score = 0.0
        if dd_365 <= -0.70:
            drawdown_score = 2.0
        elif dd_365 <= -0.55:
            drawdown_score = 1.5
        elif dd_180 <= -0.40:
            drawdown_score = 1.0
        elif dd_90 <= -0.30:
            drawdown_score = 0.5

        roc_20 = self._series_ratio(close, 20)
        roc_60 = self._series_ratio(close, 60)
        speed_score = 0.0
        if roc_20 <= -0.30:
            speed_score = 1.0
        elif roc_20 <= -0.20 or roc_60 <= -0.35:
            speed_score = 0.75

        volume_score = 0.0
        cold_score = 0.0
        if len(volume) >= 90 and volume.tail(90).mean() > 0:
            vol_ratio = volume.tail(20).mean() / volume.tail(90).mean()
            vol_std = volume.tail(90).std()
            vol_z = (volume.iloc[-1] - volume.tail(90).mean()) / vol_std if vol_std and not pd.isna(vol_std) else 0.0
            if vol_z >= 1.5 or vol_ratio >= 1.8:
                volume_score = 1.0
            elif vol_z >= 0.75 or vol_ratio >= 1.25:
                volume_score = 0.5
            if vol_ratio <= 0.75:
                cold_score = 0.5

        rebound_20 = self._rebound_from_rolling_low(close, 20)
        roc_5 = self._series_ratio(close, 5)
        roc_10 = self._series_ratio(close, 10)
        near_low_10 = self._rebound_from_rolling_low(close, 10)
        stabilizing_score = 0.0
        if rebound_20 >= 0.08:
            stabilizing_score += 1.0
        if roc_5 >= -0.03:
            stabilizing_score += 0.5
        if roc_10 >= 0.0:
            stabilizing_score += 0.5
        if near_low_10 >= 0.03:
            stabilizing_score += 0.5

        return float(position_score + drawdown_score + speed_score + volume_score + cold_score + stabilizing_score)

    @staticmethod
    def _position_in_window(series: pd.Series, window: int) -> float:
        values = pd.to_numeric(series, errors="coerce").dropna().tail(window)
        if values.empty:
            return 0.5
        low = float(values.min())
        high = float(values.max())
        if high <= low:
            return 0.5
        return float((values.iloc[-1] - low) / (high - low))

    @staticmethod
    def _series_ratio(series: pd.Series, periods: int) -> float:
        values = pd.to_numeric(series, errors="coerce").dropna()
        if len(values) <= periods or values.iloc[-periods - 1] <= 0.0:
            return 0.0
        return float(values.iloc[-1] / values.iloc[-periods - 1] - 1.0)

    @staticmethod
    def _drawdown_from_rolling_high(series: pd.Series, window: int) -> float:
        values = pd.to_numeric(series, errors="coerce").dropna().tail(window)
        if values.empty or values.max() <= 0.0:
            return 0.0
        return float(values.iloc[-1] / values.max() - 1.0)

    @staticmethod
    def _rebound_from_rolling_low(series: pd.Series, window: int) -> float:
        values = pd.to_numeric(series, errors="coerce").dropna().tail(window)
        if values.empty or values.min() <= 0.0:
            return 0.0
        return float(values.iloc[-1] / values.min() - 1.0)

    @staticmethod
    def _exec_btc_market_clean(latest: pd.Series) -> bool:
        btc_regime = str(latest.get("btc_regime", "RANGE") or "RANGE")
        if btc_regime == "BEAR":
            return False
        btc_price_vs_ema72 = latest.get("btc_price_vs_ema72", 0.0)
        btc_price_vs_ema168 = latest.get("btc_price_vs_ema168", 0.0)
        btc_ema168_slope = latest.get("btc_ema168_slope", 0.0)
        btc_roc_20 = latest.get("btc_roc_20", 0.0)
        return bool(
            (pd.isna(btc_price_vs_ema72) or float(btc_price_vs_ema72) >= -0.04)
            and (pd.isna(btc_price_vs_ema168) or float(btc_price_vs_ema168) >= -0.22)
            and (pd.isna(btc_ema168_slope) or float(btc_ema168_slope) >= -0.002)
            and (pd.isna(btc_roc_20) or float(btc_roc_20) >= -0.18)
        )


class V45ExecTransformLow26Trend175CleanForcedLiqV1Strategy(V45ExecTransformLow26Trend175CleanV1Strategy):
    """Clean leverage baseline with real maintenance-margin liquidation enabled."""

    EXECUTION_TRANSFORM_FORCE_LIQUIDATION = True

    @property
    def name(self) -> str:
        return "v4_5_exec_transform_low26_trend175_clean_forced_liq_v1"


class V43ExpOpportunityFloorArchV1Strategy(V43ExpOpportunityFloorV2Strategy):
    """V4.3 experiment: risk ceiling + independent floor + recovery phase + floor protection."""

    SPOT_EXPOSURE_CAP = 1.00
    RECOVERY_PHASE_COOLDOWN_RELIEF_MAX_BUY = 0.08

    @property
    def name(self) -> str:
        return "v4_3_exp_opportunity_floor_arch_v1"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._last_opportunity_floor_buy_call_by_symbol: dict[str, int] = {}
        self._opportunity_floor_ledger_by_symbol: dict[str, dict] = {}
        self._current_regime_for_floor_by_symbol: dict[str, V42Regime] = {}

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        self._current_regime_for_floor_by_symbol[context.symbol] = regime
        phase = self._recovery_phase(context, regime, episode, signals)
        sizing = super(V43ExpOpportunityFloorV1Strategy, self)._compute_sizing(context, regime, episode, signals, decision)
        if sizing.side == "sell":
            return sizing
        if (
            sizing.side == "buy"
            and sizing.blocked_reason == "cooldown"
            and sizing.setup in {"recovery-probe-buy", "value-recovery"}
            and phase in {"recovery_confirmed", "trend_confirmed"}
        ):
            relief = self._recovery_phase_cooldown_relief_sizing(context, regime, episode, signals, decision, sizing)
            if relief.side:
                return self._cap_buy_by_arch_ceiling(context, decision, relief)
        if sizing.side == "buy" and sizing.quantity > 1e-12:
            return self._cap_buy_by_arch_ceiling(context, decision, sizing)
        floor = self._opportunity_floor_sizing(context, regime, signals, sizing)
        if floor.side:
            return floor
        return sizing

    def _opportunity_floor_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        if context.symbol not in self.OPPORTUNITY_FLOOR_SYMBOLS:
            return V42Sizing()
        raw_floor = float(self.OPPORTUNITY_FLOOR_TARGET.get(context.symbol, 0.0))
        if raw_floor <= 0.0:
            return V42Sizing()
        target = min(raw_floor, self._risk_ceiling(context, regime), self.SPOT_EXPOSURE_CAP)
        if context.current_pct >= target - self.RECOVERY_MIN_STEP:
            return V42Sizing(blocked_reason="opportunity_floor_filled")
        if not self._opportunity_floor_low_location(context, regime):
            return V42Sizing()
        if not self._opportunity_floor_stabilizing(context, regime, signals):
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="opportunity_floor_not_stabilizing")
        last_buy = self._last_opportunity_floor_buy_call_by_symbol.get(context.symbol, -10_000)
        if self._call_count - last_buy < self.OPPORTUNITY_FLOOR_COOLDOWN_CALLS:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="opportunity_floor_cooldown")
        gap = max(0.0, target - context.current_pct)
        buy_pct = min(gap, self.OPPORTUNITY_FLOOR_MAX_BUY_PCT)
        buy_qty = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="min_notional")
        self._diag["v4_3_opportunity_floor_buy_count"] = self._diag.get("v4_3_opportunity_floor_buy_count", 0) + 1
        guard = self._join_guard(
            self._sizing_guard(context, regime, {"state": "OPPORTUNITY_FLOOR"}, "opportunity-floor-buy"),
            f"v4_3_opportunity_floor_arch_{self._recovery_phase(context, regime, {'state': 'NORMAL'}, signals)}",
        )
        return V42Sizing(
            side="buy",
            setup="opportunity-floor-buy",
            quantity=buy_qty,
            target=target,
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=gap,
            actual_step_pct=buy_pct,
            remaining_gap_after=max(0.0, gap - buy_pct),
        )

    def _recovery_phase_cooldown_relief_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        blocked_sizing: V42Sizing,
    ) -> V42Sizing:
        target = min(float(decision.target), self._risk_ceiling(context, regime), self.SPOT_EXPOSURE_CAP)
        if context.current_pct >= target - self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup=blocked_sizing.setup, blocked_reason="target_reached")
        setup = str(blocked_sizing.setup)
        blocked = self._buy_block_reason(context, regime, episode, signals, setup, decision.target_plan)
        if blocked and blocked != "cooldown":
            return V42Sizing(side="buy", setup=setup, blocked_reason=blocked)
        gap = max(0.0, target - context.current_pct)
        max_buy = min(
            self.RECOVERY_PHASE_COOLDOWN_RELIEF_MAX_BUY,
            max(self.RECOVERY_MIN_STEP, self._max_buy_pct(context, regime, episode, setup, signals)),
        )
        buy_pct = min(gap, max_buy)
        buy_qty = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup=setup, blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup=setup, blocked_reason="min_notional")
        self._diag["v4_3_recovery_phase_cooldown_relief_count"] = (
            self._diag.get("v4_3_recovery_phase_cooldown_relief_count", 0) + 1
        )
        guard = self._join_guard(
            self._buy_sizing_guard(context, regime, episode, signals, setup, decision.target_plan),
            "v4_3_recovery_phase_cooldown_relief",
        )
        return V42Sizing(
            side="buy",
            setup=setup,
            quantity=buy_qty,
            target=target,
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=gap,
            actual_step_pct=buy_pct,
            remaining_gap_after=max(0.0, gap - buy_pct),
        )

    def _cap_buy_by_arch_ceiling(self, context: V42Context, decision: V42DecisionPlan, sizing: V42Sizing) -> V42Sizing:
        if sizing.side != "buy" or sizing.quantity <= 1e-12:
            return sizing
        regime = self._current_regime_for_floor_by_symbol.get(context.symbol)
        if regime is None:
            return sizing
        cap = min(max(float(decision.target), float(decision.mature_target)), self._risk_ceiling(context, regime), self.SPOT_EXPOSURE_CAP)
        room = max(0.0, cap - context.current_pct)
        requested = sizing.quantity * context.price / context.total_value if context.total_value > 0.0 else 0.0
        if requested <= room + 1e-12:
            return sizing
        if room <= 1e-12:
            return V42Sizing(side="buy", setup=sizing.setup, blocked_reason="risk_ceiling")
        notional = room * context.total_value
        if notional < self.min_notional:
            return V42Sizing(side="buy", setup=sizing.setup, blocked_reason="risk_ceiling_min_notional")
        sizing.quantity = notional / context.price if context.price > 0.0 else 0.0
        sizing.actual_step_pct = room
        sizing.actual_position_after = context.current_pct + room
        sizing.remaining_gap_after = max(0.0, float(sizing.target_gap_before) - room)
        sizing.guard = self._join_guard(str(sizing.guard), "v4_3_risk_ceiling")
        return sizing

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        if action is not None and action.side == "sell":
            self._consume_floor_ledger_for_sell(context, regime, action)
        if action is None or sizing.setup != "opportunity-floor-buy" or action.side != "buy":
            return super()._record_event(context, regime, episode, decision, sizing, action)

        symbol = context.symbol
        self._diag["v4_2_action_buy_count"] += 1
        self._diag["v4_3_opportunity_floor_executed_count"] = self._diag.get("v4_3_opportunity_floor_executed_count", 0) + 1
        self._last_opportunity_floor_buy_call_by_symbol[symbol] = self._call_count
        self._record_floor_buy(context, regime, action)
        if hasattr(self, "_record_sleeve_accounting"):
            self._record_sleeve_accounting(context, decision, sizing, action)

    def _record_floor_buy(self, context: V42Context, regime: V42Regime, action: Action) -> None:
        ledger = self._opportunity_floor_ledger_by_symbol.setdefault(
            context.symbol,
            {"quantity": 0.0, "avg_entry": 0.0, "entry_risk_score": context.risk_score, "entry_trend_risk": context.trend_risk, "entry_low": context.price},
        )
        old_qty = float(ledger.get("quantity", 0.0) or 0.0)
        old_entry = float(ledger.get("avg_entry", context.price) or context.price)
        new_qty = old_qty + float(action.quantity)
        ledger["quantity"] = new_qty
        ledger["avg_entry"] = (old_entry * old_qty + context.price * float(action.quantity)) / new_qty if new_qty > 0.0 else 0.0
        ledger["entry_risk_score"] = min(int(ledger.get("entry_risk_score", context.risk_score) or context.risk_score), int(context.risk_score))
        ledger["entry_trend_risk"] = min(int(ledger.get("entry_trend_risk", context.trend_risk) or context.trend_risk), int(context.trend_risk))
        ledger["entry_low"] = min(float(ledger.get("entry_low", context.price) or context.price), float(context.price))
        ledger["entry_structural_bear"] = bool(ledger.get("entry_structural_bear", False) or regime.structural_bear)

    def _consume_floor_ledger_for_sell(self, context: V42Context, regime: V42Regime, action: Action) -> None:
        ledger = self._opportunity_floor_ledger_by_symbol.get(context.symbol)
        if not ledger or not self._floor_exit_allowed(context, regime):
            return
        floor_qty = self._floor_quantity(context)
        if floor_qty <= 1e-12:
            return
        non_floor_qty = max(0.0, super()._main_quantity(context) - floor_qty)
        consume = max(0.0, float(action.quantity) - non_floor_qty)
        if consume <= 1e-12:
            return
        remaining = max(0.0, floor_qty - consume)
        ledger["quantity"] = remaining
        if remaining <= 1e-12:
            ledger["quantity"] = 0.0
            ledger["avg_entry"] = 0.0

    def _main_quantity(self, context: V42Context) -> float:
        main_qty = super()._main_quantity(context)
        regime = self._current_regime_for_floor_by_symbol.get(context.symbol)
        if regime is not None and self._floor_exit_allowed(context, regime):
            return main_qty
        return max(0.0, main_qty - self._floor_quantity(context))

    def _floor_quantity(self, context: V42Context) -> float:
        ledger = self._opportunity_floor_ledger_by_symbol.get(context.symbol, {})
        qty = max(0.0, float(ledger.get("quantity", 0.0) or 0.0))
        return min(qty, max(0.0, float(context.pos.quantity)))

    def _floor_exit_allowed(self, context: V42Context, regime: V42Regime) -> bool:
        ledger = self._opportunity_floor_ledger_by_symbol.get(context.symbol)
        if not ledger or float(ledger.get("quantity", 0.0) or 0.0) <= 1e-12:
            return False
        entry_risk = int(ledger.get("entry_risk_score", context.risk_score) or context.risk_score)
        entry_trend = int(ledger.get("entry_trend_risk", context.trend_risk) or context.trend_risk)
        entry_low = float(ledger.get("entry_low", context.price) or context.price)
        return bool(
            context.risk_score >= entry_risk + 2
            or context.trend_risk >= entry_trend + 1
            or (entry_low > 0.0 and context.price <= entry_low * 0.92)
            or (regime.structural_bear and not bool(ledger.get("entry_structural_bear", False)))
        )

    def _risk_ceiling(self, context: V42Context, regime: V42Regime) -> float:
        if regime.structural_bear and context.trend_risk >= 3:
            return 0.08
        if regime.regime == "BEAR":
            return 0.10 if context.risk_score >= 3 else 0.16
        if regime.regime == "TRANSITION":
            return 0.20 if context.risk_score >= 3 else 0.38
        if regime.regime == "RANGE":
            return 0.35 if context.risk_score >= 3 else 0.70
        if regime.regime == "BULL":
            return 0.55 if context.risk_score >= 3 else self.TARGET_CAP
        return self.TARGET_CAP

    def _recovery_phase(self, context: V42Context, regime: V42Regime, episode: dict, signals: V42Signals) -> str:
        if regime.structural_bear or context.risk_score >= 4 or context.trend_risk >= 3:
            return "panic"
        if signals.trend_continuation and regime.regime == "BULL" and context.risk_score <= 1:
            return "trend_confirmed"
        if signals.value_recovery or signals.strong_recovery_signal or str(episode.get("state", "")) == "RECOVERY_TEST":
            return "recovery_confirmed"
        if signals.recovery_signal or signals.recovery_quality_ok or context.risk_score <= 2:
            return "stabilizing"
        return "panic"

    def _decay_recovery_credit(self, context: V42Context) -> None:
        regime = self._current_regime_for_floor_by_symbol.get(context.symbol)
        if regime is not None:
            signals = self._build_signals(context, regime, {"state": "NORMAL"})
            if self._recovery_phase(context, regime, {"state": "NORMAL"}, signals) in {"recovery_confirmed", "trend_confirmed"}:
                return
        return super()._decay_recovery_credit(context)


class V43ExpOpportunityFloorArchV2Strategy(V43ExpOpportunityFloorArchV1Strategy):
    """V4.3 experiment: same architecture with non-panic floor and staged cooldown relief."""

    RECOVERY_PHASE_COOLDOWN_RELIEF_MAX_BUY = 0.04
    RECOVERY_PHASE_COOLDOWN_RELIEF_CALLS = 6

    @property
    def name(self) -> str:
        return "v4_3_exp_opportunity_floor_arch_v2"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._last_recovery_phase_relief_buy_call_by_symbol: dict[str, int] = {}

    def _opportunity_floor_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        phase = self._recovery_phase(context, regime, {"state": "NORMAL"}, signals)
        if phase == "panic":
            return V42Sizing(side="buy", setup="opportunity-floor-buy", blocked_reason="opportunity_floor_panic")
        return super()._opportunity_floor_sizing(context, regime, signals, prior_sizing)

    def _recovery_phase_cooldown_relief_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        blocked_sizing: V42Sizing,
    ) -> V42Sizing:
        last_buy = self._last_recovery_phase_relief_buy_call_by_symbol.get(context.symbol, -10_000)
        if self._call_count - last_buy < self.RECOVERY_PHASE_COOLDOWN_RELIEF_CALLS:
            return V42Sizing(side="buy", setup=blocked_sizing.setup, blocked_reason="recovery_phase_relief_cooldown")
        return super()._recovery_phase_cooldown_relief_sizing(
            context,
            regime,
            episode,
            signals,
            decision,
            blocked_sizing,
        )

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        super()._record_event(context, regime, episode, decision, sizing, action)
        if action is not None and action.side == "buy" and "v4_3_recovery_phase_cooldown_relief" in str(sizing.guard):
            self._last_recovery_phase_relief_buy_call_by_symbol[context.symbol] = self._call_count


class V43ArchLowRecoveryPriorityV1Strategy(V43ArchAuditV1Strategy):
    """V4.3 architecture fix: promote low-location open-budget recovery before stale sell intents."""

    LOW_RECOVERY_TARGET_PCT = 0.40
    LOW_RECOVERY_MAX_BUY_PCT = 0.04
    LOW_RECOVERY_COOLDOWN_CALLS = 6
    LOW_RECOVERY_MIN_OPEN_BUDGET = 0.015

    @property
    def name(self) -> str:
        return "v4_3_arch_low_recovery_priority_v1"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        if self._low_recovery_priority_should_override(context, regime, episode, signals, decision, sizing):
            priority = self._low_recovery_priority_sizing(context, regime, episode, sizing)
            if priority.side or priority.blocked_reason:
                return priority if priority.side else sizing
        return sizing

    def _low_recovery_priority_should_override(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
    ) -> bool:
        if not self._low_recovery_location_ok(context, regime):
            return False
        if context.current_pct >= self.LOW_RECOVERY_TARGET_PCT - self.RECOVERY_MIN_STEP:
            return False
        if signals.distribution_exhaustion:
            return False
        if regime.btc_regime == "BEAR" or context.trend_risk >= 3:
            return False
        open_budget = self._low_recovery_open_budget(episode)
        if open_budget < self.LOW_RECOVERY_MIN_OPEN_BUDGET:
            return False
        if not self._low_recovery_has_discount(context, episode):
            return False
        blocked = str(sizing.blocked_reason or "")
        stale_sell = bool(sizing.side == "sell" and blocked in {"target_reached", "main_quantity_unavailable"})
        stalled_recovery = bool(
            sizing.side == "buy"
            and sizing.setup in {"recovery-probe-buy", "value-recovery"}
            and blocked in {
                "recovery_signal_missing",
                "recovery_step_too_small",
                "cooldown",
                "target_reached",
                "insufficient_sell_to_low_drawdown",
                "current_discount_missing",
            }
        )
        no_action = bool(not sizing.side and not blocked and decision.intent in {"HOLD", "ACCUMULATE", "EXIT", "DEFEND"})
        return bool(stale_sell or stalled_recovery or no_action)

    def _low_recovery_priority_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        prior_sizing: V42Sizing,
    ) -> V42Sizing:
        last_buy = self._last_buy_call_by_symbol.get(context.symbol, -10_000)
        if self._call_count - last_buy < self.LOW_RECOVERY_COOLDOWN_CALLS:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="low_recovery_priority_cooldown")
        open_budget = self._low_recovery_open_budget(episode)
        gap = max(0.0, self.LOW_RECOVERY_TARGET_PCT - context.current_pct)
        if gap < self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="low_recovery_priority_target_reached")
        buy_pct = min(open_budget, gap, self._low_recovery_max_buy_pct(context, regime))
        if buy_pct < self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="low_recovery_priority_step_too_small")
        buy_qty = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup="recovery-probe-buy", blocked_reason="min_notional")
        self._diag["v4_3_low_recovery_priority_buy_count"] = self._diag.get("v4_3_low_recovery_priority_buy_count", 0) + 1
        guard = self._join_guard(
            self._sizing_guard(context, regime, episode, "recovery-probe-buy"),
            "v4_3_low_recovery_priority",
        )
        return V42Sizing(
            side="buy",
            setup="recovery-probe-buy",
            quantity=buy_qty,
            target=min(self.TARGET_CAP, context.current_pct + buy_pct),
            guard=guard,
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=max(0.0, self.LOW_RECOVERY_TARGET_PCT - context.current_pct),
            actual_step_pct=buy_pct,
            remaining_gap_after=max(0.0, self.LOW_RECOVERY_TARGET_PCT - context.current_pct - buy_pct),
        )

    def _low_recovery_open_budget(self, episode: dict) -> float:
        budget = float(episode.get("cumulative_sold_pct", episode.get("recovery_budget_pct", 0.0)) or 0.0)
        if budget <= 0.0:
            budget = float(episode.get("sold_pct", 0.0) or 0.0)
        recovered = float(episode.get("cumulative_recovered_pct", episode.get("recovery_bought_pct", 0.0)) or 0.0)
        return max(0.0, budget - recovered)

    def _low_recovery_location_ok(self, context: V42Context, regime: V42Regime) -> bool:
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.30)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.35)
            or (not pd.isna(regime.price_vs_ema168) and regime.price_vs_ema168 <= -0.15)
        )

    def _low_recovery_has_discount(self, context: V42Context, episode: dict) -> bool:
        sell_price = float(episode.get("sell_price", 0.0) or 0.0)
        if sell_price <= 0.0:
            return True
        discount = 1.0 - context.price / sell_price
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        return bool(
            discount >= 0.02
            or (not pd.isna(rolling_pos) and rolling_pos <= 0.20)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.25)
        )

    def _low_recovery_max_buy_pct(self, context: V42Context, regime: V42Regime) -> float:
        cap = self.LOW_RECOVERY_MAX_BUY_PCT
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        deep = bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.18)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.20)
            or (not pd.isna(regime.price_vs_ema168) and regime.price_vs_ema168 <= -0.25)
        )
        if deep:
            cap = max(cap, 0.06)
        if regime.regime == "BEAR":
            cap = min(cap, 0.03)
        return max(0.0, cap)


class V43ArchLowRecoveryPriorityV2Strategy(V43ArchLowRecoveryPriorityV1Strategy):
    """V4.3 architecture fix v2: isolate low-recovery fills from episode state transitions."""

    @property
    def name(self) -> str:
        return "v4_3_arch_low_recovery_priority_v2"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._low_recovery_budget_used_by_symbol: dict[str, float] = {}

    def _low_recovery_open_budget(self, episode: dict) -> float:
        symbol = str(episode.get("symbol", ""))
        open_budget = super()._low_recovery_open_budget(episode)
        used = float(self._low_recovery_budget_used_by_symbol.get(symbol, 0.0) or 0.0)
        return max(0.0, open_budget - used)

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        if action is None or action.side != "buy" or "v4_3_low_recovery_priority" not in str(sizing.guard):
            return super()._record_event(context, regime, episode, decision, sizing, action)

        buy_pct = action.quantity * action.price / context.total_value if context.total_value > 0.0 else 0.0
        self._low_recovery_budget_used_by_symbol[context.symbol] = (
            float(self._low_recovery_budget_used_by_symbol.get(context.symbol, 0.0) or 0.0)
            + max(0.0, buy_pct)
        )
        active = self._episodes_by_symbol.pop(context.symbol, None)
        try:
            return super()._record_event(context, regime, episode, decision, sizing, action)
        finally:
            if active is not None and context.symbol not in self._episodes_by_symbol:
                self._episodes_by_symbol[context.symbol] = active


class V43ArchLowRecoveryPriorityV3Strategy(V43ArchLowRecoveryPriorityV2Strategy):
    """V4.3 architecture fix v3: only promote stabilized low-location recovery tests."""

    @property
    def name(self) -> str:
        return "v4_3_arch_low_recovery_priority_v3"

    def _low_recovery_priority_should_override(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
    ) -> bool:
        if not super()._low_recovery_priority_should_override(context, regime, episode, signals, decision, sizing):
            return False
        if str(episode.get("state", "NORMAL")) != "RECOVERY_TEST":
            return False
        if regime.regime not in {"RANGE", "BULL"}:
            return False
        if context.trend_risk != 0 or context.drawdown_risk != 0:
            return False
        blocked = str(sizing.blocked_reason or "")
        return bool(blocked in {"recovery_step_too_small", "target_reached", "cooldown"} or not sizing.side)


class V43ExpLowBaseSleeveV1Strategy(V43ArchAuditV1Strategy):
    """V4.3 experiment: independent low-location base sleeve, held until base-exit."""

    LOW_BASE_CAP = {"BTC/USDT": 0.08, "ETH/USDT": 0.08, "BNB/USDT": 0.08}
    LOW_BASE_PORTFOLIO_CAP = 0.18
    LOW_BASE_MAX_BUY_PCT = 0.03
    LOW_BASE_COOLDOWN_CALLS = 30
    LOW_BASE_MIN_POSITION_GAP = 0.02

    @property
    def name(self) -> str:
        return "v4_3_exp_low_base_sleeve_v1"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = self._low_base_sizing(context, regime, signals, decision)
        if sizing.side or sizing.blocked_reason:
            return sizing if sizing.side else super()._compute_sizing(context, regime, episode, signals, decision)
        return super()._compute_sizing(context, regime, episode, signals, decision)

    def _low_base_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        if not self._low_base_location_ok(context, regime):
            return V42Sizing()
        if self._low_base_path_accelerating(context, regime):
            return V42Sizing(side="buy", setup="low-base-buy", blocked_reason="low_base_path_accelerating")
        if signals.distribution_exhaustion:
            return V42Sizing(side="buy", setup="low-base-buy", blocked_reason="low_base_distribution_exhaustion")
        if regime.btc_regime == "BEAR" and context.trend_risk >= 2:
            return V42Sizing(side="buy", setup="low-base-buy", blocked_reason="low_base_btc_bear_hard_risk")
        cap = self._low_base_asset_cap(context.symbol)
        floor = self._bear_base_floor(context)
        if cap <= 0.0 or floor >= cap - self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="low-base-buy", blocked_reason="low_base_cap_filled")
        portfolio_room = max(0.0, self.LOW_BASE_PORTFOLIO_CAP - self._low_base_portfolio_used_pct(context))
        if portfolio_room < self.RECOVERY_MIN_STEP:
            return V42Sizing(side="buy", setup="low-base-buy", blocked_reason="low_base_portfolio_cap_filled")
        gap = min(cap - floor, portfolio_room)
        if gap < self.LOW_BASE_MIN_POSITION_GAP:
            return V42Sizing(side="buy", setup="low-base-buy", blocked_reason="low_base_gap_too_small")
        last_buy = int(getattr(self, "_last_low_base_buy_call_by_symbol", {}).get(context.symbol, -10_000))
        if self._call_count - last_buy < self.LOW_BASE_COOLDOWN_CALLS:
            return V42Sizing(side="buy", setup="low-base-buy", blocked_reason="low_base_cooldown")
        buy_pct = min(gap, self.LOW_BASE_MAX_BUY_PCT)
        buy_qty = context.total_value * buy_pct / context.price if context.price > 0.0 else 0.0
        if buy_qty <= 1e-12:
            return V42Sizing(side="buy", setup="low-base-buy", blocked_reason="zero_quantity")
        if buy_qty * context.price < self.min_notional:
            self._diag["v4_2_min_notional_blocked_count"] += 1
            return V42Sizing(side="buy", setup="low-base-buy", blocked_reason="min_notional")
        decision.primary_sleeve = V42SleevePlan(
            sleeve="low-base",
            side="buy",
            setup="low-base-buy",
            target=min(self.TARGET_CAP, context.current_pct + buy_pct),
            guard="v4_3_low_base",
            priority=85,
            allowed=True,
        )
        self._diag["v4_3_low_base_buy_count"] = self._diag.get("v4_3_low_base_buy_count", 0) + 1
        return V42Sizing(
            side="buy",
            setup="low-base-buy",
            quantity=buy_qty,
            target=min(self.TARGET_CAP, context.current_pct + buy_pct),
            guard="v4_3_low_base",
            actual_position_before=context.current_pct,
            actual_position_after=context.current_pct + buy_pct,
            target_gap_before=gap,
            actual_step_pct=buy_pct,
            remaining_gap_after=max(0.0, gap - buy_pct),
        )

    def _record_event(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        decision: V42DecisionPlan,
        sizing: V42Sizing,
        action: Action | None,
    ) -> None:
        if action is not None and action.side == "buy" and sizing.setup == "low-base-buy":
            self._record_low_base_buy(context, action)
            low_base_calls = getattr(self, "_last_low_base_buy_call_by_symbol", None)
            if low_base_calls is None:
                self._last_low_base_buy_call_by_symbol = {}
                low_base_calls = self._last_low_base_buy_call_by_symbol
            low_base_calls[context.symbol] = self._call_count
        return super()._record_event(context, regime, episode, decision, sizing, action)

    def _action_sleeve(self, decision: V42DecisionPlan, sizing: V42Sizing) -> str:
        primary = decision.primary_sleeve.sleeve if decision.primary_sleeve is not None else ""
        if primary == "low-base" or sizing.setup == "low-base-buy":
            return "base"
        return super()._action_sleeve(decision, sizing)

    def _record_low_base_buy(self, context: V42Context, action: Action) -> None:
        ledger = self._base_ledger_by_symbol.setdefault(context.symbol, self._new_base_ledger())
        buy_pct = action.quantity * action.price / context.total_value if context.total_value > 0.0 else 0.0
        old_base_qty = float(ledger.get("base_quantity", 0.0) or 0.0)
        old_entry = float(ledger.get("base_avg_entry_price", context.price) or context.price)
        new_base_qty = old_base_qty + float(action.quantity)
        if new_base_qty > 0.0:
            ledger["base_avg_entry_price"] = (old_entry * old_base_qty + context.price * float(action.quantity)) / new_base_qty
        ledger["base_budget_used_pct"] = self._ledger_base_budget_used_pct(ledger) + max(0.0, buy_pct)
        ledger["base_quantity"] = new_base_qty
        ledger["base_position_pct"] = self._base_pct_from_quantity(context, new_base_qty)
        ledger["base_source"] = self._join_guard(str(ledger.get("base_source", "")), "low_base")
        ledger["base_layer"] = max(int(ledger.get("base_layer", 0) or 0), 1)
        if ledger.get("base_entry_call") is None:
            ledger["base_entry_call"] = self._call_count
            ledger["base_peak_price"] = context.price
            ledger["base_peak_profit"] = 0.0

    def _low_base_asset_cap(self, symbol: str) -> float:
        return max(0.0, float(self.LOW_BASE_CAP.get(symbol, 0.0)))

    def _low_base_portfolio_used_pct(self, context: V42Context) -> float:
        total = 0.0
        for symbol, ledger in self._base_ledger_by_symbol.items():
            if symbol == context.symbol:
                total += self._bear_base_floor(context)
            else:
                total += max(0.0, float(ledger.get("base_position_pct", 0.0) or 0.0))
        return total

    def _low_base_location_ok(self, context: V42Context, regime: V42Regime) -> bool:
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        return bool(
            (not pd.isna(rolling_pos) and rolling_pos <= 0.20)
            or (not pd.isna(donchian_pos) and donchian_pos <= 0.20)
            or (not pd.isna(regime.price_vs_ema168) and regime.price_vs_ema168 <= -0.25)
        )

    def _low_base_path_accelerating(self, context: V42Context, regime: V42Regime) -> bool:
        roc_20 = self._value(context.latest, "roc_20", 0.0)
        atr_rank = regime.atr_rank
        return bool(
            (not pd.isna(roc_20) and roc_20 <= -0.25)
            or (
                not pd.isna(atr_rank)
                and atr_rank >= 0.97
                and not pd.isna(roc_20)
                and roc_20 <= -0.15
            )
        )


class V43ExpLowBaseSleeveV2Strategy(V43ExpLowBaseSleeveV1Strategy):
    """V4.3 low-base v2: low-base is supplemental and never preempts active main flow."""

    @property
    def name(self) -> str:
        return "v4_3_exp_low_base_sleeve_v2"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        primary = super(V43ExpLowBaseSleeveV1Strategy, self)._compute_sizing(context, regime, episode, signals, decision)
        if primary.side and primary.quantity > 1e-12:
            return primary
        blocked = str(primary.blocked_reason or "")
        can_supplement = bool(
            not primary.side
            or blocked in {"target_reached", "main_quantity_unavailable", "zero_quantity"}
            or (primary.side == "sell" and blocked == "target_reached")
        )
        if not can_supplement:
            return primary
        low_base = self._low_base_sizing(context, regime, signals, decision)
        if low_base.side:
            return low_base
        return primary


