class V43ExpLowBaseSleeveV13Strategy(V43ExpLowBaseSleeveV10Strategy):
    """V4.3 low-base v13: sell profitable base when independent exposure creates cash pressure."""

    BASE_PRESSURE_EXIT_TOTAL_PCT = 1.02
    BASE_PRESSURE_EXIT_TARGET_PCT = 0.98
    BASE_PRESSURE_EXIT_MIN_PROFIT = 0.25
    BASE_PRESSURE_EXIT_MAX_STEP = 0.06

    @property
    def name(self) -> str:
        return "v4_3_exp_low_base_sleeve_v13"

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        pressure_exit = self._base_pressure_exit_sizing(context, regime, decision)
        if pressure_exit.side:
            return pressure_exit
        return super()._compute_sizing(context, regime, episode, signals, decision)

    def _base_pressure_exit_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        total_pct = float(getattr(context, "total_position_pct", context.current_pct))
        if total_pct <= self.BASE_PRESSURE_EXIT_TOTAL_PCT:
            return V42Sizing()
        base_qty = self._base_quantity(context)
        if base_qty <= 1e-12:
            return V42Sizing()
        ledger = self._base_ledger_by_symbol.get(context.symbol, {})
        entry = float(ledger.get("base_avg_entry_price", 0.0) or 0.0)
        if entry <= 0.0 or context.price / entry - 1.0 < self.BASE_PRESSURE_EXIT_MIN_PROFIT:
            return V42Sizing()
        rolling_pos = self._value(context.latest, "rolling_365d_pos", 0.5)
        donchian_pos = self._value(context.latest, "donchian_pos", 0.5)
        high_location = bool(
            (not pd.isna(rolling_pos) and rolling_pos >= 0.72)
            or (not pd.isna(donchian_pos) and donchian_pos >= 0.72)
            or (not pd.isna(regime.price_vs_ema168) and regime.price_vs_ema168 >= 0.22)
        )
        if not high_location:
            return V42Sizing()
        excess = max(0.0, total_pct - self.BASE_PRESSURE_EXIT_TARGET_PCT)
        sell_pct = min(excess, self.BASE_PRESSURE_EXIT_MAX_STEP)
        qty = min(base_qty, context.total_value * sell_pct / context.price if context.price > 0.0 else 0.0)
        if qty <= 1e-12:
            return V42Sizing()
        if qty * context.price < self.min_notional:
            return V42Sizing(side="sell", setup="bear-base-exit", blocked_reason="min_notional")
        decision.primary_sleeve = V42SleevePlan(
            sleeve="bear-base-exit",
            side="sell",
            setup="bear-base-exit",
            target=max(0.0, total_pct - sell_pct),
            guard="v4_3_base_pressure_exit",
            priority=95,
            allowed=True,
        )
        return V42Sizing(
            side="sell",
            setup="bear-base-exit",
            quantity=qty,
            target=max(0.0, total_pct - sell_pct),
            guard="v4_3_base_pressure_exit",
            actual_position_before=total_pct,
            actual_position_after=max(0.0, total_pct - sell_pct),
            target_gap_before=sell_pct,
            actual_step_pct=sell_pct,
            remaining_gap_after=0.0,
        )


class V43ExpLowBaseSleeveV14Strategy(V43ExpLowBaseSleeveV8Strategy):
    """V4.3 low-base v14: weighted base exposure for decisions, real spot cap for execution."""

    BASE_DECISION_WEIGHT = 0.50
    SPOT_EXPOSURE_CAP = 1.00

    @property
    def name(self) -> str:
        return "v4_3_exp_low_base_sleeve_v14"

    def _build_context(self, candles_by_symbol, portfolio, current_prices) -> V42Context | None:
        context = V43ExpLowBaseSleeveV4Strategy._build_context(self, candles_by_symbol, portfolio, current_prices)
        if context is None:
            return None
        real_pct = float(context.current_pct)
        base_pct = self._base_pct_from_quantity(context, self._base_quantity(context))
        decision_base_pct = base_pct * max(0.0, min(1.0, float(self.BASE_DECISION_WEIGHT)))
        decision_pct = max(0.0, real_pct - base_pct + decision_base_pct)
        setattr(context, "total_position_pct", real_pct)
        setattr(context, "base_position_pct_for_decision", float(base_pct))
        setattr(context, "base_decision_weight", float(self.BASE_DECISION_WEIGHT))
        setattr(context, "decision_position_pct", float(decision_pct))
        context.current_pct = decision_pct
        return context

    def _compute_sizing(
        self,
        context: V42Context,
        regime: V42Regime,
        episode: dict,
        signals: V42Signals,
        decision: V42DecisionPlan,
    ) -> V42Sizing:
        sizing = super()._compute_sizing(context, regime, episode, signals, decision)
        return self._cap_buy_by_real_spot_exposure(context, sizing)

    def _cap_buy_by_real_spot_exposure(self, context: V42Context, sizing: V42Sizing) -> V42Sizing:
        if sizing.side != "buy" or sizing.quantity <= 1e-12:
            return sizing
        real_pct = float(getattr(context, "total_position_pct", context.current_pct))
        room = max(0.0, float(self.SPOT_EXPOSURE_CAP) - real_pct)
        requested_pct = float(sizing.quantity) * float(context.price) / float(context.total_value) if context.total_value > 0.0 else 0.0
        if requested_pct <= room + 1e-12:
            return sizing
        if room <= 1e-12:
            return V42Sizing(side="buy", setup=sizing.setup, blocked_reason="spot_exposure_cap")
        capped_notional = room * float(context.total_value)
        if capped_notional < self.min_notional:
            return V42Sizing(side="buy", setup=sizing.setup, blocked_reason="spot_exposure_cap_min_notional")
        capped_qty = capped_notional / float(context.price) if context.price > 0.0 else 0.0
        if capped_qty <= 1e-12:
            return V42Sizing(side="buy", setup=sizing.setup, blocked_reason="spot_exposure_cap_zero_quantity")
        sizing.quantity = capped_qty
        sizing.actual_step_pct = room
        sizing.actual_position_after = context.current_pct + room
        sizing.remaining_gap_after = max(0.0, float(sizing.target_gap_before) - room)
        sizing.guard = self._join_guard(str(sizing.guard), "v4_3_real_spot_cap")
        return sizing


