class V40BHStrategy(V40AXStrategy):
    """V4.0BH: peak-drawdown episode only caps future buys."""

    VERSION_LABEL = "v4_0BH"
    RECENT_PEAK_CALLS = 120
    PEAK_DRAWDOWN_TRIGGER = 0.16
    PEAK_DRAWDOWN_SEVERE = 0.24
    PEAK_DRAWDOWN_TARGET = 0.82
    PEAK_DRAWDOWN_SEVERE_TARGET = 0.74
    PEAK_DRAWDOWN_RELEASE = 0.08
    PEAK_DRAWDOWN_MAX_CALLS = 60

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._v40bh_price_history: dict[str, list[tuple[int, float]]] = {}
        self._v40bh_episode: dict[str, dict] = {}
        self._v40bh_diag: dict[str, int] = {
            "v4_0BH_peak_drawdown_episode_started_count": 0,
            "v4_0BH_peak_drawdown_episode_active_count": 0,
            "v4_0BH_peak_drawdown_episode_released_count": 0,
            "v4_0BH_peak_drawdown_buy_capped_count": 0,
            "v4_0BH_peak_drawdown_buy_blocked_count": 0,
        }

    @property
    def name(self) -> str:
        return "v4_0BH"

    def strategy_diagnostics(self) -> dict[str, int]:
        diagnostics = super().strategy_diagnostics()
        diagnostics.update(self._v40bh_diag)
        return diagnostics

    def _maybe_sell(
        self,
        *,
        symbol: str,
        latest: pd.Series,
        price: float,
        pos: PositionState,
        current_pct: float,
        total_value: float,
        sell_target: float,
        market: dict,
    ) -> list[Action]:
        self._v40bh_record_price(symbol, price)
        self._v40bh_update_episode(symbol=symbol, latest=latest, price=price, current_pct=current_pct)
        return super()._maybe_sell(
            symbol=symbol,
            latest=latest,
            price=price,
            pos=pos,
            current_pct=current_pct,
            total_value=total_value,
            sell_target=sell_target,
            market=market,
        )

    def _adjust_buy_execution(
        self,
        *,
        latest: pd.Series,
        price: float,
        raw_state: str,
        buy_setup: str,
        max_buy: float,
        confirmed_state: str,
    ) -> tuple[float, str]:
        adjusted, guard = super()._adjust_buy_execution(
            latest=latest,
            price=price,
            raw_state=raw_state,
            buy_setup=buy_setup,
            max_buy=max_buy,
            confirmed_state=confirmed_state,
        )
        if adjusted <= 0.0:
            return adjusted, guard
        symbol = str(getattr(self, "_v40ar_current_buy_symbol", ""))
        if not symbol:
            return adjusted, guard
        self._v40bh_record_price(symbol, price)
        current_pct = float(getattr(self, "_v40ao_current_pct", 0.0))
        episode = self._v40bh_update_episode(symbol=symbol, latest=latest, price=price, current_pct=current_pct)
        if not episode:
            return adjusted, guard
        cap = float(episode.get("cap", 1.0))
        capped = min(adjusted, max(0.0, cap - current_pct))
        if capped < self.MIN_ADJUST_THRESHOLD:
            self._v40bh_diag["v4_0BH_peak_drawdown_buy_blocked_count"] += 1
            return 0.0, self._join_guard(guard, f"{self.VERSION_LABEL}_peak_drawdown_buy_blocked")
        if capped < adjusted:
            self._v40bh_diag["v4_0BH_peak_drawdown_buy_capped_count"] += 1
            return capped, self._join_guard(guard, f"{self.VERSION_LABEL}_peak_drawdown_buy_capped")
        return adjusted, guard

    def _v40bh_record_price(self, symbol: str, price: float) -> None:
        history = self._v40bh_price_history.setdefault(symbol, [])
        history.append((self._call_count, float(price)))
        cutoff = self._call_count - self.RECENT_PEAK_CALLS
        self._v40bh_price_history[symbol] = [(call, value) for call, value in history if call >= cutoff]

    def _v40bh_update_episode(self, *, symbol: str, latest: pd.Series, price: float, current_pct: float) -> dict | None:
        episode = self._v40bh_episode.get(symbol)
        if episode:
            age = self._call_count - int(episode.get("call", -10_000))
            trigger_price = float(episode.get("trigger_price", 0.0) or 0.0)
            release = bool(
                age > self.PEAK_DRAWDOWN_MAX_CALLS
                or (trigger_price > 0.0 and price >= trigger_price * (1.0 + self.PEAK_DRAWDOWN_RELEASE))
            )
            if release:
                self._v40bh_episode.pop(symbol, None)
                self._v40bh_diag["v4_0BH_peak_drawdown_episode_released_count"] += 1
                episode = None
            else:
                self._v40bh_diag["v4_0BH_peak_drawdown_episode_active_count"] += 1
                return episode

        active, severe, cap = self._v40bh_peak_drawdown_trigger(symbol=symbol, latest=latest, price=price, current_pct=current_pct)
        if not active:
            return None
        episode = {
            "call": self._call_count,
            "trigger_price": float(price),
            "cap": float(cap),
            "severe": bool(severe),
        }
        self._v40bh_episode[symbol] = episode
        self._v40bh_diag["v4_0BH_peak_drawdown_episode_started_count"] += 1
        return episode

    def _v40bh_peak_drawdown_trigger(self, *, symbol: str, latest: pd.Series, price: float, current_pct: float) -> tuple[bool, bool, float]:
        if current_pct < 0.82:
            return False, False, 1.0
        history = self._v40bh_price_history.get(symbol, [])
        if not history:
            return False, False, 1.0
        recent_peak = max(value for _, value in history)
        if recent_peak <= 0.0:
            return False, False, 1.0
        drawdown = recent_peak / float(price) - 1.0
        btc_vs_ema72 = self._v3_value(latest, "btc_price_vs_ema72")
        btc_roc_20 = self._v3_value(latest, "btc_roc_20")
        market_not_strong = bool(self._v40g_le(btc_vs_ema72, 0.08) or self._v40g_le(btc_roc_20, 0.04))
        if drawdown >= self.PEAK_DRAWDOWN_SEVERE and market_not_strong:
            return True, True, self.PEAK_DRAWDOWN_SEVERE_TARGET
        if drawdown >= self.PEAK_DRAWDOWN_TRIGGER and market_not_strong:
            return True, False, self.PEAK_DRAWDOWN_TARGET
        return False, False, 1.0


class V40BIStrategy(V40BHStrategy):
    """V4.0BI: one-shot peak drawdown trim, then buy cap episode."""

    VERSION_LABEL = "v4_0BI"
    PEAK_DRAWDOWN_ONESHOT_MAX_SELL = 0.08

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._v40bi_diag: dict[str, int] = {
            "v4_0BI_peak_drawdown_oneshot_sell_count": 0,
            "v4_0BI_peak_drawdown_oneshot_severe_sell_count": 0,
        }

    @property
    def name(self) -> str:
        return "v4_0BI"

    def strategy_diagnostics(self) -> dict[str, int]:
        diagnostics = super().strategy_diagnostics()
        diagnostics.update(self._v40bi_diag)
        return diagnostics

    def _maybe_sell(
        self,
        *,
        symbol: str,
        latest: pd.Series,
        price: float,
        pos: PositionState,
        current_pct: float,
        total_value: float,
        sell_target: float,
        market: dict,
    ) -> list[Action]:
        self._v40bh_record_price(symbol, price)
        had_episode = symbol in self._v40bh_episode
        episode = self._v40bh_update_episode(symbol=symbol, latest=latest, price=price, current_pct=current_pct)
        if episode and not had_episode:
            target = float(episode.get("cap", 1.0))
            if current_pct > target + self.MIN_ADJUST_THRESHOLD:
                sell_pct = min(current_pct - target, self.PEAK_DRAWDOWN_ONESHOT_MAX_SELL)
                quantity = min(total_value * sell_pct / price, pos.quantity)
                if quantity > 1e-12 and quantity * price >= self.min_notional:
                    severe = bool(episode.get("severe", False))
                    self._v40bi_diag[
                        "v4_0BI_peak_drawdown_oneshot_severe_sell_count" if severe else "v4_0BI_peak_drawdown_oneshot_sell_count"
                    ] += 1
                    candidate = {
                        "symbol": symbol,
                        "side": "sell",
                        "setup": "peak-drawdown-oneshot-sell",
                        "price": float(price),
                        "target": float(target),
                        "risk_score": market["risk_score"],
                        "trend_risk": market["trend_risk"],
                        "drawdown_risk": market["drawdown_risk"],
                        "raw_state": market["raw_state"],
                        "confirmed_state": market["confirmed_state"],
                    }
                    guard = f"{self.VERSION_LABEL}_{'peak_drawdown_oneshot_severe' if severe else 'peak_drawdown_oneshot'}"
                    return [self._action_from_sell_candidate(candidate, {"quantity": quantity, "guard": guard})]
        return super()._maybe_sell(
            symbol=symbol,
            latest=latest,
            price=price,
            pos=pos,
            current_pct=current_pct,
            total_value=total_value,
            sell_target=sell_target,
            market=market,
        )


class V40BJStrategy(V40BIStrategy):
    """V4.0BJ: narrower one-shot peak drawdown trim."""

    VERSION_LABEL = "v4_0BJ"
    PEAK_DRAWDOWN_TRIGGER = 0.20
    PEAK_DRAWDOWN_SEVERE = 0.30

    @property
    def name(self) -> str:
        return "v4_0BJ"

    def _v40bh_peak_drawdown_trigger(self, *, symbol: str, latest: pd.Series, price: float, current_pct: float) -> tuple[bool, bool, float]:
        if current_pct < 0.95:
            return False, False, 1.0
        return super()._v40bh_peak_drawdown_trigger(
            symbol=symbol,
            latest=latest,
            price=price,
            current_pct=current_pct,
        )


class V317BStrategy(V317AStrategy):
    """V3.17B: narrow BNB early-recovery target-reduce softening."""

    VERSION_LABEL = "v3_17B"
    BNB_EARLY_RECOVERY_SELL_MIN_THRESHOLD = 0.16
    BNB_EARLY_RECOVERY_SELL_MAX_SELL = 0.04

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._v317b_symbol = ""

    @property
    def name(self) -> str:
        return "v3_17B"

    def compute_actions(self, candles_by_symbol, portfolio, current_prices):
        self._v317b_symbol = strategy_utils.resolve_symbol(candles_by_symbol) or ""
        return super().compute_actions(candles_by_symbol, portfolio, current_prices)

    def _adjust_sell_execution(
        self,
        latest: pd.Series,
        price: float,
        raw_state: str,
        confirmed_state: str,
        trend_risk: int,
        drawdown_risk: int,
        risk_score: int,
        sell_setup: str,
        sell_threshold: float,
        max_sell: float,
    ) -> tuple[float, float, str]:
        threshold, adjusted_max_sell, guard = super()._adjust_sell_execution(
            latest=latest,
            price=price,
            raw_state=raw_state,
            confirmed_state=confirmed_state,
            trend_risk=trend_risk,
            drawdown_risk=drawdown_risk,
            risk_score=risk_score,
            sell_setup=sell_setup,
            sell_threshold=sell_threshold,
            max_sell=max_sell,
        )
        if not self._is_bnb_early_recovery_sell_fly_risk(
            latest=latest,
            price=price,
            raw_state=raw_state,
            confirmed_state=confirmed_state,
            trend_risk=trend_risk,
            drawdown_risk=drawdown_risk,
            risk_score=risk_score,
            sell_setup=sell_setup,
        ):
            return threshold, adjusted_max_sell, guard
        return (
            max(threshold, self.BNB_EARLY_RECOVERY_SELL_MIN_THRESHOLD),
            min(adjusted_max_sell, self.BNB_EARLY_RECOVERY_SELL_MAX_SELL),
            self._join_guard(guard, f"{self.VERSION_LABEL}_bnb_early_recovery_target_reduce_softened"),
        )

    def _is_bnb_early_recovery_sell_fly_risk(
        self,
        *,
        latest: pd.Series,
        price: float,
        raw_state: str,
        confirmed_state: str,
        trend_risk: int,
        drawdown_risk: int,
        risk_score: int,
        sell_setup: str,
    ) -> bool:
        if self._v317b_symbol != "BNB/USDT":
            return False
        if sell_setup != "target-reduce":
            return False
        if raw_state != "MIXED" or confirmed_state != "MIXED":
            return False
        if trend_risk != 2 or drawdown_risk != 0 or risk_score != 2:
            return False
        if str(latest.get("btc_regime", "")) != "BULL":
            return False
        if self._transition_context(latest=latest, price=price, market={
            "raw_state": raw_state,
            "confirmed_state": confirmed_state,
            "trend_risk": trend_risk,
            "drawdown_risk": drawdown_risk,
            "risk_score": risk_score,
        }) != "early_recovery":
            return False

        rolling_365d_pos = self._v3_value(latest, "rolling_365d_pos")
        donchian_pos = self._v3_value(latest, "donchian_pos")
        ema168_slope = self._v3_value(latest, "ema168_slope")
        ema24_slope = self._v3_value(latest, "ema24_slope")
        if any(pd.isna(value) for value in (rolling_365d_pos, donchian_pos, ema168_slope, ema24_slope)):
            return False
        return bool(
            rolling_365d_pos <= 0.52
            and donchian_pos >= 0.58
            and ema168_slope < 0.0
            and ema24_slope >= -0.025
        )


class V317CStrategy(V317AStrategy):
    """V3.17C: BTC-only early-recovery target-reduce defer probe."""

    VERSION_LABEL = "v3_17C"
    BTC_EARLY_REDUCE_DEFER_CALLS = 3

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._v317c_symbol = ""
        self._v317c_pending_sell: dict | None = None

    @property
    def name(self) -> str:
        return "v3_17C"

    def compute_actions(self, candles_by_symbol, portfolio, current_prices):
        self._v317c_symbol = strategy_utils.resolve_symbol(candles_by_symbol) or ""
        actions = super().compute_actions(candles_by_symbol, portfolio, current_prices)
        pending = self._v317c_release_pending_sell_if_due(portfolio=portfolio, current_prices=current_prices)
        if pending is not None:
            return [pending]
        if not actions:
            return actions
        action = actions[0]
        latest = None
        frame = candles_by_symbol.get(self._v317c_symbol)
        if frame is not None and not frame.empty:
            latest = frame.iloc[-1]
        if not self._should_defer_btc_early_recovery_target_reduce(action, latest=latest):
            if action.side == "sell" and "_sell_target-reduce_" not in action.reason:
                self._v317c_pending_sell = None
            return actions
        self._v317c_pending_sell = {
            "due_call": self._call_count + self.BTC_EARLY_REDUCE_DEFER_CALLS,
            "symbol": action.symbol,
            "quantity": float(action.quantity),
            "reason": f"{action.reason}-{self.VERSION_LABEL}_btc_early_target_reduce_deferred{self.BTC_EARLY_REDUCE_DEFER_CALLS}",
        }
        return []

    def _v317c_release_pending_sell_if_due(self, *, portfolio, current_prices) -> Action | None:
        if not self._v317c_pending_sell:
            return None
        if self._call_count < int(self._v317c_pending_sell["due_call"]):
            return None
        symbol = str(self._v317c_pending_sell["symbol"])
        price = float(current_prices.get(symbol, 0.0))
        if price <= 0:
            self._v317c_pending_sell = None
            return None
        pos = portfolio.positions.get(symbol, PositionState())
        quantity = min(float(self._v317c_pending_sell["quantity"]), pos.quantity)
        reason = str(self._v317c_pending_sell["reason"])
        self._v317c_pending_sell = None
        if quantity <= 1e-12 or quantity * price < self.min_notional:
            return None
        return Action(
            symbol=symbol,
            side="sell",
            quantity=quantity,
            price=price,
            reason=reason,
        )

    def _should_defer_btc_early_recovery_target_reduce(self, action: Action, *, latest: pd.Series | None = None) -> bool:
        if self._v317c_symbol != "BTC/USDT" or action.symbol != "BTC/USDT":
            return False
        reason = str(action.reason)
        if "_sell_target-reduce_" not in reason:
            return False
        if "tc_early_recovery_" not in reason:
            return False
        parsed = self._parse_action_context(action)
        if int(parsed.get("trend_risk", 9)) > 2:
            return False
        if int(parsed.get("drawdown_risk", 9)) != 0:
            return False
        if int(parsed.get("risk_score", 9)) > 2:
            return False
        if latest is None:
            return False
        rolling_365d_pos = self._v3_value(latest, "rolling_365d_pos")
        if pd.isna(rolling_365d_pos) or rolling_365d_pos > 0.70:
            return False
        return True


class V226AStrategy(V221EStrategy):
    """V2.26A: external recovery score cap layered over v2.21E buy targets."""

    VERSION_LABEL = "v2_26A"
    RECOVERY_EXTERNAL_BASE_CAP = 0.40
    RECOVERY_EXTERNAL_MID_CAP = 0.50
    RECOVERY_EXTERNAL_HIGH_CAP = 0.65

    @property
    def name(self) -> str:
        return "v2_26A"

    def _compose_target(
        self,
        symbol: str,
        tactical_target: float,
        raw_state: str,
        trend_risk: int,
        drawdown_risk: int,
        latest: pd.Series,
        price: float,
        side: str,
    ) -> float:
        target = super()._compose_target(
            symbol=symbol,
            tactical_target=tactical_target,
            raw_state=raw_state,
            trend_risk=trend_risk,
            drawdown_risk=drawdown_risk,
            latest=latest,
            price=price,
            side=side,
        )
        if side != "buy" or raw_state != "MIXED" or price <= 0:
            return target
        if target <= self.RECOVERY_EXTERNAL_BASE_CAP:
            return target
        cap = self._external_recovery_cap(latest, price, trend_risk, drawdown_risk)
        return min(target, cap)

    def _external_recovery_cap(
        self,
        latest: pd.Series,
        price: float,
        trend_risk: int,
        drawdown_risk: int,
    ) -> float:
        cap = self.RECOVERY_EXTERNAL_BASE_CAP
        if trend_risk > 1 or drawdown_risk > 1:
            return cap
        if str(latest.get("btc_regime", "")) == "BEAR":
            return cap

        macro_repair = self._macro_repair(latest)
        donchian_pos = self._value(latest, "donchian_pos")
        volume_strength = self._value(latest, "volume_strength", default=1.0)
        if (
            macro_repair
            and donchian_pos >= 0.54
            and volume_strength <= 1.00
            and not self._is_severe_extension(latest, price)
        ):
            cap = self.RECOVERY_EXTERNAL_MID_CAP

        if (
            trend_risk == 0
            and drawdown_risk == 0
            and self._recovery_overlay_score(latest, price) >= 7
            and self._ratio(latest, "ema72", "ema168") >= -0.03
            and donchian_pos >= 0.54
            and not self._is_extension_risk(latest, price)
        ):
            cap = self.RECOVERY_EXTERNAL_HIGH_CAP
        return cap

    def _recovery_overlay_score(self, latest: pd.Series, price: float) -> int:
        score = 0
        if self._ratio(latest, "ema72", "ema168") >= -0.03:
            score += 2
        if self._ratio(latest, "ema24", "ema168") >= -0.02:
            score += 1
        if self._macro_repair(latest):
            score += 1
        if self._value(latest, "donchian_pos") >= 0.54:
            score += 2
        if self._value(latest, "volume_strength", default=1.0) <= 0.75:
            score += 1
        rolling_pos = self._value(latest, "rolling_365d_pos")
        if 0.20 <= rolling_pos <= 0.75:
            score += 1
        if self._value(latest, "roc_20") < 0.20:
            score += 1
        if self._value(latest, "price_vs_ema168", default=self._price_vs(latest, price, "ema168")) >= -0.03:
            score += 1
        return score

    def _macro_repair(self, latest: pd.Series) -> bool:
        return (
            self._value(latest, "btc_price_vs_ema72") > 0
            or self._value(latest, "btc_ema24_slope") > 0
        )

    def _is_severe_extension(self, latest: pd.Series, price: float) -> bool:
        roc_20 = self._value(latest, "roc_20")
        price_vs_ema168 = self._value(
            latest,
            "price_vs_ema168",
            default=self._price_vs(latest, price, "ema168"),
        )
        donchian_pos = self._value(latest, "donchian_pos")
        rolling_pos = self._value(latest, "rolling_365d_pos")
        return bool(
            (roc_20 >= 0.30 and price_vs_ema168 >= 0.18 and donchian_pos >= 0.85)
            or (rolling_pos >= 0.80 and donchian_pos >= 0.90 and price_vs_ema168 >= 0.18)
        )

    def _is_extension_risk(self, latest: pd.Series, price: float) -> bool:
        roc_20 = self._value(latest, "roc_20")
        price_vs_ema168 = self._value(
            latest,
            "price_vs_ema168",
            default=self._price_vs(latest, price, "ema168"),
        )
        donchian_pos = self._value(latest, "donchian_pos")
        rolling_pos = self._value(latest, "rolling_365d_pos")
        return bool(
            (roc_20 >= 0.20 and price_vs_ema168 >= 0.12 and donchian_pos >= 0.75)
            or (rolling_pos >= 0.64 and donchian_pos >= 0.80 and price_vs_ema168 >= 0.12)
        )

    @staticmethod
    def _value(latest: pd.Series, column: str, default: float = float("nan")) -> float:
        value = latest.get(column, default)
        if pd.isna(value):
            return default
        return float(value)

    @classmethod
    def _ratio(cls, latest: pd.Series, numerator: str, denominator: str) -> float:
        num = cls._value(latest, numerator)
        den = cls._value(latest, denominator)
        if pd.isna(num) or pd.isna(den) or den <= 0:
            return float("nan")
        return num / den - 1.0

    @classmethod
    def _price_vs(cls, latest: pd.Series, price: float, column: str) -> float:
        den = cls._value(latest, column)
        if pd.isna(den) or den <= 0:
            return float("nan")
        return price / den - 1.0


class V226BStrategy(V226AStrategy):
    """V2.26B: external recovery overlay caps buy size, not strategy target."""

    VERSION_LABEL = "v2_26B"
    RECOVERY_EXTERNAL_BASE_CAP = 0.25
    RECOVERY_EXTERNAL_MID_CAP = 0.40
    RECOVERY_EXTERNAL_HIGH_CAP = 0.65
    RECOVERY_TARGET_GAP_MAX_CURRENT = 0.35
    RECOVERY_CAP_EPSILON = 0.001

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._overlay_current_pct = 0.0

    @property
    def name(self) -> str:
        return "v2_26B"

    def compute_actions(self, candles_by_symbol, portfolio, current_prices):
        symbol = strategy_utils.resolve_symbol(candles_by_symbol)
        self._overlay_current_pct = 0.0
        if symbol is not None:
            price = current_prices.get(symbol, 0.0)
            pos = portfolio.positions.get(symbol, PositionState())
            position_value = pos.quantity * price if price > 0 else 0.0
            total_value = portfolio.cash + position_value
            if total_value > 0:
                self._overlay_current_pct = position_value / total_value
        return super().compute_actions(candles_by_symbol, portfolio, current_prices)

    def _compose_target(
        self,
        symbol: str,
        tactical_target: float,
        raw_state: str,
        trend_risk: int,
        drawdown_risk: int,
        latest: pd.Series,
        price: float,
        side: str,
    ) -> float:
        return V221EStrategy._compose_target(
            self,
            symbol=symbol,
            tactical_target=tactical_target,
            raw_state=raw_state,
            trend_risk=trend_risk,
            drawdown_risk=drawdown_risk,
            latest=latest,
            price=price,
            side=side,
        )

    def _adjust_buy_execution(
        self,
        latest: pd.Series,
        price: float,
        raw_state: str,
        buy_setup: str,
        max_buy: float,
        confirmed_state: str | None = None,
    ) -> tuple[float, str]:
        max_buy, guard = super()._adjust_buy_execution(
            latest=latest,
            price=price,
            raw_state=raw_state,
            buy_setup=buy_setup,
            max_buy=max_buy,
            confirmed_state=confirmed_state,
        )
        if not self._should_apply_external_recovery_overlay(
            latest=latest,
            price=price,
            raw_state=raw_state,
            confirmed_state=confirmed_state,
            buy_setup=buy_setup,
        ):
            return max_buy, guard

        current_pct = self._overlay_current_pct
        # Risk scores are not available at this hook; the overlay is deliberately
        # structural here and only caps buy size.
        cap = self._external_recovery_cap(
            latest=latest,
            price=price,
            trend_risk=0,
            drawdown_risk=0,
        )
        allowed_buy = max(0.0, cap - current_pct)
        if allowed_buy + self.RECOVERY_CAP_EPSILON < max_buy:
            max_buy = max(0.0, allowed_buy)
            guard = self._join_guard(guard, f"{self.VERSION_LABEL}_external_cap_t{cap:.0%}")
        return max_buy, guard

    def _external_recovery_cap(
        self,
        latest: pd.Series,
        price: float,
        trend_risk: int,
        drawdown_risk: int,
    ) -> float:
        cap = self.RECOVERY_EXTERNAL_BASE_CAP
        if str(latest.get("btc_regime", "")) == "BEAR":
            return cap

        macro_repair = self._macro_repair(latest)
        donchian_pos = self._value(latest, "donchian_pos")
        volume_strength = self._value(latest, "volume_strength", default=1.0)
        ema72_vs_ema168 = self._ratio(latest, "ema72", "ema168")
        if (
            macro_repair
            and donchian_pos >= 0.54
            and ema72_vs_ema168 >= -0.03
            and volume_strength <= 1.00
            and not self._is_severe_extension(latest, price)
        ):
            cap = self.RECOVERY_EXTERNAL_MID_CAP

        if (
            self._recovery_overlay_score(latest, price) >= 7
            and ema72_vs_ema168 >= -0.03
            and donchian_pos >= 0.54
            and not self._is_extension_risk(latest, price)
        ):
            cap = self.RECOVERY_EXTERNAL_HIGH_CAP
        return cap

    def _should_apply_external_recovery_overlay(
        self,
        latest: pd.Series,
        price: float,
        raw_state: str,
        confirmed_state: str | None,
        buy_setup: str,
    ) -> bool:
        if raw_state != "MIXED" or confirmed_state != "MIXED":
            return False
        if buy_setup == "safe-recovery":
            return True
        if buy_setup == "target-gap" and self._overlay_current_pct < self.RECOVERY_TARGET_GAP_MAX_CURRENT:
            return True
        return False


class V226CStrategy(V226BStrategy):
    """V2.26C: cap safe-recovery, but only cap weak low-position target-gap buys."""

    VERSION_LABEL = "v2_26C"
    WEAK_TARGET_GAP_MIN_FLAGS = 3

    @property
    def name(self) -> str:
        return "v2_26C"

    def _should_apply_external_recovery_overlay(
        self,
        latest: pd.Series,
        price: float,
        raw_state: str,
        confirmed_state: str | None,
        buy_setup: str,
    ) -> bool:
        if raw_state != "MIXED" or confirmed_state != "MIXED":
            return False
        if buy_setup == "safe-recovery":
            return True
        if buy_setup != "target-gap":
            return False
        if self._overlay_current_pct >= self.RECOVERY_TARGET_GAP_MAX_CURRENT:
            return False
        return self._weak_recovery_structure_score(latest, price) >= self.WEAK_TARGET_GAP_MIN_FLAGS

    def _weak_recovery_structure_score(self, latest: pd.Series, price: float) -> int:
        score = 0
        if self._ratio(latest, "ema72", "ema168") < -0.03:
            score += 1
        if self._value(latest, "ema168_slope") < 0:
            score += 1
        if self._value(latest, "donchian_pos") < 0.54:
            score += 1
        if self._value(latest, "roc_20") < 0.08:
            score += 1
        if self._value(latest, "dd_from_120d_high") > 0.35:
            score += 1
        return score


class V226DStrategy(V226CStrategy):
    """V2.26D: only cap structurally weak safe-recovery buys."""

    VERSION_LABEL = "v2_26D"

    @property
    def name(self) -> str:
        return "v2_26D"

    def _should_apply_external_recovery_overlay(
        self,
        latest: pd.Series,
        price: float,
        raw_state: str,
        confirmed_state: str | None,
        buy_setup: str,
    ) -> bool:
        if raw_state != "MIXED" or confirmed_state != "MIXED":
            return False
        if buy_setup != "safe-recovery":
            return False
        return self._weak_recovery_structure_score(latest, price) >= self.WEAK_TARGET_GAP_MIN_FLAGS


class V226EStrategy(V226BStrategy):
    """V2.26E: cap only low-position target-gap weak-range recovery buys."""

    VERSION_LABEL = "v2_26E"
    RECOVERY_EXTERNAL_BASE_CAP = 0.30

    @property
    def name(self) -> str:
        return "v2_26E"

    def _external_recovery_cap(
        self,
        latest: pd.Series,
        price: float,
        trend_risk: int,
        drawdown_risk: int,
    ) -> float:
        return self.RECOVERY_EXTERNAL_BASE_CAP

    def _should_apply_external_recovery_overlay(
        self,
        latest: pd.Series,
        price: float,
        raw_state: str,
        confirmed_state: str | None,
        buy_setup: str,
    ) -> bool:
        if raw_state != "MIXED" or confirmed_state != "MIXED":
            return False
        if buy_setup != "target-gap":
            return False
        if self._overlay_current_pct >= self.RECOVERY_TARGET_GAP_MAX_CURRENT:
            return False
        return self._is_low_quality_target_gap_context(latest)

    def _is_low_quality_target_gap_context(self, latest: pd.Series) -> bool:
        mid_history_weak_range = (
            self._value(latest, "rolling_365d_pos") >= 0.3198
            and self._value(latest, "donchian_pos") < 0.54
        )
        deep_ema_weak_low_volume = (
            self._ratio(latest, "ema72", "ema168") <= -0.05
            and self._value(latest, "volume_strength", default=1.0) <= 0.8709
        )
        return bool(mid_history_weak_range or deep_ema_weak_low_volume)


class V226FStrategy(V226EStrategy):
    """V2.26F: cap only BTC-hot, local-EMA-weak low-position target-gap buys."""

    VERSION_LABEL = "v2_26F"

    @property
    def name(self) -> str:
        return "v2_26F"

    def _is_low_quality_target_gap_context(self, latest: pd.Series) -> bool:
        return bool(
            self._value(latest, "btc_price_vs_ema72") >= 0.096
            and self._ratio(latest, "ema72", "ema168") <= -0.05
        )


class V227AStrategy(V221EStrategy):
    """V2.27A: relax tiny low-position MIXED target-gap buys."""

    VERSION_LABEL = "v2_27A"
    RELAXED_TINY_MAX_CURRENT = 0.35
    RELAXED_TINY_MIN_TARGET_GAP = 0.05
    RELAXED_TINY_MIN_BUY = 0.05

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._overlay_current_pct = 0.0

    @property
    def name(self) -> str:
        return "v2_27A"

    def compute_actions(self, candles_by_symbol, portfolio, current_prices):
        symbol = strategy_utils.resolve_symbol(candles_by_symbol)
        self._overlay_current_pct = 0.0
        if symbol is not None:
            price = current_prices.get(symbol, 0.0)
            pos = portfolio.positions.get(symbol, PositionState())
            position_value = pos.quantity * price if price > 0 else 0.0
            total_value = portfolio.cash + position_value
            if total_value > 0:
                self._overlay_current_pct = position_value / total_value
        return super().compute_actions(candles_by_symbol, portfolio, current_prices)

    def _adjust_buy_execution(
        self,
        latest: pd.Series,
        price: float,
        raw_state: str,
        buy_setup: str,
        max_buy: float,
        confirmed_state: str | None = None,
    ) -> tuple[float, str]:
        if not self._is_relaxed_tiny_target_gap_context(
            raw_state=raw_state,
            confirmed_state=confirmed_state,
            buy_setup=buy_setup,
            max_buy=max_buy,
        ):
            return super()._adjust_buy_execution(
                latest=latest,
                price=price,
                raw_state=raw_state,
                buy_setup=buy_setup,
                max_buy=max_buy,
                confirmed_state=confirmed_state,
            )

        adjusted, guard = V212AStrategy._adjust_buy_execution(
            self,
            latest=latest,
            price=price,
            raw_state=raw_state,
            buy_setup=buy_setup,
            max_buy=max_buy,
            confirmed_state=confirmed_state,
        )
        if 0.0 < adjusted < self.RELAXED_TINY_MIN_BUY:
            return 0.0, self._join_guard(guard, f"{self.VERSION_LABEL}_relaxed_tiny_floor_skipped")
        return adjusted, self._join_guard(guard, f"{self.VERSION_LABEL}_relaxed_tiny_target_gap")

    def _is_relaxed_tiny_target_gap_context(
        self,
        raw_state: str,
        confirmed_state: str | None,
        buy_setup: str,
        max_buy: float,
    ) -> bool:
        if raw_state != "MIXED" or confirmed_state != "MIXED":
            return False
        if buy_setup != "target-gap":
            return False
        if self._overlay_current_pct >= self.RELAXED_TINY_MAX_CURRENT:
            return False
        return max_buy >= self.RELAXED_TINY_MIN_TARGET_GAP


class V227BStrategy(V227AStrategy):
    """V2.27B: relaxed tiny target-gap buys with a narrow external deny gate."""

    VERSION_LABEL = "v2_27B"

    @property
    def name(self) -> str:
        return "v2_27B"

    def _adjust_buy_execution(
        self,
        latest: pd.Series,
        price: float,
        raw_state: str,
        buy_setup: str,
        max_buy: float,
        confirmed_state: str | None = None,
    ) -> tuple[float, str]:
        if self._is_relaxed_tiny_target_gap_context(
            raw_state=raw_state,
            confirmed_state=confirmed_state,
            buy_setup=buy_setup,
            max_buy=max_buy,
        ) and self._external_deny_target_gap(latest):
            return 0.0, f"{self.VERSION_LABEL}_external_deny_f"
        return super()._adjust_buy_execution(
            latest=latest,
            price=price,
            raw_state=raw_state,
            buy_setup=buy_setup,
            max_buy=max_buy,
            confirmed_state=confirmed_state,
        )

    def _external_deny_target_gap(self, latest: pd.Series) -> bool:
        return bool(
            V226FStrategy._value(latest, "btc_price_vs_ema72") >= 0.096
            and V226FStrategy._ratio(latest, "ema72", "ema168") <= -0.05
        )


class V227CStrategy(V227AStrategy):
    """V2.27C: relax tiny target-gap buys only in high-quality MIXED recovery."""

    VERSION_LABEL = "v2_27C"

    @property
    def name(self) -> str:
        return "v2_27C"

    def _is_relaxed_tiny_target_gap_context(
        self,
        raw_state: str,
        confirmed_state: str | None,
        buy_setup: str,
        max_buy: float,
    ) -> bool:
        if not super()._is_relaxed_tiny_target_gap_context(
            raw_state=raw_state,
            confirmed_state=confirmed_state,
            buy_setup=buy_setup,
            max_buy=max_buy,
        ):
            return False
        latest = getattr(self, "_latest_bar", None)
        price = getattr(self, "_current_price", 0.0)
        if latest is None or price <= 0:
            return False
        return self._is_high_quality_target_gap_context(latest, price)

    def _is_high_quality_target_gap_context(self, latest: pd.Series, price: float) -> bool:
        if str(latest.get("btc_regime", "")) == "BEAR":
            return False
        if V226FStrategy._value(latest, "btc_price_vs_ema72") < -0.02:
            return False
        if price <= V226FStrategy._value(latest, "ema24"):
            return False
        if V226FStrategy._ratio(latest, "ema24", "ema72") <= 0:
            return False
        if V226FStrategy._ratio(latest, "ema72", "ema168") < -0.10:
            return False
        if V226FStrategy._value(latest, "donchian_pos") < 0.54:
            return False
        if V226FStrategy._value(latest, "roc_20") < 0.08:
            return False
        if V226FStrategy._value(latest, "volume_strength", default=1.0) > 1.20:
            return False
        return True


class V227DStrategy(V227CStrategy):
    """V2.27D: ultra-conservative tiny relaxation after long trend turns up."""

    VERSION_LABEL = "v2_27D"

    @property
    def name(self) -> str:
        return "v2_27D"

    def _is_relaxed_tiny_target_gap_context(
        self,
        raw_state: str,
        confirmed_state: str | None,
        buy_setup: str,
        max_buy: float,
    ) -> bool:
        if self._is_post_override_target_gap(buy_setup):
            return False
        return super()._is_relaxed_tiny_target_gap_context(
            raw_state=raw_state,
            confirmed_state=confirmed_state,
            buy_setup=buy_setup,
            max_buy=max_buy,
        )

    def _is_high_quality_target_gap_context(self, latest: pd.Series, price: float) -> bool:
        if not super()._is_high_quality_target_gap_context(latest, price):
            return False
        return V226FStrategy._value(latest, "ema168_slope") >= 0
